void ApplicationShell::selectLinkedLevelMapEntities(bool targets)
{
	const QVector<LevelMapSelectionRef> linked = levelMapLinkedEntities(m_levelMapDocument, targets);
	const bool doom = m_levelMapDocument.format == LevelMapFormat::DoomWad;
	if (linked.isEmpty()) {
		statusBar()->showMessage(doom ? (targets ? tr("The selected lines tag no sector.") : tr("No line acts on the selected sectors."))
					      : (targets ? tr("The selection targets no entity.") : tr("No entity targets the selection.")));
		return;
	}
	setLevelMapSelection(&m_levelMapDocument, linked);
	refreshLevelMapWorkbench();
	const int count = static_cast<int>(linked.size());
	if (doom) {
		statusBar()->showMessage(targets ? tr("Selected the %n sector(s) the selected lines act on, by their tag.", nullptr, count)
						 : tr("Selected the %n line(s) that act on the selected sectors, by their tag.", nullptr, count));
		return;
	}
	statusBar()->showMessage(targets ? tr("Selected the %n entity(ies) the selection targets.", nullptr, count)
					 : tr("Selected the %n entity(ies) that target the selection.", nullptr, count));
}

