QString ApplicationShell::levelMapSkippedNote(const QStringList& skipped) const
{
	if (skipped.isEmpty()) {
		return {};
	}
	return QLatin1Char(' ') + tr("%n brush(es) left as they were; the first because: %1", nullptr, static_cast<int>(skipped.size())).arg(skipped.first());
}

void ApplicationShell::carveLevelMapSelectionFromUi()
{
	if (!levelMapSelectionClippable()) {
		statusBar()->showMessage(tr("Select the brushes to carve with."));
		return;
	}
	// Hidden brushes are left alone, as Radiant's subtract leaves them.
	QVector<int> hidden;
	if (m_levelMapViewport && m_levelMapViewport->hiddenCount() > 0) {
		for (const LevelMapBrush& brush : m_levelMapDocument.brushes) {
			if (m_levelMapViewport->isHidden(LevelMapSelectionKind::QuakeBrush, brush.id)) {
				hidden.push_back(brush.id);
			}
		}
	}
	int carved = 0;
	QString error;
	QStringList skipped;
	if (!carveLevelMapSelection(&m_levelMapDocument, &carved, &error, &skipped, hidden)) {
		statusBar()->showMessage(tr("Could not carve: %1").arg(error));
		return;
	}
	recordActivity(tr("Level map brushes carved"), tr("%n brush(es)", nullptr, carved), QStringLiteral("level-map"), OperationState::Warning,
		tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Carved %n brush(es); the carving brushes are still selected, ready to delete.", nullptr, carved)
		+ levelMapSkippedNote(skipped));
}

void ApplicationShell::hollowLevelMapSelectionFromUi()
{
	if (!levelMapSelectionClippable()) {
		statusBar()->showMessage(tr("Select brushes, or a brush entity, to hollow."));
		return;
	}
	const int grid = m_levelMapViewport ? std::max(1, m_levelMapViewport->gridSize()) : 8;
	bool ok = false;
	const int thickness = QInputDialog::getInt(this, tr("Hollow"), tr("Wall thickness (units)"), grid, 1, 4096, 1, &ok);
	if (!ok) {
		return;
	}
	int hollowed = 0;
	QString error;
	QStringList skipped;
	if (!hollowLevelMapSelection(&m_levelMapDocument, thickness, &hollowed, &error, &skipped)) {
		statusBar()->showMessage(tr("Could not hollow: %1").arg(error));
		return;
	}
	const int walls = static_cast<int>(m_levelMapDocument.selection.size());
	recordActivity(tr("Level map brushes hollowed"), tr("%n wall(s)", nullptr, walls), QStringLiteral("level-map"), OperationState::Warning,
		tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Hollowed %n brush(es) into walls %1 units thick.", nullptr, hollowed).arg(thickness) + levelMapSkippedNote(skipped));
}

void ApplicationShell::setLevelMapClipMode(bool enabled)
{
	if (!m_levelMapViewport) {
		return;
	}
	const bool quakeFamilyMap = m_levelMapDocument.format == LevelMapFormat::QuakeMap || m_levelMapDocument.format == LevelMapFormat::Quake3Map;
	if (enabled && !quakeFamilyMap) {
		statusBar()->showMessage(tr("Open a Quake-family .map to clip brushes."));
		if (QAction* tool = m_commands->action(QStringLiteral("map.clipTool"))) {
			tool->setChecked(false);
		}
		return;
	}
	// The clip line is drawn in the 2D view, so a single 3D view gives way
	// to it, as Draw Sector's does.
	if (enabled && !levelMap2DShowing()) {
		setLevelMap3D(false);
	}
	m_levelMapViewport->setClipMode(enabled);
	if (enabled) {
		m_levelMapViewport->setFocus(Qt::ShortcutFocusReason);
	}
}

bool ApplicationShell::levelMapSelectionClippable() const
{
	for (const LevelMapSelectionRef& ref : m_levelMapDocument.selection) {
		if (ref.kind == LevelMapSelectionKind::QuakeBrush) {
			return true;
		}
		if (ref.kind == LevelMapSelectionKind::Entity) {
			for (const LevelMapBrush& brush : m_levelMapDocument.brushes) {
				if (brush.entityId == ref.objectId) {
					return true;
				}
			}
		}
	}
	return false;
}

bool ApplicationShell::applyLevelMapClip(const LevelMapVec3& a, const LevelMapVec3& b, const LevelMapVec3& c, LevelMapClipKeep keep)
{
	int clipped = 0;
	QString error;
	QStringList skipped;
	if (!clipLevelMapSelection(&m_levelMapDocument, a, b, c, keep, &clipped, &error, &skipped)) {
		statusBar()->showMessage(tr("Could not clip: %1").arg(error));
		return false;
	}
	const bool both = keep == LevelMapClipKeep::Both;
	recordActivity(both ? tr("Level map brushes split") : tr("Level map brushes clipped"), tr("%n brush(es)", nullptr, clipped),
		QStringLiteral("level-map"), OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage((both ? tr("Split %n brush(es) in two.", nullptr, clipped) : tr("Clipped %n brush(es).", nullptr, clipped))
		+ levelMapSkippedNote(skipped));
	return true;
}

void ApplicationShell::clipLevelMapSelectionFromViewport(const LevelMapVec3& a, const LevelMapVec3& b, const LevelMapVec3& c, int keep)
{
	if (applyLevelMapClip(a, b, c, static_cast<LevelMapClipKeep>(keep)) && m_levelMapViewport) {
		// The line has done its work; the tool stays on for the next cut.
		m_levelMapViewport->clearClipLine();
	}
}

void ApplicationShell::clipLevelMapSelectionFromUi()
{
	if (!levelMapSelectionClippable()) {
		statusBar()->showMessage(tr("Select brushes, or a brush entity, to clip."));
		return;
	}
	LevelMapVec3 low;
	LevelMapVec3 high;
	levelMapSelectionBounds(m_levelMapDocument, &low, &high);
	const int grid = m_levelMapViewport ? std::max(1, m_levelMapViewport->gridSize()) : 16;

	QDialog dialog(this);
	dialog.setObjectName(QStringLiteral("clipSelectionDialog"));
	dialog.setWindowTitle(tr("Clip Selection"));
	dialog.setAccessibleName(tr("Clip Selection"));
	auto* layout = new QVBoxLayout(&dialog);
	auto* form = new QFormLayout;
	auto* axis = new QComboBox(&dialog);
	axis->setObjectName(QStringLiteral("clipAxis"));
	axis->addItem(tr("x (a plane square to x)"));
	axis->addItem(tr("y (a plane square to y)"));
	axis->addItem(tr("z (a plane square to z)"));
	axis->setAccessibleName(tr("Axis"));
	// The view's own horizontal axis first: what a vertical line on screen cuts.
	int viewAxis = 0;
	if (m_levelMapViewport && m_levelMapViewport->projection() == MapViewportProjection::SideZY) {
		viewAxis = 1;
	}
	axis->setCurrentIndex(viewAxis);
	form->addRow(tr("Axis"), axis);
	auto* position = new QDoubleSpinBox(&dialog);
	position->setObjectName(QStringLiteral("clipPosition"));
	position->setDecimals(3);
	position->setRange(-131072.0, 131072.0);
	position->setSingleStep(grid);
	position->setSuffix(tr(" units"));
	position->setAccessibleName(tr("Position"));
	const auto middle = [&low, &high, grid](int index) {
		const double lows[3] {low.x, low.y, low.z};
		const double highs[3] {high.x, high.y, high.z};
		return snapLevelMapCoordinate((lows[index] + highs[index]) * 0.5, grid);
	};
	position->setValue(low.valid ? middle(viewAxis) : 0.0);
	connect(axis, &QComboBox::currentIndexChanged, &dialog, [&low, position, middle](int index) {
		if (low.valid) {
			position->setValue(middle(index));
		}
	});
	form->addRow(tr("Position"), position);
	auto* keep = new QComboBox(&dialog);
	keep->setObjectName(QStringLiteral("clipKeep"));
	keep->addItem(tr("The part below the plane"), static_cast<int>(LevelMapClipKeep::Back));
	keep->addItem(tr("The part above the plane"), static_cast<int>(LevelMapClipKeep::Front));
	keep->addItem(tr("Both parts, as two brushes"), static_cast<int>(LevelMapClipKeep::Both));
	keep->setAccessibleName(tr("Keep"));
	form->addRow(tr("Keep"), keep);
	layout->addLayout(form);
	auto* buttons = new QDialogButtonBox(QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
	buttons->button(QDialogButtonBox::Ok)->setText(tr("Clip"));
	connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
	connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
	layout->addWidget(buttons);
	position->setFocus(Qt::OtherFocusReason);
	position->selectAll();
	if (dialog.exec() != QDialog::Accepted) {
		return;
	}
	// Three points on the plane, stepping along the next two axes in the
	// order that puts its front up the chosen one: above is the front.
	const int chosen = axis->currentIndex();
	LevelMapVec3 a {0.0, 0.0, 0.0, true};
	double* first[3] {&a.x, &a.y, &a.z};
	*first[chosen] = position->value();
	LevelMapVec3 b = a;
	LevelMapVec3 c = a;
	double* bAxes[3] {&b.x, &b.y, &b.z};
	double* cAxes[3] {&c.x, &c.y, &c.z};
	*bAxes[(chosen + 1) % 3] += 1.0;
	*cAxes[(chosen + 2) % 3] += 1.0;
	applyLevelMapClip(a, b, c, static_cast<LevelMapClipKeep>(keep->currentData().toInt()));
}

void ApplicationShell::setLevelMap3D(bool enabled)
{
	if (!m_levelMapViews || !m_levelMap3D || !m_levelMapViewport) {
		return;
	}
	restoreLevelViewWorkspace();
	if (m_levelMap3DButton && m_levelMap3DButton->isChecked() != enabled) {
		const QSignalBlocker blocker(m_levelMap3DButton);
		m_levelMap3DButton->setChecked(enabled);
	}
	if (QAction* toggle = m_commands ? m_commands->action(QStringLiteral("map.toggle3D")) : nullptr) {
		toggle->setChecked(enabled);
	}
	// A single view swaps between 3D and 2D; beside the camera (Radiant's
	// layout) the 2D view stays and only the camera comes and goes.
	const bool show2D = !enabled || m_levelViewLayout == LevelViewLayout::CameraAndPlan || levelViewLayoutHasThreePlans(m_levelViewLayout);
	if (!show2D && m_levelMapViewport) {
		// Whatever the 2D view was in the middle of stops, its tools with it.
		m_levelMapViewport->cancelInteraction();
		m_levelMapViewport->setClipMode(false);
		m_levelMapViewport->setDrawMode(false);
	}
	m_levelMap3D->setVisible(enabled);
	if (m_levelPreviewStatus) { m_levelPreviewStatus->setVisible(enabled); }
	m_levelMapViewport->setVisible(show2D);
	if (levelViewLayoutHasThreePlans(m_levelViewLayout)) {
		for (auto* view : m_levelPlanViews) { view->show(); }
	}
	if (m_levelViewLayout == LevelViewLayout::CameraAbovePlans || m_levelViewLayout == LevelViewLayout::CameraBesidePlans) { m_levelMapUpperViews->setVisible(enabled); }
	// Projection and display flags belong to plans; grid, snap and framing
	// also drive camera authoring, including a maximized camera pane.
	for (QWidget* control : std::initializer_list<QWidget*> {m_levelMapProjection,
		     findChild<QToolButton*>(QStringLiteral("levelMapShowButton"))}) {
		if (control) {
			control->setEnabled(show2D);
		}
	}
	for (QWidget* control : std::initializer_list<QWidget*> {m_levelMapGrid, m_levelMapSnap,
		findChild<QToolButton*>(QStringLiteral("levelMapZoomSelection"))}) {
		if (control) { control->setEnabled(m_levelMapDocument.format != LevelMapFormat::Unknown); }
	}
	if (enabled) {
		// The same map keeps its camera, so stepping between views never
		// loses the place the user flew to.
		refreshLevelMap3D();
		if (!show2D) {
			m_levelMap3D->setFocus(Qt::OtherFocusReason);
		}
	} else if (m_levelMapViewport) {
		m_levelMapViewport->setFocus(Qt::OtherFocusReason);
	}
	if (m_levelMapHover) {
		m_levelMapHover->setText(enabled && !show2D ? m_levelMap3D->hoverSummary() : m_levelMapViewport->hoverSummary());
	}
	refreshLevelCameraMarker();
	refreshCommandEnablement();
}

// ---------------------------------------------------------------------------
// Level editor profiles: controls, layout, and the camera's link to the 2D view
// ---------------------------------------------------------------------------

bool ApplicationShell::levelMap3DShowing() const
{
	return m_levelMap3D && !m_levelMap3D->isHidden();
}

bool ApplicationShell::levelMap2DShowing() const
{
	// MapViewport's own isHidden() asks about map objects.
	return m_levelMapViewport && !m_levelMapViewport->QWidget::isHidden();
}

void ApplicationShell::refreshLevelViewportShortcuts()
{
	if (!m_commands) { return; }
	QList<QKeySequence> reserved;
	for (const auto& id : m_commands->commandIds()) {
		const auto* action = m_commands->action(id);
		if (action && (id.startsWith(QLatin1String("map.")) || action->shortcutContext() == Qt::WindowShortcut)) {
			reserved.append(action->shortcuts());
		}
	}
	for (auto* view : m_levelPlanViews) { view->setReservedShortcuts(reserved); }
}

void ApplicationShell::applyLevelEditorProfile(bool profileChanged, bool preserveWorkspace)
{
	if (!preserveWorkspace) { m_levelBookmarkLayout = false; }
	const EditorProfileDescriptor profile = [this]() {
		EditorProfileDescriptor descriptor;
		if (!editorProfileForId(m_settings.selectedEditorProfileId(), &descriptor)) {
			editorProfileForId(defaultEditorProfileId(), &descriptor);
		}
		return descriptor;
	}();
	LevelViewLayout effectiveLayout = profile.controls.layout;
	levelViewLayoutForId(m_settings.levelViewLayoutPreference(), &effectiveLayout);
	const bool layoutChanged = profileChanged || !m_levelControlsApplied || m_levelViewLayout != effectiveLayout;
	QString gestureError;
	m_levelControls = m_settings.effectiveLevelEditorControls(profile.id, &gestureError);
	m_levelControlsProfileName = profile.lineage;
	m_levelControlsApplied = true;
	refreshLevelViewportShortcuts();
	for (auto* view : m_levelPlanViews) {
		view->setControls(m_levelControls.plan);
		view->setControlsHelp(levelControlsAccessibleText(QStringLiteral("plan"), tr("2D view")));
	}
	if (m_levelMap3D) {
		m_levelMap3D->setCameraControls(m_levelControls.camera, preserveWorkspace);
		m_levelMap3D->setControlsHelp(levelControlsAccessibleText(QStringLiteral("camera"), tr("3D view")));
		refreshLevelCameraBrush();
	}
	if (layoutChanged && !preserveWorkspace) {
		applyLevelViewLayout(effectiveLayout);
	}
	if (profileChanged && m_levelMapGrid) {
		// A new profile brings its own grid, as a fresh start in that editor
		// would.
		const int index = m_levelMapGrid->findData(m_levelControls.defaultGridUnits);
		if (index >= 0) {
			m_levelMapGrid->setCurrentIndex(index);
		}
	}
	if (m_levelControlsButton) {
		m_levelControlsButton->setText(profile.lineage);
		m_levelControlsButton->setToolTip(tr("Level editor controls: %1. Choose another editor's controls, or see every mouse gesture and key.").arg(profile.displayName));
		m_levelControlsButton->setAccessibleDescription(m_levelControlsButton->toolTip());
		if (QMenu* menu = m_levelControlsButton->menu()) {
			for (QAction* choice : menu->actions()) {
				if (choice->isCheckable()) {
					choice->setChecked(normalizedEditorProfileId(choice->data().toString()) == normalizedEditorProfileId(profile.id));
				}
			}
		}
	}
	refreshLevelCameraMarker();
	applyLevelSidebarProfile();
	if (!gestureError.isEmpty()) {
		statusBar()->showMessage(tr("Gesture preferences could not be applied: %1. Profile defaults are in use.").arg(gestureError), 12000);
	}
	if (profileChanged && gestureError.isEmpty()) {
		statusBar()->showMessage(tr("Levels now use %1 controls: %2. Controls on the Levels tool bar lists every gesture and key.")
				.arg(profile.displayName, levelViewLayoutDisplayName(effectiveLayout)),
			6000);
	}
}

QString ApplicationShell::levelControlsAccessibleText(const QString& section, const QString& view) const
{
	QStringList parts;
	for (const LevelEditorControlRow& row : levelEditorControlRows(m_levelControls)) {
		if (row.section == section) {
			parts << tr("%1: %2").arg(row.action, row.gesture);
		}
	}
	return tr("%1 with %2 controls. %3.").arg(view, m_levelControlsProfileName, parts.join(QStringLiteral("; ")));
}

void ApplicationShell::cycleLevelMapView()
{
	if (!m_levelMapViewport || !m_levelMap3D || !m_levelMapProjection) {
		return;
	}
	// With both views showing, the 2D view steps through its planes. With
	// one, that view steps 3D, Top, Front, Side, and back to 3D, as
	// TrenchBroom's one-pane layout does.
	if (levelMap3DShowing() && levelMap2DShowing()) {
		stepLevelMapProjection();
		return;
	}
	if (levelMap3DShowing()) {
		m_levelMapProjection->setCurrentIndex(0);
		setLevelMap3D(false);
		statusBar()->showMessage(tr("View: %1").arg(m_levelMapProjection->currentText()), 2000);
		return;
	}
	if (m_levelMapProjection->currentIndex() >= m_levelMapProjection->count() - 1) {
		setLevelMap3D(true);
		statusBar()->showMessage(tr("View: 3D"), 2000);
		return;
	}
	stepLevelMapProjection();
}

void ApplicationShell::stepLevelMapProjection()
{
	if (!m_levelMapProjection) {
		return;
	}
	showLevelMapProjection((m_levelMapProjection->currentIndex() + 1) % std::max(1, m_levelMapProjection->count()));
}

void ApplicationShell::showLevelMapProjection(int index)
{
	if (!m_levelMapProjection || index < 0 || index >= m_levelMapProjection->count()) {
		return;
	}
	m_levelMapProjection->setCurrentIndex(index);
	if (levelViewLayoutHasThreePlans(m_levelViewLayout)) {
		activateLevelPlanViewport(m_levelPlanViews.value(index));
		m_levelMapViewport->setFocus(Qt::OtherFocusReason);
	}
	// A single view shows the plane asked for instead of the 3D view.
	if (!levelMap2DShowing()) {
		setLevelMap3D(false);
	}
	statusBar()->showMessage(tr("View: %1").arg(m_levelMapProjection->currentText()), 2000);
}

void ApplicationShell::setLevelMapGridUnits(int units)
{
	if (!m_levelMapGrid) {
		return;
	}
	const int index = m_levelMapGrid->findData(units);
	if (index >= 0) {
		m_levelMapGrid->setCurrentIndex(index);
		statusBar()->showMessage(tr("Grid: %1 units.").arg(units), 2000);
	}
}

void ApplicationShell::frameLevelMapSelection()
{
	if (m_levelMapDocument.format == LevelMapFormat::Unknown) {
		return;
	}
	frameLevelPlanViews();
	LevelMapVec3 mins;
	LevelMapVec3 maxs;
	if (!levelMap3DShowing() || !m_levelMap3D->isPerspective() || !levelMapSelectionBounds(m_levelMapDocument, &mins, &maxs)) {
		return;
	}
	// The camera keeps its heading and backs off along it until the
	// selection's bounding sphere fills the view.
	const double centre[3] {(mins.x + maxs.x) * 0.5, (mins.y + maxs.y) * 0.5, (mins.z + maxs.z) * 0.5};
	const double radius = std::max(16.0, 0.5 * std::sqrt(std::pow(maxs.x - mins.x, 2.0) + std::pow(maxs.y - mins.y, 2.0) + std::pow(maxs.z - mins.z, 2.0)));
	const double distance = radius / std::sin(std::clamp(m_levelMap3D->fieldOfView(), 15.0, 150.0) * std::numbers::pi / 360.0) * 1.1;
	const double yaw = m_levelMap3D->cameraYaw() * std::numbers::pi / 180.0;
	const double pitch = m_levelMap3D->cameraPitch() * std::numbers::pi / 180.0;
	ModelVec3 position;
	position.x = static_cast<float>(centre[0] - std::cos(pitch) * std::cos(yaw) * distance);
	position.y = static_cast<float>(centre[1] - std::cos(pitch) * std::sin(yaw) * distance);
	position.z = static_cast<float>(centre[2] - std::sin(pitch) * distance);
	// Explicit framing keeps the plans on the selection. Camera follow resumes
	// with the next camera navigation instead of shifting them to this eye point.
	const QScopedValueRollback<bool> framing(m_applyingLevelViewNavigation, true);
	m_levelMap3D->setCameraView(position, m_levelMap3D->cameraYaw(), m_levelMap3D->cameraPitch());
}

void ApplicationShell::isolateLevelMapSelection()
{
	if (!m_levelMapViewport || m_levelMapDocument.selection.isEmpty()) {
		statusBar()->showMessage(tr("Select what to keep in view first."));
		return;
	}
	const QVector<LevelMapSelectionRef> keep = m_levelMapDocument.selection;
	// Everything else is what Invert Selection would pick; that is hidden,
	// and the selection comes back.
	selectAllLevelMapObjects(true);
	const int hidden = m_levelMapDocument.selection.isEmpty() ? 0 : m_levelMapViewport->hideSelection();
	QString error;
	setLevelMapSelection(&m_levelMapDocument, keep, &error);
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Isolated the selection: %n other object(s) hidden. Show All Hidden brings them back.", nullptr, hidden));
}

QString ApplicationShell::levelBrushMaterial() const
{
	// The shared picker also receives texture-browser selections and samples.
	// Fall back to the last drawing material, map usage and the placeholder.
	QString texture = m_levelPaintMaterial.trimmed();
	if (texture.isEmpty() && m_levelMapTextures && m_levelMapTextures->currentItem() && m_levelMapTextures->currentItem()->isSelected()) {
		texture = m_levelMapTextures->currentItem()->data(Qt::UserRole).toString();
		if (texture.isEmpty()) {
			texture = m_levelMapTextures->currentItem()->text();
		}
	}
	if (texture.isEmpty()) {
		texture = m_lastDrawnBrushTexture;
	}
	if (texture.isEmpty()) {
		int mostUses = 0;
		for (const LevelMapTextureUse& use : levelMapTextureUsage(m_levelMapDocument)) {
			if (use.count > mostUses) {
				texture = use.name;
				mostUses = use.count;
			}
		}
	}
	if (texture.isEmpty()) {
		texture = QStringLiteral("__TB_empty");
	}
	return texture;
}

void ApplicationShell::drawLevelMapBrushFromViewport(const LevelMapVec3& mins, const LevelMapVec3& maxs, int depthAxis)
{
	// On a Doom map the box drawn in shape drawing is the sector shape's.
	if (m_levelMapDocument.format == LevelMapFormat::DoomWad) {
		if (m_levelMapViewport && m_levelMapViewport->shapeDrawMode()) {
			addLevelSectorShape(mins.x, mins.y, maxs.x, maxs.y);
		}
		return;
	}
	if (m_levelMapDocument.format != LevelMapFormat::QuakeMap && m_levelMapDocument.format != LevelMapFormat::Quake3Map) { return; }
	// The shape chosen in the Shapes tab fills the box drawn, as the block
	// tool in Hammer makes the object bar's primitive.
	if (m_levelShape != QLatin1String("box")) {
		addLevelShapeFromUi(mins, maxs, depthAxis >= 0 ? depthAxis : levelShapeViewAxis(), true);
		return;
	}
	const QString texture = levelBrushMaterial();
	LevelPlacementRequest request;
	request.operation = LevelPlacementOperation::AddBrush;
	request.primitive.mins = mins;
	request.primitive.maxs = maxs;
	request.primitive.texture = texture;
	QString error;
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(tr("Could not draw the brush: %1").arg(error));
		return;
	}
	const int brushId = m_levelMapDocument.selectedObjectId;
	m_lastDrawnBrushTexture = texture;
	rememberLevelMaterial(texture);
	recordActivity(tr("Level map brush drawn"), QStringLiteral("brush:%1").arg(brushId), QStringLiteral("level-map"), OperationState::Warning,
		tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Drew brush:%1, %2 by %3 by %4, in %5.")
			.arg(brushId)
			.arg(maxs.x - mins.x, 0, 'g', 8)
			.arg(maxs.y - mins.y, 0, 'g', 8)
			.arg(maxs.z - mins.z, 0, 'g', 8)
			.arg(texture),
		5000);
}

void ApplicationShell::pickLevelMap3D(int triangle, int pick)
{
	const auto mode = static_cast<ModelViewportPick>(pick);
	QString error;
	if (triangle < 0 || triangle >= m_levelMap3DOwners.size()) {
		// A plain click on nothing clears the selection, as a click on empty
		// space in the 2D view does.
		if (mode == ModelViewportPick::Replace && !m_levelMapDocument.selection.isEmpty()) {
			setLevelMapSelection(&m_levelMapDocument, {}, &error);
			refreshLevelMapWorkbench();
		}
		return;
	}
	const LevelMapSelectionRef owner = m_levelMap3DOwners.at(triangle);
	const int face = m_levelMap3DFaces.value(triangle, -1);
	if (mode == ModelViewportPick::Replace) {
		// triangleClicked() has settled it.
		return;
	}
	QVector<LevelMapSelectionRef> selection = m_levelMapDocument.selection;
	const auto at = std::find_if(selection.begin(), selection.end(), [&owner](const LevelMapSelectionRef& ref) {
		return ref.kind == owner.kind && ref.objectId == owner.objectId;
	});
	const bool wasSelected = at != selection.end();
	switch (mode) {
	case ModelViewportPick::Toggle:
	case ModelViewportPick::FaceToggle:
		if (wasSelected) {
			selection.erase(at);
		} else {
			selection.push_back(owner);
		}
		break;
	case ModelViewportPick::Face:
		selection = {owner};
		break;
	case ModelViewportPick::Replace:
		break;
	}
	if (!setLevelMapSelection(&m_levelMapDocument, selection, &error)) {
		statusBar()->showMessage(error);
		return;
	}
	const bool picksFace = (mode == ModelViewportPick::Face || mode == ModelViewportPick::FaceToggle) && owner.kind == LevelMapSelectionKind::QuakeBrush && face >= 0;
	if (picksFace && (mode == ModelViewportPick::Face || !wasSelected)) {
		m_inspectorFocus = QStringLiteral("face:%1:%2").arg(owner.objectId).arg(face);
		showLevelSidebarPage(QStringLiteral("inspector"));
	}
	refreshLevelMapWorkbench();
	if (picksFace) {
		statusBar()->showMessage(tr("Face %1 of %2 is in the Inspector.").arg(face + 1).arg(levelMapSelectionRefId(owner)));
	} else {
		statusBar()->showMessage(wasSelected ? tr("Took %1 out of the selection.").arg(levelMapSelectionRefId(owner))
						   : tr("Added %1 to the selection.").arg(levelMapSelectionRefId(owner)));
	}
}

void ApplicationShell::showLevelMap3DContextMenu(const QPoint& position)
{
	if (!m_levelMap3D) {
		return;
	}
	showLevelMapContextMenu(m_levelMap3D->mapToGlobal(position), true);
}

void ApplicationShell::refreshLevelCameraMarker()
{
	if (!m_levelMapViewport || !m_levelMap3D) {
		return;
	}
	// The 2D view shows the 3D camera while both can be seen: beside it in
	// Radiant's layout, or whenever a single view is back on its plane after
	// the camera was placed.
	const bool shown = m_levelMap3D->isPerspective() && m_levelMap3D->hasMesh() && levelMap2DShowing();
	const ModelVec3 at = m_levelMap3D->cameraPosition();
	for (auto* view : m_levelPlanViews) {
		view->setCameraMarker(shown && !view->QWidget::isHidden(), LevelMapVec3 {at.x, at.y, at.z, true}, m_levelMap3D->cameraYaw(), m_levelMap3D->cameraPitch(),
			m_levelMap3D->fieldOfView());
	}
}

void ApplicationShell::aimLevelCameraAt(const QPointF& planePoint, bool place)
{
	if (!m_levelMap3D || !m_levelMap3D->isPerspective() || !m_levelMapViewport) {
		return;
	}
	// The axis the 2D view hides keeps the camera's own value.
	const ModelVec3 camera = m_levelMap3D->cameraPosition();
	ModelVec3 point = camera;
	switch (m_levelMapViewport->projection()) {
	case MapViewportProjection::TopXY:
		point.x = static_cast<float>(planePoint.x());
		point.y = static_cast<float>(planePoint.y());
		break;
	case MapViewportProjection::FrontXZ:
		point.x = static_cast<float>(planePoint.x());
		point.z = static_cast<float>(planePoint.y());
		break;
	case MapViewportProjection::SideZY:
		point.y = static_cast<float>(planePoint.x());
		point.z = static_cast<float>(planePoint.y());
		break;
	}
	if (place) {
		m_levelMap3D->setCameraView(point, m_levelMap3D->cameraYaw(), m_levelMap3D->cameraPitch());
	} else {
		// From above only the heading turns, as Radiant's top view does.
		m_levelMap3D->aimCameraAt(point, m_levelMapViewport->projection() == MapViewportProjection::TopXY);
	}
}

void ApplicationShell::showLevelControlsReference()
{
	// Every gesture and key the Levels views answer to under the chosen
	// editor's controls, grouped by view, searchable, and kept open beside the
	// work so it can be read while trying them.
	if (!m_levelControlsDialog) {
		m_levelControlsDialog = new QDialog(this);
		m_levelControlsDialog->setObjectName(QStringLiteral("levelControlsDialog"));
		m_levelControlsDialog->setModal(false);
		m_levelControlsDialog->resize(560, 620);
		auto* layout = new QVBoxLayout(m_levelControlsDialog);
		auto* filter = new QLineEdit(m_levelControlsDialog);
		filter->setObjectName(QStringLiteral("levelControlsFilter"));
		filter->setPlaceholderText(tr("Filter gestures and keys"));
		filter->setAccessibleName(tr("Filter the controls"));
		filter->setClearButtonEnabled(true);
		clearOnEscape(filter);
		layout->addWidget(filter);
		auto* tree = new QTreeWidget(m_levelControlsDialog);
		tree->setObjectName(QStringLiteral("levelControlsTree"));
		tree->setAccessibleName(tr("Level editor controls"));
		tree->setColumnCount(2);
		tree->setHeaderLabels({tr("Action"), tr("Mouse or key")});
		tree->setRootIsDecorated(true);
		tree->setUniformRowHeights(false);
		tree->setWordWrap(true);
		tree->setTextElideMode(Qt::ElideNone);
		// QTreeWidget's default row hint does not use the actual column width,
		// so long translated gestures otherwise remain one truncated line.
		class ControlsDelegate final : public QStyledItemDelegate {
		public:
			explicit ControlsDelegate(QTreeWidget* owner) : QStyledItemDelegate(owner), m_tree(owner) {}
			QSize sizeHint(const QStyleOptionViewItem& option, const QModelIndex& index) const override
			{
				QStyleOptionViewItem item(option);
				initStyleOption(&item, index);
				QSize hint = QStyledItemDelegate::sizeHint(option, index);
				int width = m_tree->columnWidth(index.column()) - 12;
				if (index.column() == 0) {
					width -= m_tree->indentation() * (index.parent().isValid() ? 2 : 1);
				}
				const auto text = item.fontMetrics.boundingRect(QRect(0, 0, std::max(1, width), 100000), Qt::TextWordWrap, item.text);
				hint.setHeight(std::max(hint.height(), text.height() + 8));
				return hint;
			}
		private:
			QTreeWidget* m_tree;
		};
		tree->setItemDelegate(new ControlsDelegate(tree));
		tree->header()->setSectionResizeMode(QHeaderView::Stretch);
		connect(tree->header(), &QHeaderView::sectionResized, tree, [tree]() { tree->doItemsLayout(); });
		layout->addWidget(tree, 1);
		auto* buttons = new QDialogButtonBox(QDialogButtonBox::Close, m_levelControlsDialog);
		connect(buttons, &QDialogButtonBox::rejected, m_levelControlsDialog, &QDialog::hide);
		layout->addWidget(buttons);
		connect(filter, &QLineEdit::textChanged, tree, [tree](const QString& text) {
			const QString needle = text.trimmed();
			for (int group = 0; group < tree->topLevelItemCount(); ++group) {
				QTreeWidgetItem* heading = tree->topLevelItem(group);
				int shown = 0;
				for (int row = 0; row < heading->childCount(); ++row) {
					QTreeWidgetItem* item = heading->child(row);
					const bool match = needle.isEmpty() || item->text(0).contains(needle, Qt::CaseInsensitive) || item->text(1).contains(needle, Qt::CaseInsensitive);
					item->setHidden(!match);
					shown += match ? 1 : 0;
				}
				heading->setHidden(shown == 0);
			}
		});
	}
	auto* tree = m_levelControlsDialog->findChild<QTreeWidget*>(QStringLiteral("levelControlsTree"));
	EditorProfileDescriptor profile;
	editorProfileForId(m_settings.selectedEditorProfileId(), &profile);
	m_levelControlsDialog->setWindowTitle(m_settings.editorGestureOverrides(profile.id).isEmpty()
		? tr("%1 Controls").arg(profile.displayName) : tr("%1 Controls (customized)").arg(profile.displayName));
	m_levelControlsDialog->setAccessibleName(m_levelControlsDialog->windowTitle());
	if (tree) {
		tree->clear();
		QHash<QString, QTreeWidgetItem*> groups;
		if (!profile.adaptations.isEmpty()) {
			auto* heading = new QTreeWidgetItem(tree, {tr("Profile adaptations")});
			heading->setFirstColumnSpanned(true);
			for (const auto& note : profile.adaptations) {
				auto* item = new QTreeWidgetItem(heading, {tr("Workflow differences"), note});
				item->setToolTip(1, note);
				item->setData(0, Qt::AccessibleTextRole, note);
			}
		}
		for (const LevelEditorControlRow& row : levelEditorControlRows(m_levelControls)) {
			QTreeWidgetItem* heading = groups.value(row.view);
			if (!heading) {
				heading = new QTreeWidgetItem(tree, {row.view});
				heading->setFirstColumnSpanned(true);
				QFont bold = heading->font(0);
				bold.setBold(true);
				heading->setFont(0, bold);
				heading->setExpanded(true);
				groups.insert(row.view, heading);
			}
			auto* item = new QTreeWidgetItem(heading, {row.action, row.gesture});
			item->setToolTip(1, row.gesture);
			item->setData(0, Qt::AccessibleTextRole, tr("%1: %2").arg(row.action, row.gesture));
		}
		tree->expandAll();
	}
	if (auto* filter = m_levelControlsDialog->findChild<QLineEdit*>(QStringLiteral("levelControlsFilter"))) {
		filter->clear();
		filter->setFocus(Qt::OtherFocusReason);
	}
	m_levelControlsDialog->show();
	m_levelControlsDialog->raise();
	m_levelControlsDialog->activateWindow();
}

void ApplicationShell::refreshLevelMap3DHighlight()
{
	if (!levelMap3DShowing()) {
		return;
	}
	// A selected entity lights its brushes and patches; a Doom selection its
	// linedefs.
	QSet<QPair<int, int>> lit;
	QSet<int> entities;
	for (const LevelMapSelectionRef& ref : std::as_const(m_levelMapDocument.selection)) {
		lit.insert({static_cast<int>(ref.kind), ref.objectId});
		if (ref.kind == LevelMapSelectionKind::Entity) {
			entities.insert(ref.objectId);
		}
	}
	for (const LevelMapBrush& brush : std::as_const(m_levelMapDocument.brushes)) {
		if (entities.contains(brush.entityId)) {
			lit.insert({static_cast<int>(LevelMapSelectionKind::QuakeBrush), brush.id});
		}
	}
	for (const LevelMapPatch& patch : std::as_const(m_levelMapDocument.patches)) {
		if (entities.contains(patch.entityId)) {
			lit.insert({static_cast<int>(LevelMapSelectionKind::QuakePatch), patch.id});
		}
	}
	QVector<int> triangles;
	for (int triangle = 0; triangle < m_levelMap3DOwners.size(); ++triangle) {
		const LevelMapSelectionRef& owner = m_levelMap3DOwners.at(triangle);
		if (lit.contains({static_cast<int>(owner.kind), owner.objectId})) {
			triangles.push_back(triangle);
		}
	}
	m_levelMap3D->setHighlightedTriangles(triangles);
	refreshLevelCameraResize();
	refreshLevelCameraBrush();
}

void ApplicationShell::stepLevelMapGrid(int direction)
{
	if (!m_levelMapGrid) {
		return;
	}
	const int index = std::clamp(m_levelMapGrid->currentIndex() + (direction < 0 ? -1 : 1), 0, m_levelMapGrid->count() - 1);
	if (index == m_levelMapGrid->currentIndex()) {
		statusBar()->showMessage(direction < 0 ? tr("The grid is already at its finest, %1 unit.").arg(m_levelMapGrid->currentData().toInt())
						       : tr("The grid is already at its coarsest, %1 units.").arg(m_levelMapGrid->currentData().toInt()));
		return;
	}
	m_levelMapGrid->setCurrentIndex(index);
	refreshCommandEnablement();
	statusBar()->showMessage(tr("Grid: %1 units.").arg(m_levelMapGrid->currentData().toInt()));
}

void ApplicationShell::hideLevelMapSelection()
{
	if (!m_levelMapViewport) {
		return;
	}
	const int hidden = m_levelMapViewport->hideSelection();
	if (hidden == 0) {
		statusBar()->showMessage(tr("Select entities, brushes, patches, or things to hide them."));
		return;
	}
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Hid %n object(s); Shift+H shows everything again.", nullptr, hidden));
}

void ApplicationShell::showAllLevelMapObjects()
{
	if (!m_levelMapViewport || m_levelMapViewport->hiddenCount() == 0) {
		statusBar()->showMessage(tr("Nothing is hidden."));
		return;
	}
	const int hidden = m_levelMapViewport->hiddenCount();
	m_levelMapViewport->showAllHidden();
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Showed %n hidden object(s).", nullptr, hidden));
}

bool ApplicationShell::copyFocusedTextSelection()
{
	QWidget* focus = QApplication::focusWidget();
	if (auto* plain = qobject_cast<QPlainTextEdit*>(focus); plain && plain->textCursor().hasSelection()) {
		plain->copy();
		return true;
	}
	if (auto* rich = qobject_cast<QTextEdit*>(focus); rich && rich->textCursor().hasSelection()) {
		rich->copy();
		return true;
	}
	if (auto* label = qobject_cast<QLabel*>(focus); label && label->hasSelectedText()) {
		QGuiApplication::clipboard()->setText(label->selectedText());
		return true;
	}
	return false;
}

bool ApplicationShell::copyLevelMapSelectionToClipboard()
{
	QString error;
	const QString text = levelMapSelectionText(m_levelMapDocument, &error);
	if (text.isEmpty()) {
		statusBar()->showMessage(error.isEmpty() ? tr("Select entities, brushes, or patches of a Quake-family map to copy them.")
							 : tr("Could not copy: %1").arg(error));
		return false;
	}
	QGuiApplication::clipboard()->setText(text);
	statusBar()->showMessage(tr("Copied %n map object(s) as .map text.", nullptr, static_cast<int>(m_levelMapDocument.selection.size())));
	return true;
}

void ApplicationShell::cutLevelMapSelection()
{
	if (!levelMapSelectionIsDeletable(m_levelMapDocument)) {
		statusBar()->showMessage(tr("Select entities other than worldspawn, brushes, or patches to cut them."));
		return;
	}
	if (copyLevelMapSelectionToClipboard()) {
		deleteLevelMapSelectionFromUi();
	}
}

void ApplicationShell::pasteLevelMapFromClipboard()
{
	QString error;
	LevelPlacementRequest request;
	request.operation = LevelPlacementOperation::Paste;
	request.text = QGuiApplication::clipboard()->text();
	request.textures = {m_settings.levelTextureLock(), m_settings.levelAllowValve220()};
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(tr("Could not paste: %1").arg(error));
		return;
	}
	const int count = static_cast<int>(m_levelMapDocument.selection.size());
	recordActivity(tr("Level map objects pasted"), tr("%n object(s)", nullptr, count), QStringLiteral("level-map"),
		OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Pasted %n map object(s); they are selected.", nullptr, count));
}

void ApplicationShell::rotateLevelMapSelectionFromUi(bool counterclockwise)
{
	if (m_levelMapDocument.selection.isEmpty() || !m_levelMapViewport) {
		statusBar()->showMessage(tr("Select map objects before turning them."));
		return;
	}
	// Counterclockwise on screen is a positive turn about the axis pointing at
	// the viewer: +z in the top view, +x in the side view, and -y in the front
	// view, whose screen shows x to the right and z up.
	int axis = 2;
	int turns = counterclockwise ? 1 : -1;
	switch (m_levelMapViewport->projection()) {
	case MapViewportProjection::TopXY:
		break;
	case MapViewportProjection::FrontXZ:
		axis = 1;
		turns = -turns;
		break;
	case MapViewportProjection::SideZY:
		axis = 0;
		break;
	}
	QString error;
	LevelMapRotationRequest rotation;
	rotation.axis = axis;
	rotation.degrees = 90.0 * turns;
	rotation.textureLock = m_settings.levelTextureLock();
	rotation.allowValve220 = m_settings.levelAllowValve220();
	LevelPlacementRequest request;
	request.operation = LevelPlacementOperation::Rotate;
	request.rotation = rotation;
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(tr("Could not turn the selection: %1").arg(error));
		return;
	}
	recordActivity(tr("Level map selection turned"), counterclockwise ? tr("90° left") : tr("90° right"), QStringLiteral("level-map"),
		OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(counterclockwise ? tr("Turned the selection 90° left.") : tr("Turned the selection 90° right."));
}

void ApplicationShell::flipLevelMapSelectionFromUi(bool horizontal)
{
	if (m_levelMapDocument.selection.isEmpty() || !m_levelMapViewport) {
		statusBar()->showMessage(tr("Select map objects before flipping them."));
		return;
	}
	// The view's horizontal and vertical axes: x and y from the top, x and z
	// from the front, y and z from the side.
	int axis = 0;
	switch (m_levelMapViewport->projection()) {
	case MapViewportProjection::TopXY:
		axis = horizontal ? 0 : 1;
		break;
	case MapViewportProjection::FrontXZ:
		axis = horizontal ? 0 : 2;
		break;
	case MapViewportProjection::SideZY:
		axis = horizontal ? 1 : 2;
		break;
	}
	QString error;
	LevelPlacementRequest request;
	request.operation = LevelPlacementOperation::Mirror;
	request.axis = axis;
	request.textures = {m_settings.levelTextureLock(), m_settings.levelAllowValve220()};
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(tr("Could not flip the selection: %1").arg(error));
		return;
	}
	recordActivity(tr("Level map selection flipped"), horizontal ? tr("horizontal") : tr("vertical"), QStringLiteral("level-map"),
		OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(horizontal ? tr("Flipped the selection horizontally.") : tr("Flipped the selection vertically."));
}

bool ApplicationShell::levelMapSelectionResizable() const
{
	const LevelMapDocument& document = m_levelMapDocument;
	if (document.selection.isEmpty()) {
		return false;
	}
	if (document.format == LevelMapFormat::DoomWad && !document.doomUdmf) {
		for (const LevelMapSelectionRef& ref : document.selection) {
			if (ref.kind != LevelMapSelectionKind::DoomThing) {
				return false;
			}
		}
	}
	LevelMapVec3 mins;
	LevelMapVec3 maxs;
	return levelMapSelectionBounds(document, &mins, &maxs) && (maxs.x > mins.x || maxs.y > mins.y || maxs.z > mins.z);
}

bool ApplicationShell::applyLevelMapResize(const LevelMapVec3& mins, const LevelMapVec3& maxs)
{
	QString error;
	LevelPlacementRequest request;
	request.operation = LevelPlacementOperation::Resize;
	request.mins = mins;
	request.maxs = maxs;
	request.textures = {m_settings.levelTextureScaleLock(), m_settings.levelAllowValve220()};
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(tr("Could not resize the selection: %1").arg(error));
		// A handle drag previewed a box the map never took; draw it as it is.
		refreshLevelMapViewport();
		return false;
	}
	const QString size = tr("%1 by %2 by %3 units")
				     .arg(maxs.x - mins.x, 0, 'g', 8)
				     .arg(maxs.y - mins.y, 0, 'g', 8)
				     .arg(maxs.z - mins.z, 0, 'g', 8);
	recordActivity(tr("Level map selection resized"), size, QStringLiteral("level-map"), OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Resized %n object(s) to %1.", nullptr, static_cast<int>(m_levelMapDocument.selection.size())).arg(size));
	return true;
}

void ApplicationShell::resizeLevelMapSelectionFromViewport(const LevelMapVec3& mins, const LevelMapVec3& maxs)
{
	if (m_levelMapDocument.format == LevelMapFormat::Unknown) {
		return;
	}
	applyLevelMapResize(mins, maxs);
}

void ApplicationShell::resizeLevelMapSelectionFromUi()
{
	LevelMapVec3 low;
	LevelMapVec3 high;
	if (!levelMapSelectionResizable() || !levelMapSelectionBounds(m_levelMapDocument, &low, &high)) {
		statusBar()->showMessage(m_levelMapDocument.format == LevelMapFormat::DoomWad
				? tr("Select two or more things to resize the space between them.")
				: tr("Select map objects with a size before resizing them."));
		return;
	}
	const bool doom = m_levelMapDocument.format == LevelMapFormat::DoomWad;
	const double grid = m_levelMapViewport ? std::max(1, m_levelMapViewport->gridSize()) : 16.0;
	const double from[3] {low.x, low.y, low.z};
	const double size[3] {high.x - low.x, high.y - low.y, high.z - low.z};

	QDialog dialog(this);
	dialog.setObjectName(QStringLiteral("resizeSelectionDialog"));
	dialog.setWindowTitle(tr("Resize Selection"));
	dialog.setAccessibleName(tr("Resize Selection"));
	auto* layout = new QVBoxLayout(&dialog);
	auto* current = new QLabel(tr("Now %1 by %2 by %3 units, from %4, %5, %6.")
					   .arg(size[0], 0, 'g', 8)
					   .arg(size[1], 0, 'g', 8)
					   .arg(size[2], 0, 'g', 8)
					   .arg(from[0], 0, 'g', 8)
					   .arg(from[1], 0, 'g', 8)
					   .arg(from[2], 0, 'g', 8),
		&dialog);
	current->setObjectName(QStringLiteral("resizeSelectionCurrent"));
	current->setWordWrap(true);
	layout->addWidget(current);
	auto* form = new QFormLayout;
	QVector<QDoubleSpinBox*> sizes;
	const QStringList axes {tr("Width (x)"), tr("Depth (y)"), tr("Height (z)")};
	for (int axis = 0; axis < 3; ++axis) {
		auto* field = new QDoubleSpinBox(&dialog);
		field->setObjectName(QStringLiteral("resizeSize%1").arg(QLatin1Char("xyz"[axis])));
		field->setDecimals(3);
		field->setRange(size[axis] > 0.0 ? 0.001 : 0.0, 131072.0);
		field->setSingleStep(grid);
		field->setValue(size[axis]);
		// The shown value is rounded; remembering it tells an edited field from
		// one left alone, which keeps its exact size.
		field->setProperty("shownValue", field->value());
		field->setSuffix(tr(" units"));
		field->setAccessibleName(axes.at(axis));
		// An axis the selection has no size along cannot be stretched; things
		// have no height at all.
		if (size[axis] <= 0.0) {
			field->setEnabled(false);
			field->setToolTip(tr("The selection has no size along this axis."));
		}
		form->addRow(axes.at(axis), field);
		if (doom && axis == 2) {
			field->hide();
			form->labelForField(field)->hide();
		}
		sizes << field;
	}
	auto* anchor = new QComboBox(&dialog);
	anchor->setObjectName(QStringLiteral("resizeAnchor"));
	anchor->addItem(tr("Lower corner"));
	anchor->addItem(tr("Centre"));
	anchor->addItem(tr("Upper corner"));
	anchor->setAccessibleName(tr("Keep in place"));
	anchor->setToolTip(tr("The point of the selection's box that stays where it is."));
	form->addRow(tr("Keep in place"), anchor);
	layout->addLayout(form);
	auto* buttons = new QDialogButtonBox(QDialogButtonBox::Ok | QDialogButtonBox::Cancel, &dialog);
	buttons->button(QDialogButtonBox::Ok)->setText(tr("Resize"));
	connect(buttons, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
	connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
	layout->addWidget(buttons);
	for (QDoubleSpinBox* field : sizes) {
		if (field->isEnabled()) {
			field->setFocus(Qt::OtherFocusReason);
			field->selectAll();
			break;
		}
	}
	if (dialog.exec() != QDialog::Accepted) {
		return;
	}

	LevelMapVec3 mins = low;
	LevelMapVec3 maxs = high;
	double* newLow[3] {&mins.x, &mins.y, &mins.z};
	double* newHigh[3] {&maxs.x, &maxs.y, &maxs.z};
	for (int axis = 0; axis < 3; ++axis) {
		if (size[axis] <= 0.0) {
			continue;
		}
		QDoubleSpinBox* field = sizes.at(axis);
		const bool edited = std::abs(field->value() - field->property("shownValue").toDouble()) > 1.0e-9;
		const double wanted = edited ? field->value() : size[axis];
		switch (anchor->currentIndex()) {
		case 1: {
			const double middle = from[axis] + size[axis] * 0.5;
			*newLow[axis] = middle - wanted * 0.5;
			*newHigh[axis] = middle + wanted * 0.5;
			break;
		}
		case 2:
			*newLow[axis] = from[axis] + size[axis] - wanted;
			break;
		default:
			*newHigh[axis] = from[axis] + wanted;
			break;
		}
	}
	applyLevelMapResize(mins, maxs);
}

void ApplicationShell::snapLevelMapSelectionFromUi()
{
	if (m_levelMapDocument.selection.isEmpty() || !m_levelMapViewport) {
		statusBar()->showMessage(tr("Select map objects before snapping them to the grid."));
		return;
	}
	const int grid = std::max(1, m_levelMapViewport->gridSize());
	QString error;
	LevelPlacementRequest request;
	request.operation = LevelPlacementOperation::Snap;
	request.grid = grid;
	request.textures = {m_settings.levelTextureLock(), m_settings.levelAllowValve220()};
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(error);
		return;
	}
	const int moved = static_cast<int>(m_levelMapDocument.undoStack.last().moveSteps.size());
	recordActivity(tr("Level map selection snapped"), tr("%n object(s)", nullptr, moved), QStringLiteral("level-map"),
		OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Snapped %n object(s) to the %1-unit grid.", nullptr, moved).arg(grid));
}

void ApplicationShell::duplicateLevelMapSelectionFromUi()
{
	if (m_levelMapDocument.selection.isEmpty() || !m_levelMapViewport) {
		statusBar()->showMessage(tr("Select map objects before duplicating them."));
		return;
	}
	// One grid step right and down on screen, whichever plane the view shows.
	const double step = std::max(1, m_levelMapViewport->gridSize());
	double dx = 0.0;
	double dy = 0.0;
	double dz = 0.0;
	switch (m_levelMapViewport->projection()) {
	case MapViewportProjection::TopXY:
		dx = step;
		dy = -step;
		break;
	case MapViewportProjection::FrontXZ:
		dx = step;
		dz = -step;
		break;
	case MapViewportProjection::SideZY:
		dy = step;
		dz = -step;
		break;
	}
	QString error;
	LevelPlacementRequest request;
	request.offset = {dx, dy, dz, true};
	request.textures = {m_settings.levelTextureLock(), m_settings.levelAllowValve220()};
	if (!runLevelPlacementFromUi(request, &error)) {
		statusBar()->showMessage(tr("Could not duplicate: %1").arg(error));
		return;
	}
	const int count = static_cast<int>(m_levelMapDocument.selection.size());
	const QString what = count == 1 ? levelMapSelectionRefId(m_levelMapDocument.selection.first()) : tr("%n copies", nullptr, count);
	recordActivity(tr("Level map objects duplicated"), what, QStringLiteral("level-map"), OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(count == 1 ? tr("Duplicated as %1; the copy is selected.").arg(what)
					    : tr("Duplicated %1; the copies are selected.").arg(what));
}

QString ApplicationShell::similarLevelMapObjectsLabel() const
{
	const LevelMapDocument& document = m_levelMapDocument;
	if (document.selectionKind == LevelMapSelectionKind::DoomThing) {
		for (const LevelMapDoomThing& thing : document.doomThings) {
			if (thing.id == document.selectedObjectId) {
				return tr("Select All Type %1").arg(thing.type);
			}
		}
	}
	if (document.selectionKind == LevelMapSelectionKind::Entity) {
		for (const LevelMapEntity& entity : document.entities) {
			if (entity.id == document.selectedObjectId && !entity.className.isEmpty()) {
				return tr("Select All %1").arg(entity.className);
			}
		}
	}
	return {};
}

QString ApplicationShell::selectedLevelMapTexture() const
{
	const LevelMapDocument& document = m_levelMapDocument;
	switch (document.selectionKind) {
	case LevelMapSelectionKind::QuakeBrush:
		for (const LevelMapBrush& brush : document.brushes) {
			if (brush.id == document.selectedObjectId && !brush.faces.isEmpty()) {
				return brush.faces.first().textureName;
			}
		}
		break;
	case LevelMapSelectionKind::QuakePatch:
		for (const LevelMapPatch& patch : document.patches) {
			if (patch.id == document.selectedObjectId) {
				return patch.textureName;
			}
		}
		break;
	case LevelMapSelectionKind::DoomSector:
		for (const LevelMapDoomSector& sector : document.doomSectors) {
			if (sector.id == document.selectedObjectId) {
				return sector.floorTexture;
			}
		}
		break;
	default:
		break;
	}
	return {};
}

void ApplicationShell::selectLevelMapObjectsByTexture(const QString& texture)
{
	QString name = texture;
	if (name.isEmpty()) {
		QStringList textures;
		for (const LevelMapTextureUse& use : levelMapTextureUsage(m_levelMapDocument)) {
			textures << use.name;
		}
		if (textures.isEmpty()) {
			statusBar()->showMessage(tr("The open map uses no textures."));
			return;
		}
		const QString preset = selectedLevelMapTexture();
		bool ok = false;
		name = QInputDialog::getItem(this, tr("Select by Texture"), tr("Texture"), textures,
			std::max(0, static_cast<int>(textures.indexOf(preset))), true, &ok).trimmed();
		if (!ok || name.isEmpty()) {
			return;
		}
	}
	// Objects hidden in the view stay out, as Select All leaves them.
	int leftHidden = 0;
	const QVector<LevelMapSelectionRef> objects = visibleLevelMapObjects(levelMapObjectsUsingTexture(m_levelMapDocument, name), &leftHidden);
	if (objects.isEmpty()) {
		statusBar()->showMessage(leftHidden > 0 ? tr("Only hidden objects use %1; Show All Hidden brings them back.").arg(name)
							: tr("Nothing in the map uses %1.").arg(name));
		return;
	}
	setLevelMapSelection(&m_levelMapDocument, objects);
	refreshLevelMapWorkbench();
	QString message = tr("Selected %n object(s) using %1.", nullptr, static_cast<int>(objects.size())).arg(name);
	if (leftHidden > 0) {
		message += QLatin1Char(' ') + tr("%n hidden one(s) left out; Show All Hidden brings them back.", nullptr, leftHidden);
	}
	statusBar()->showMessage(message);
}

void ApplicationShell::selectSimilarLevelMapObjects()
{
	LevelMapDocument& document = m_levelMapDocument;
	QVector<LevelMapSelectionRef> selection;
	QString what;
	if (document.selectionKind == LevelMapSelectionKind::DoomThing) {
		int type = -1;
		for (const LevelMapDoomThing& thing : document.doomThings) {
			if (thing.id == document.selectedObjectId) {
				type = thing.type;
			}
		}
		for (const LevelMapDoomThing& thing : document.doomThings) {
			if (thing.type == type && thing.id != document.selectedObjectId) {
				selection.push_back({LevelMapSelectionKind::DoomThing, thing.id});
			}
		}
		what = tr("type %1").arg(type);
	} else if (document.selectionKind == LevelMapSelectionKind::Entity) {
		QString className;
		for (const LevelMapEntity& entity : document.entities) {
			if (entity.id == document.selectedObjectId) {
				className = entity.className;
			}
		}
		for (const LevelMapEntity& entity : document.entities) {
			if (entity.id != document.selectedObjectId && !className.isEmpty() && entity.className.compare(className, Qt::CaseInsensitive) == 0) {
				selection.push_back({LevelMapSelectionKind::Entity, entity.id});
			}
		}
		what = tr("class %1").arg(className);
	} else {
		statusBar()->showMessage(tr("Select an entity or a thing first."));
		return;
	}
	// Objects hidden in the view stay out, as Select All leaves them; the
	// object the user picked stays primary, so the inspector keeps it.
	int leftHidden = 0;
	selection = visibleLevelMapObjects(selection, &leftHidden);
	selection.push_back({document.selectionKind, document.selectedObjectId});
	setLevelMapSelection(&document, selection);
	refreshLevelMapWorkbench();
	QString message = tr("Selected %n object(s) of %1.", nullptr, static_cast<int>(selection.size())).arg(what);
	if (leftHidden > 0) {
		message += QLatin1Char(' ') + tr("%n hidden one(s) left out; Show All Hidden brings them back.", nullptr, leftHidden);
	}
	statusBar()->showMessage(message);
}

void ApplicationShell::removeEntityInspectorKey()
{
	QTreeWidgetItem* item = m_entityInspector ? m_entityInspector->currentItem() : nullptr;
	if (m_levelMapDocument.selectionKind == LevelMapSelectionKind::DoomThing) {
		statusBar()->showMessage(tr("A Doom thing always has these fields; edit a value instead of removing it."));
		return;
	}
	if (!item || !item->data(0, Qt::UserRole + 2).toBool() || m_levelMapDocument.selectionKind != LevelMapSelectionKind::Entity) {
		statusBar()->showMessage(tr("Choose a key the entity sets to remove it."));
		return;
	}
	const QString key = item->data(0, Qt::UserRole).toString();
	if (key.compare(QStringLiteral("classname"), Qt::CaseInsensitive) == 0) {
		statusBar()->showMessage(tr("An entity needs its classname; edit it instead of removing it."));
		return;
	}
	QString error;
	if (const QVector<int> several = selectedLevelMapEntityIds(); several.size() > 1) {
		const int before = static_cast<int>(m_levelMapDocument.undoStack.size());
		if (!removeLevelMapEntitiesProperty(&m_levelMapDocument, several, key, &error)) {
			statusBar()->showMessage(tr("Map edit failed: %1").arg(error));
			return;
		}
		const int removed = m_levelMapDocument.undoStack.size() > before ? static_cast<int>(m_levelMapDocument.undoStack.constLast().propertySteps.size()) : 0;
		recordActivity(tr("Level map entity key removed"), key, QStringLiteral("level-map"), OperationState::Warning, tr("Unsaved map edit"));
		refreshLevelMapWorkbench();
		statusBar()->showMessage(tr("Removed %1 from %n entit(y)(ies). Undo restores it.", nullptr, removed).arg(key));
		return;
	}
	if (!removeLevelMapEntityProperty(&m_levelMapDocument, m_levelMapDocument.selectedObjectId, key, &error)) {
		statusBar()->showMessage(tr("Map edit failed: %1").arg(error));
		return;
	}
	recordActivity(tr("Level map entity key removed"), key, QStringLiteral("level-map"), OperationState::Warning, tr("Unsaved map edit"));
	refreshLevelMapWorkbench();
	statusBar()->showMessage(tr("Removed %1. Undo restores it.").arg(key));
}

bool ApplicationShell::levelMapHasUnsavedEdits() const
{
	return m_levelMapDocument.format != LevelMapFormat::Unknown
		&& m_levelMapDocument.editState == QStringLiteral("modified");
}

bool ApplicationShell::confirmLevelMapEditsHandled(const QString& question, const QString& proceedLabel)
{
	if (!levelMapHasUnsavedEdits()) {
		return true;
	}
	QMessageBox box(this);
	box.setIcon(QMessageBox::Warning);
	box.setWindowTitle(tr("Unsaved Map Edits"));
	box.setText(tr("%1 has unsaved edits.").arg(m_levelMapDocument.mapName));
	box.setInformativeText(question);
	QPushButton* save = box.addButton(tr("Save"), QMessageBox::AcceptRole);
	// Going ahead without saving throws the edits away, or, for a compile, uses
	// the saved file and leaves the edits open in the editor.
	QPushButton* proceed = proceedLabel.isEmpty()
		? box.addButton(tr("Discard Edits"), QMessageBox::DestructiveRole)
		: box.addButton(proceedLabel, QMessageBox::ActionRole);
	box.addButton(QMessageBox::Cancel);
	box.setDefaultButton(save);
	box.exec();
	if (box.clickedButton() == proceed) {
		return true;
	}
	if (box.clickedButton() == save) {
		return saveLevelMapFromUi();
	}
	return false;
}

void ApplicationShell::planLevelMapCompile()
{
	if (m_compilerRunThread) {
		statusBar()->showMessage(tr("A compiler task is already running"));
		return;
	}
	if (m_levelMapDocument.format == LevelMapFormat::Unknown) {
		statusBar()->showMessage(tr("Open a level map before planning a compile."));
		return;
	}
	if (m_levelMapDocument.sourcePath.isEmpty() && !saveLevelMapFromUi()) { return; }
	// The compiler reads the file on disk, so unsaved edits would silently be
	// left out of the build.
	if (!confirmLevelMapEditsHandled(tr("The compiler reads the saved file, so it would not see them. Save and compile the current map?"),
			tr("Compile Saved File"))) {
		return;
	}
	runLevelMapCompile(m_levelMapDocument);
}

void ApplicationShell::runLevelMapCompile(const LevelMapDocument& document)
{
	const QString profileId = m_levelMapCompilerProfile ? m_levelMapCompilerProfile->currentData().toString() : QString();
	CompilerCommandRequest request = compilerRequestForLevelMap(document, profileId);
	request.workspaceRootPath = m_settings.currentProjectPath();
	ProjectManifest manifest;
	if (!request.workspaceRootPath.trimmed().isEmpty() && loadProjectManifest(request.workspaceRootPath, &manifest)) {
		request.extraSearchPaths = effectiveProjectCompilerSearchPaths(manifest, request.extraSearchPaths);
		request.executableOverrides = effectiveProjectCompilerToolOverrides(manifest, m_settings.compilerToolPathOverrides());
	} else {
		request.executableOverrides = m_settings.compilerToolPathOverrides();
	}
	const CompilerCommandPlan plan = buildCompilerCommandPlan(request);
	m_levelMapDrawer->setSections({
		{QStringLiteral("compile-plan"), tr("Compile Plan"), tr("Reviewable compiler command"), compilerCommandPlanText(plan), plan.state()},
		{QStringLiteral("map-health"), tr("Map Health"), tr("Validation before compile"), levelMapValidationLines(document).join('\n'), levelMapStatistics(document).errorCount > 0 ? OperationState::Failed : OperationState::Warning},
	});
	m_levelMapDrawer->showSection(QStringLiteral("compile-plan"));
	if (!plan.isRunnable()) {
		recordActivity(tr("Level compile plan"), request.profileId, QStringLiteral("level-map"), plan.state(), tr("Review required"), plan.warnings);
		statusBar()->showMessage(tr("Compiler plan needs review."));
		return;
	}

	CompilerRunRequest runRequest;
	runRequest.command = request;
	runRequest.registerOutputs = true;
	const QString manifestRoot = request.workspaceRootPath.trimmed().isEmpty() ? QFileInfo(request.inputPath).absolutePath() : request.workspaceRootPath;
	runRequest.manifestPath = QDir(manifestRoot).filePath(QStringLiteral(".vibestudio/compiler-runs/%1-%2.json").arg(request.profileId, QDateTime::currentDateTimeUtc().toString(QStringLiteral("yyyyMMddTHHmmssZ"))));

	m_compilerRunCancelRequested.store(false);
	m_compilerRunActivityId = m_activity.createTask(tr("Level Compile"), request.profileId, tr("level-map"), OperationState::Running, true);
	m_activity.setProgress(m_compilerRunActivityId, 0, 4, tr("Planning compiler command."));
	refreshActivityCenter(m_compilerRunActivityId);
	statusBar()->showMessage(tr("Level compiler run started: %1").arg(request.profileId));

	const QString taskId = m_compilerRunActivityId;
	const QString projectPath = request.workspaceRootPath;
	auto* thread = QThread::create([this, runRequest, taskId, projectPath]() {
		CompilerRunCallbacks callbacks;
		callbacks.cancellationRequested = [this]() {
			return m_compilerRunCancelRequested.load();
		};
		callbacks.logEntry = [this, taskId](const CompilerTaskLogEntry& entry) {
			QMetaObject::invokeMethod(this, [this, taskId, entry]() {
				m_activity.appendLog(taskId, OperationState::Running, entry.message);
				// A streamed line updates the task's details only while the user
				// is looking at that task; it never moves the selection.
				if (selectedActivityTaskId() == taskId) {
					refreshActivityDetails(taskId);
				}
			}, Qt::QueuedConnection);
		};
		CompilerRunResult result = runCompilerCommand(runRequest, callbacks);
		QMetaObject::invokeMethod(this, [this, result, taskId, projectPath]() {
			finishCompilerRun(result, taskId, projectPath);
		}, Qt::QueuedConnection);
	});
	m_compilerRunThread = thread;
	connect(thread, &QThread::finished, thread, &QObject::deleteLater);
	thread->start();
}

void ApplicationShell::copyLevelMapCliEquivalent()
{
	if (m_levelMapDocument.sourcePath.trimmed().isEmpty()) {
		statusBar()->showMessage(tr("Open a level map before copying a CLI command."));
		return;
	}
	QStringList parts = {
		QStringLiteral("vibestudio"),
		QStringLiteral("--cli"),
		QStringLiteral("map"),
		QStringLiteral("compile-plan"),
		m_levelMapDocument.outputPath.trimmed().isEmpty() ? m_levelMapDocument.sourcePath : m_levelMapDocument.outputPath,
	};
	if (m_levelMapDocument.format == LevelMapFormat::DoomWad && !m_levelMapDocument.mapName.isEmpty()) {
		parts << QStringLiteral("--map") << m_levelMapDocument.mapName;
	}
	if (m_levelMapCompilerProfile && !m_levelMapCompilerProfile->currentData().toString().isEmpty()) {
		parts << QStringLiteral("--profile") << m_levelMapCompilerProfile->currentData().toString();
	}
	for (QString& part : parts) {
		part = quoteCliPart(part);
	}
	QGuiApplication::clipboard()->setText(parts.join(' '));
	statusBar()->showMessage(tr("Level map CLI command copied."));
}

void ApplicationShell::refreshAdvancedStudioSurface()
{
	if (!m_advancedStudioState || !m_advancedStudioDrawer) {
		return;
	}

	auto setListLines = [](QListWidget* list, const QStringList& lines, const QString& emptyText) {
		if (!list) {
			return;
		}
		list->clear();
		if (lines.isEmpty()) {
			list->addItem(disabledListItem(emptyText));
			return;
		}
		list->addItems(lines);
	};

	const bool hasShader = !m_advancedShaderDocument.shaders.isEmpty();
	const bool hasSprite = !m_advancedSpritePlan.frames.isEmpty();
	const bool hasCode = !m_advancedCodeIndex.files.isEmpty();
	const bool hasAi = !m_advancedAiProposal.title.isEmpty();
	const bool hasExtensions = !m_advancedExtensionDiscovery.manifests.isEmpty();
	const int ready = static_cast<int>(hasShader) + static_cast<int>(hasSprite) + static_cast<int>(hasCode) + static_cast<int>(hasAi) + static_cast<int>(hasExtensions);
	const OperationState state = ready >= 5 ? OperationState::Completed : (ready > 0 ? OperationState::Warning : OperationState::Idle);
	const QString projectPath = m_settings.currentProjectPath();

	// The Shaders page owns this pane, so it reports the shader script; the
	// sprite, code, AI, and extension results show on their own surfaces.
	Q_UNUSED(ready);
	Q_UNUSED(state);
	Q_UNUSED(projectPath);
	const OperationState shaderState = !hasShader ? OperationState::Idle
		: (m_advancedShaderValidationWarnings.isEmpty() ? OperationState::Completed : OperationState::Warning);
	m_advancedStudioState->setTitle(tr("Shader Script"));
	m_advancedStudioState->setDetail(hasShader
			? tr("%1 shader(s), %2 texture reference(s), %3 warning(s)")
				  .arg(m_advancedShaderDocument.shaders.size())
				  .arg(m_advancedShaderValidation.size())
				  .arg(m_advancedShaderValidationWarnings.size())
			: tr("Open an idTech3 shader script to inspect its stages."));
	m_advancedStudioState->setState(shaderState, localizedOperationStateName(shaderState));
	m_advancedStudioState->setProgress({});

	if (m_advancedShaderGraph) {
		const QSignalBlocker blocker(m_advancedShaderGraph);
		m_advancedShaderGraph->clear();
		if (!hasShader) {
			auto* empty = new QTreeWidgetItem(m_advancedShaderGraph, {tr("No shader script inspected yet.")});
			empty->setFirstColumnSpanned(true);
			empty->setFlags(Qt::NoItemFlags);
		}
		QHash<QString, ShaderReferenceValidation> checks;
		for (const ShaderReferenceValidation& check : m_advancedShaderValidation) {
			checks.insert(check.textureReference.toLower(), check);
		}
		const QString separator = QStringLiteral("  %1  ").arg(QChar(0x00b7));
		// Each shader's properties, for the filter's queries.
		m_shaderQueryProperties.clear();
		for (const ShaderDefinition& shader : m_advancedShaderDocument.shaders) {
			StudioQueryProperties& properties = m_shaderQueryProperties[shader.name];
			properties.insert(QStringLiteral("name"), shader.name);
			properties.insert(QStringLiteral("stages"), QString::number(shader.stages.size()));
			properties.insert(QStringLiteral("textures"), QString::number(shader.textureReferences.size()));
			int missing = 0;
			for (const QString& reference : shader.textureReferences) {
				const auto check = checks.constFind(reference.toLower());
				missing += check != checks.constEnd() && !check->found ? 1 : 0;
			}
			properties.insert(QStringLiteral("missing"), QString::number(missing));
			// A directive's first word is its key: cull none, surfaceparm nolightmap.
			for (const QString& directive : shader.directives) {
				const QString line = directive.simplified();
				const qsizetype space = line.indexOf(QLatin1Char(' '));
				properties.insert((space < 0 ? line : line.left(space)).toLower(), space < 0 ? QString() : line.mid(space + 1));
			}
			for (const ShaderStage& stage : shader.stages) {
				properties.insert(QStringLiteral("blend"), stage.blendFunc);
				properties.insert(QStringLiteral("map"), stage.mapDirective);
				properties.insert(QStringLiteral("rgbgen"), stage.rgbGen);
			}
		}
		for (const ShaderDefinition& shader : m_advancedShaderDocument.shaders) {
			auto* shaderItem = new QTreeWidgetItem(m_advancedShaderGraph, {shader.name,
				QStringList {tr("%n stage(s)", nullptr, static_cast<int>(shader.stages.size())),
					tr("%n texture(s)", nullptr, static_cast<int>(shader.textureReferences.size()))}
					.join(separator)});
			shaderItem->setIcon(0, studioIcon(QStringLiteral("layers")));
			shaderItem->setData(0, Qt::UserRole, shader.name);
			shaderItem->setData(0, Qt::UserRole + 1, -1);
			shaderItem->setData(0, Qt::UserRole + 3, shader.startLine);
			shaderItem->setToolTip(0, shader.directives.isEmpty() ? shader.name : QStringLiteral("%1\n%2").arg(shader.name, shader.directives.join('\n')));
			shaderItem->setToolTip(1, shaderItem->toolTip(0));
			for (const ShaderStage& stage : shader.stages) {
				const QStringList details {
					stage.mapDirective.isEmpty() ? tr("no map") : stage.mapDirective,
					tr("blend %1").arg(stage.blendFunc.isEmpty() ? tr("default") : stage.blendFunc),
					tr("rgbGen %1").arg(stage.rgbGen.isEmpty() ? tr("identity") : stage.rgbGen),
				};
				auto* stageItem = new QTreeWidgetItem(shaderItem, {tr("Stage %1").arg(stage.id), details.join(separator)});
				stageItem->setData(0, Qt::UserRole, shader.name);
				stageItem->setData(0, Qt::UserRole + 1, stage.id);
				stageItem->setData(0, Qt::UserRole + 3, stage.startLine);
				stageItem->setToolTip(0, stage.rawText.trimmed());
				stageItem->setToolTip(1, details.join('\n'));
				for (const QString& reference : stage.textureReferences) {
					const auto check = checks.constFind(reference.toLower());
					const bool checked = check != checks.constEnd();
					const bool missing = checked && !check->found;
					QString status = tr("not checked");
					if (checked) {
						status = !check->found ? tr("missing from the open package")
							: (check->foundInPackage.isEmpty() ? tr("found") : tr("found in %1").arg(QFileInfo(check->foundInPackage).fileName()));
					}
					auto* textureItem = new QTreeWidgetItem(stageItem, {reference, status});
					textureItem->setIcon(0, studioIcon(missing ? QStringLiteral("warning") : QStringLiteral("image"),
						missing ? StudioIconTone::Warning : StudioIconTone::Muted));
					textureItem->setData(0, Qt::UserRole, shader.name);
					textureItem->setData(0, Qt::UserRole + 1, stage.id);
					textureItem->setData(0, Qt::UserRole + 2, reference);
					textureItem->setData(0, Qt::UserRole + 3, stage.startLine);
					const QString tip = checked && !check->candidatePaths.isEmpty()
						? tr("%1\nLooked for: %2").arg(reference, check->candidatePaths.join(QStringLiteral(", ")))
						: reference;
					textureItem->setToolTip(0, tip);
					textureItem->setToolTip(1, tip);
				}
			}
		}
		m_advancedShaderGraph->expandAll();
		filterShaderGraph();
	}

	QStringList spriteLines;
	if (hasSprite) {
		spriteLines << m_advancedSpritePlan.sequenceLines;
		spriteLines << m_advancedSpritePlan.palettePreviewLines;
		spriteLines << m_advancedSpritePlan.stagingLines;
	}
	setListLines(m_advancedSpriteSequence, spriteLines, tr("No sprite workflow plan yet."));

	// Symbol rows carry their file and line, so activating one opens it there.
	refreshCodeIndexResults();

	QStringList aiLines;
	if (hasAi) {
		aiLines = aiProposalReviewSurfaceText(m_advancedAiProposal).split('\n');
	}
	setListLines(m_advancedAiProposalList, aiLines, tr("No AI proposal generated yet."));

	QStringList extensionLines;
	if (hasExtensions || !m_advancedExtensionDiscovery.warnings.isEmpty()) {
		extensionLines = extensionDiscoveryText(m_advancedExtensionDiscovery).split('\n');
	} else {
		extensionLines = extensionTrustModelLines();
	}
	setListLines(m_advancedExtensions, extensionLines, tr("No extensions discovered yet."));

	refreshShaderDetailSections();
}

void ApplicationShell::refreshShaderDetailSections(const QString& shaderName, int stageIndex)
{
	if (!m_advancedStudioDrawer) {
		return;
	}
	const bool hasShader = !m_advancedShaderDocument.shaders.isEmpty();
	m_advancedStudioDrawer->setTitle(tr("Shader Details"));
	m_advancedStudioDrawer->setSubtitle(hasShader ? tr("Stages, blend modes, and texture references") : tr("No shader script loaded"));
	QVector<DetailSection> shaderSections;
	if (hasShader && !shaderName.isEmpty()) {
		// The selected shader, or one of its stages, ahead of the whole report.
		shaderSections.push_back({QStringLiteral("selection"),
			stageIndex >= 0 ? tr("Stage %1").arg(stageIndex) : tr("Shader"),
			shaderName,
			shaderStagePreviewLines(m_advancedShaderDocument, shaderName, stageIndex).join('\n'),
			OperationState::Completed});
	}
	if (hasShader) {
		shaderSections.push_back({QStringLiteral("shader"), tr("Shader Report"), tr("%1 shader(s)").arg(m_advancedShaderDocument.shaders.size()),
			shaderDocumentReportText(m_advancedShaderDocument, m_advancedShaderValidation, m_advancedShaderValidationWarnings),
			m_advancedShaderValidationWarnings.isEmpty() ? OperationState::Completed : OperationState::Warning});
	}
	shaderSections.push_back({QStringLiteral("capabilities"), tr("Capabilities"), tr("What the shader tools cover"), advancedStudioCapabilityLines().join('\n'), OperationState::Completed});
	m_advancedStudioDrawer->setSections(shaderSections);
	m_advancedStudioDrawer->showSection(!shaderName.isEmpty() && hasShader ? QStringLiteral("selection")
		: (hasShader ? QStringLiteral("shader") : QStringLiteral("capabilities")));
}

void ApplicationShell::inspectAdvancedShaderScript()
{
	const QString path = m_advancedShaderPath ? m_advancedShaderPath->text().trimmed() : QString();
	if (path.isEmpty()) {
		statusBar()->showMessage(tr("Choose a shader script before inspecting."));
		return;
	}
	openMaterialScript(path);
	QString error;
	if (!loadShaderScript(path, &m_advancedShaderDocument, &error)) {
		statusBar()->showMessage(tr("Shader inspect failed: %1").arg(error));
		recordActivity(tr("Shader inspect failed"), nativePath(path), QStringLiteral("shader"), OperationState::Failed, error);
		return;
	}
	QStringList packagePaths;
	if (m_packageArchive.isOpen()) {
		packagePaths << m_packageArchive.sourcePath();
	}
	m_advancedShaderValidation = validateShaderReferences(m_advancedShaderDocument, packagePaths, &m_advancedShaderValidationWarnings);
	recordActivity(tr("Shader inspected"), nativePath(path), QStringLiteral("shader"), m_advancedShaderValidationWarnings.isEmpty() ? OperationState::Completed : OperationState::Warning, tr("%1 shader(s), %2 reference(s)").arg(m_advancedShaderDocument.shaders.size()).arg(m_advancedShaderValidation.size()), m_advancedShaderValidationWarnings);
	refreshAdvancedStudioSurface();
	m_advancedStudioDrawer->showSection(QStringLiteral("shader"));
	statusBar()->showMessage(tr("Shader inspected: %1").arg(nativePath(path)));
}

void ApplicationShell::createAdvancedSpritePlan()
{
	SpriteWorkflowRequest request;
	request.engineFamily = m_advancedSpriteEngine ? m_advancedSpriteEngine->currentData().toString() : QStringLiteral("doom");
	request.spriteName = m_advancedSpriteName && !m_advancedSpriteName->text().trimmed().isEmpty() ? m_advancedSpriteName->text().trimmed() : QStringLiteral("SPRT");
	bool framesOk = false;
	bool rotationsOk = false;
	request.frameCount = m_advancedSpriteFrames ? m_advancedSpriteFrames->text().toInt(&framesOk) : 4;
	request.rotations = m_advancedSpriteRotations ? m_advancedSpriteRotations->text().toInt(&rotationsOk) : 8;
	if (!framesOk || request.frameCount <= 0) {
		request.frameCount = 4;
	}
	if (!rotationsOk || request.rotations < 0) {
		request.rotations = request.engineFamily == QStringLiteral("doom") ? 8 : 1;
	}
	request.paletteId = request.engineFamily == QStringLiteral("doom") ? QStringLiteral("doom-playpal") : QStringLiteral("quake-palette");
	request.outputPackageRoot = request.engineFamily == QStringLiteral("doom") ? QStringLiteral("sprites") : QStringLiteral("progs");
	m_advancedSpritePlan = buildSpriteWorkflowPlan(request);
	recordActivity(tr("Sprite plan created"), request.spriteName, QStringLiteral("sprite"), m_advancedSpritePlan.state, tr("%1 staged frame(s)").arg(m_advancedSpritePlan.frames.size()), m_advancedSpritePlan.warnings);
	refreshAdvancedStudioSurface();
	m_advancedStudioDrawer->showSection(QStringLiteral("sprite"));
	statusBar()->showMessage(tr("Sprite workflow plan created."));
}

void ApplicationShell::indexAdvancedCodeWorkspace()
{
	startCodeIndex();
	if (m_codeOutputTabs && m_codeIndexPanel) { m_codeOutputTabs->setCurrentWidget(m_codeIndexPanel); }
}

void ApplicationShell::createAdvancedAiProposal()
{
	const QString prompt = m_advancedAiPrompt && !m_advancedAiPrompt->text().trimmed().isEmpty() ? m_advancedAiPrompt->text().trimmed() : tr("Create a reviewable idTech asset workflow");
	const QString kind = m_advancedAiKind ? m_advancedAiKind->currentData().toString() : QStringLiteral("shader");
	const AiAutomationPreferences preferences = m_settings.aiAutomationPreferences();
	if (kind == QStringLiteral("entity")) {
		m_advancedAiProposal = promptToEntityDefinitionAiExperiment(prompt, preferences);
	} else if (kind == QStringLiteral("package")) {
		m_advancedAiProposal = promptToPackageValidationPlanAiExperiment(prompt, m_packageArchive.isOpen() ? m_packageArchive.sourcePath() : QString(), preferences);
	} else if (kind == QStringLiteral("batch")) {
		m_advancedAiProposal = promptToBatchConversionRecipeAiExperiment(prompt, preferences);
	} else if (kind == QStringLiteral("cli")) {
		m_advancedAiProposal = generateCliCommandAiExperiment(prompt, preferences);
	} else {
		m_advancedAiProposal = promptToShaderScaffoldAiExperiment(prompt, preferences);
	}
	recordActivity(tr("AI proposal generated"), kind, QStringLiteral("ai"), m_advancedAiProposal.manifest.state, m_advancedAiProposal.summary, m_advancedAiProposal.manifest.warnings);
	refreshAdvancedStudioSurface();
	m_advancedStudioDrawer->showSection(QStringLiteral("ai"));
	statusBar()->showMessage(tr("AI proposal generated for review."));
}

void ApplicationShell::discoverAdvancedExtensions()
{
	QString root = m_advancedExtensionRoot ? m_advancedExtensionRoot->text().trimmed() : QString();
	if (root.isEmpty() && !m_settings.currentProjectPath().isEmpty()) {
		root = QDir(m_settings.currentProjectPath()).filePath(QStringLiteral("extensions"));
	}
	if (root.isEmpty()) {
		root = QDir::currentPath();
	}
	m_advancedExtensionDiscovery = discoverExtensions({root});
	recordActivity(tr("Extensions discovered"), nativePath(root), QStringLiteral("extension"), m_advancedExtensionDiscovery.state, tr("%1 extension manifest(s)").arg(m_advancedExtensionDiscovery.manifests.size()), m_advancedExtensionDiscovery.warnings);
	refreshAdvancedStudioSurface();
	m_advancedStudioDrawer->showSection(QStringLiteral("extensions"));
	statusBar()->showMessage(tr("Extension discovery complete."));
}

QString ApplicationShell::selectedWorkspaceFilePath() const
{
	const QListWidget* lists[] = {m_workspaceSearchResults, m_changedFiles, m_dependencyGraph, m_projectProblems, m_recentActivityTimeline};
	for (const QListWidget* list : lists) {
		const QListWidgetItem* item = list ? list->currentItem() : nullptr;
		const QString path = item ? item->data(Qt::UserRole).toString() : QString();
		if (!path.trimmed().isEmpty()) {
			return path;
		}
	}
	return {};
}

QString ApplicationShell::selectedWorkspaceVirtualPath() const
{
	const QListWidget* lists[] = {m_workspaceSearchResults, m_changedFiles, m_dependencyGraph, m_projectProblems, m_recentActivityTimeline};
	for (const QListWidget* list : lists) {
		const QListWidgetItem* item = list ? list->currentItem() : nullptr;
		const QString path = item ? item->data(Qt::UserRole + 1).toString() : QString();
		if (!path.trimmed().isEmpty()) {
			return path;
		}
	}
	const QString selectedPackagePath = selectedPackageEntryPath();
	if (!selectedPackagePath.isEmpty()) {
		return selectedPackagePath;
	}
	return {};
}

void ApplicationShell::revealSelectedWorkspacePath()
{
	const QString path = selectedWorkspaceFilePath();
	if (path.isEmpty()) {
		statusBar()->showMessage(tr("No local workspace path selected"));
		return;
	}

	QFileInfo info(path);
	if (!info.exists()) {
		statusBar()->showMessage(tr("Selected workspace path does not exist locally"));
		return;
	}
	const QString revealPath = info.isDir() ? info.absoluteFilePath() : info.absolutePath();
	if (revealPath.isEmpty() || !QDesktopServices::openUrl(QUrl::fromLocalFile(revealPath))) {
		statusBar()->showMessage(tr("Unable to reveal workspace path"));
		return;
	}
	statusBar()->showMessage(tr("Revealed: %1").arg(nativePath(revealPath)));
}

void ApplicationShell::copySelectedWorkspaceVirtualPath()
{
	QString path = selectedWorkspaceVirtualPath();
	if (path.isEmpty()) {
		path = selectedWorkspaceFilePath();
	}
	if (path.isEmpty()) {
		statusBar()->showMessage(tr("No workspace path selected"));
		return;
	}
	QApplication::clipboard()->setText(path);
	statusBar()->showMessage(tr("Copied path: %1").arg(path));
}

void ApplicationShell::refreshPackageTree()
{
	UiRefreshTiming timing(__func__);
	if (!m_packageTree || !m_packageEntries) { return; }
	const QSignalBlocker blocker(m_packageTree);
	const auto& archive = packageViewArchive();
	if (!archive.isOpen()) {
		const auto error = archive.errorString();
		m_packageTree->showMessage(error.isEmpty() ? tr("No package loaded") : tr("Package view unavailable"), error); return;
	}
	const auto index = m_packageEntries->browserIndex(packageViewKey());
	if (!index) {
		const auto status = m_packageEntries->busy() || !m_packageEntries->canRetry() ? tr("Preparing package entries…") : m_packageEntries->statusText();
		m_packageTree->showMessage(status, status); return;
	}
	const auto& summary = index->summary;
	const auto label = summary.sourcePath.isEmpty() ? tr("Untitled %1").arg(localizedPackageFormatName(summary.format)) : QFileInfo(summary.sourcePath).fileName();
	QString detail = tr("%1 entries from %2").arg(summary.entryCount).arg(nativePath(summary.sourcePath));
	if (summary.totalSizeOverflow) { detail += QLatin1Char('\n') + tr("Size exceeds the supported range"); }
	m_packageTree->showFolders(index, packageViewKey(), label, detail, summary.warningCount > 0 || summary.totalSizeOverflow);
	if (m_packageTree->currentIndex().isValid() && m_packageTree->currentIndex().data(Qt::UserRole).isValid()
		&& m_packageTree->selectedFolder() == m_packageBrowseFolder) { return; }
	if (!m_packageTree->selectFolder(m_packageBrowseFolder)) {
		m_packageBrowseFolder.clear(); m_packageTree->selectFolder(QString());
		// An edit may remove the folder that was open. Refilter the root using
		// the prepared index; the entry view rejects the superseded result.
		filterPackageEntries();
	}
}

void ApplicationShell::refreshPackageCompositionSummary()
{
	UiRefreshTiming timing(__func__);
	if (!m_packageComposition) {
		return;
	}
	m_packageComposition->clear();
	const QString viewError = packageViewArchive().errorString();
	if (m_packageCompositionChart) {
		m_packageCompositionChart->clear();
		m_packageCompositionChart->setVisible(true);
		m_packageCompositionChart->setEmptyText(viewError.isEmpty()
			? tr("Open a package to see how its content divides by type and size.") : viewError);
	}
	if (!packageViewArchive().isOpen()) {
		auto* item = new QListWidgetItem(viewError.isEmpty()
			? tr("No package composition yet\nOpen a folder, PAK, WAD, ZIP, or PK3 to see type and size distribution.")
			: tr("Package view unavailable") + QLatin1Char('\n') + viewError);
		item->setFlags(Qt::NoItemFlags);
		item->setToolTip(viewError); item->setData(Qt::AccessibleDescriptionRole, viewError);
		item->setData(Qt::UserRole + 1, viewError.isEmpty() ? QStringLiteral("idle") : QStringLiteral("failed"));
		m_packageComposition->addItem(item);
		return;
	}

	const auto index = m_packageEntries->browserIndex(packageViewKey());
	if (!index) {
		const auto status = m_packageEntries->busy() || !m_packageEntries->canRetry() ? tr("Preparing package entries…") : m_packageEntries->statusText();
		auto* item = new QListWidgetItem(status); item->setFlags(Qt::ItemIsEnabled);
		item->setData(Qt::AccessibleTextRole, status); m_packageComposition->addItem(item);
		if (m_packageCompositionChart) { m_packageCompositionChart->setEmptyText(status); }
		return;
	}
	const QVector<SummaryBucket> buckets = packageCompositionBuckets(*index);
	const bool overflow = index->summary.totalSizeOverflow;
	if (overflow) {
		const auto warning = tr("Total size exceeds the supported range; proportions are unavailable.");
		auto* item = new QListWidgetItem(QChar(0x2068) + warning + QChar(0x2069)); item->setFlags(Qt::ItemIsEnabled);
		item->setToolTip(warning); item->setData(Qt::AccessibleTextRole, warning);
		item->setData(Qt::UserRole + 1, QStringLiteral("warning")); m_packageComposition->addItem(item);
		if (m_packageCompositionChart) { m_packageCompositionChart->setEmptyText(warning); m_packageCompositionChart->hide(); }
	}
	const double totalBytes = static_cast<double>(std::max<quint64>(1, index->summary.totalSizeBytes));
	for (const SummaryBucket& bucket : buckets) {
		const double fraction = !overflow && bucket.bytes > 0 ? static_cast<double>(bucket.bytes) / totalBytes : 0.0;
		const auto label = overflow ? bucket.label : QStringLiteral("%1 %2").arg(compositionBar(fraction), bucket.label);
		const auto detail = QStringLiteral("%1 / %2").arg(byteSizeText(bucket.bytes, bucket.sizeOverflow), tr("%n entries", nullptr, bucket.count));
		auto* item = new QListWidgetItem(QChar(0x2068) + label + QChar(0x2069) + QLatin1Char('\n') + QChar(0x2068) + detail + QChar(0x2069));
		const auto accessible = label + QLatin1Char('\n') + detail;
		item->setToolTip(accessible); item->setData(Qt::AccessibleTextRole, accessible);
		item->setData(Qt::UserRole + 1, !bucket.sizeOverflow && bucket.bytes > 0 ? QStringLiteral("completed") : QStringLiteral("warning"));
		m_packageComposition->addItem(item);
	}
	if (buckets.isEmpty()) {
		auto* item = new QListWidgetItem(tr("Package is empty"));
		item->setFlags(Qt::NoItemFlags);
		item->setData(Qt::UserRole + 1, QStringLiteral("warning"));
		m_packageComposition->addItem(item);
	}

	if (m_packageCompositionChart && !overflow) {
		QVector<StudioChartSlice> slices;
		int patternIndex = 0;
		for (const SummaryBucket& bucket : buckets) {
			StudioChartSlice slice;
			slice.id = bucket.id;
			slice.label = bucket.label;
			slice.value = static_cast<double>(bucket.bytes);
			slice.valueText = byteSizeText(bucket.bytes);
			slice.detail = tr("%n entries", nullptr, bucket.count);
			slice.state = bucket.bytes > 0 ? OperationState::Completed : OperationState::Warning;
			slice.patternIndex = patternIndex++;
			slices.push_back(slice);
		}
		m_packageCompositionChart->setSlices(slices);
	}
}

void ApplicationShell::refreshPackageStagingSummary()
{
	UiRefreshTiming timing(__func__);
	refreshPackageRecoveryStatus();
	if (m_packageBrowserKey != packageViewKey()) { refreshPackageBrowser(); return; }
	if (m_audioEditorDialog) { m_audioEditorDialog->refreshContext(); }
	const QString previewKey = packageViewKey();
	if (previewKey != m_levelPackagePreviewKey) {
		m_levelPackagePreviewKey = previewKey;
		refreshLevelMap3D();
		refreshModelMaterials();
		if (m_textureEntries) { refreshTextureBrowser(); }
		if (m_audioEntries) { refreshAudioBrowser(); }
		if (m_modelEntries) { refreshModelBrowser(); }
		refreshLevelAssetBrowsers();
	}
	if (m_textureEditorDialog) { m_textureEditorDialog->refreshContext(); }
	if (m_modelEditorDialog) { m_modelEditorDialog->refreshContext(); }
	if (!m_packageStagingSummary) {
		return;
	}

	const bool stagingLoaded = m_packageArchive.isOpen() && m_packageStaging.isLoaded() && !m_packageSaveRunning && !m_packageReadRunning && !m_packageExtractionRunning;

	QVector<PackageStagingRow> before, after;
	auto* rows = &before;
	const auto addItem = [&rows](const QString& text, const QString& state) { rows->append({text, state}); };

	if (!stagingLoaded) {
		m_packageStagingSummary->showMessage(tr("No package loaded for staging\nOpen a folder, PAK, WAD, ZIP, or PK3 before staging changes."));
		refreshPackageCommandEnablement();
		return;
	}

	const PackageStagingSummary summary = m_packageStaging.summary();
	const QString state = summary.blockingCount > 0 ? QStringLiteral("failed") : QStringLiteral("completed");
	addItem(QStringLiteral("%1\n%2\n%3 -> %4\n%5")
			.arg(summary.canSave ? tr("Staging ready") : tr("Staging blocked"),
				tr("%1 operations, %2 conflicts, %3 blockers").arg(summary.operationCount).arg(summary.conflictCount).arg(summary.blockingCount),
				tr("%n base files", nullptr, summary.baseFileCount),
				tr("%n staged files", nullptr, summary.stagedFileCount),
				tr("%1 before, %2 after").arg(byteSizeText(summary.beforeBytes, summary.beforeSizeOverflow, summary.totalsAvailable), byteSizeText(summary.afterBytes, summary.afterSizeOverflow, summary.totalsAvailable))),
		state);

	if (!m_packageStaging.draftPath().isEmpty()) {
		addItem(tr("Draft: %1\n%2").arg(nativePath(m_packageStaging.draftPath()), m_packageStaging.isModified() ? tr("Unsaved draft edits") : tr("Draft saved")),
			m_packageStaging.isModified() ? QStringLiteral("running") : QStringLiteral("completed"));
	}
	if (summary.operationCount == 0) {
		addItem(tr("No staged changes yet\nUse Stage Add, Replace, Rename, or Delete to build a save-as plan."), QStringLiteral("idle"));
	}

	rows = &after;

	const auto addCompositionLines = [&](const QString& title, const QVector<PackageCompositionBucket>& buckets, quint64 totalBytes, bool overflow) {
		if (!summary.totalsAvailable) {
			addItem(QStringLiteral("%1\n%2").arg(title, tr("Composition unavailable.")), QStringLiteral("warning")); return;
		}
		if (overflow) { addItem(QStringLiteral("%1\n%2").arg(title, tr("Total size exceeds the supported range; proportions are unavailable.")), QStringLiteral("warning")); }
		const int limit = 4;
		int shown = 0;
		for (const PackageCompositionBucket& bucket : buckets) {
			if (shown >= limit) {
				break;
			}
			const double fraction = bucket.sizeBytes > 0 ? static_cast<double>(bucket.sizeBytes) / static_cast<double>(std::max<quint64>(1, totalBytes)) : 0.0;
			addItem(QStringLiteral("%1: %2\n%3 %4 / %5")
					.arg(title,
						bucket.label,
						overflow ? QString() : compositionBar(fraction),
						byteSizeText(bucket.sizeBytes, bucket.sizeOverflow),
						tr("%n files", nullptr, bucket.fileCount)),
				overflow ? QStringLiteral("warning") : QStringLiteral("completed"));
			++shown;
		}
		if (buckets.isEmpty()) {
			addItem(QStringLiteral("%1\n%2").arg(title, tr("No files in this composition.")), QStringLiteral("warning"));
		}
	};
	addCompositionLines(tr("Before"), m_packageStaging.beforeComposition(), summary.beforeBytes, summary.beforeSizeOverflow);
	addCompositionLines(tr("After"), m_packageStaging.afterComposition(), summary.afterBytes, summary.afterSizeOverflow);

	m_packageStagingSummary->setContents(std::move(before), m_packageStaging.operations(), m_packageStaging.conflicts(), std::move(after));
	scheduleThemeRefresh();
	refreshCommandEnablement();
}

void ApplicationShell::refreshPackageEntryDetails(const QString& virtualPath)
{
	UiRefreshTiming timing(__func__);
	if (!m_packageDrawer) {
		return;
	}

	PackageEntry selectedEntry;
	const auto entries = packageViewArchive().entries();
	const qsizetype entryIndex = selectedPackageEntryPath() == virtualPath ? selectedPackageEntryIndex() : -1;
	const bool found = entryIndex >= 0 && entryIndex < entries.size() && entries.at(entryIndex).virtualPath == virtualPath;
	if (found) { selectedEntry = entries.at(entryIndex); }

	if (!found) {
		if (m_packagePreviewWorker) { m_packagePreviewWorker->cancel(); }
		m_packageMetadataPreviewKey.clear(); m_packageMetadataPreview.reset(); m_packagePreviewCancelled = false;
		if (m_packagePreviewStatus) { m_packagePreviewStatus->hide(); m_packagePreviewProgress->hide(); m_packagePreviewCancel->hide(); }
		if (m_packageTexturePreviewWorker) { m_packageTexturePreviewWorker->cancel(); }
		m_packageTexturePreviewKey.clear(); m_packageTexturePreview.reset();
		if (m_packageImagePreview) { m_packageImagePreview->clearImage(); }
		if (m_packageTextPreview) { m_packageTextPreview->clear(); }
		m_packageDrawer->setTitle(tr("Package Entry Details"));
		const QString viewError = packageViewArchive().errorString();
		m_packageDrawer->setSubtitle(viewError.isEmpty() ? tr("No entry selected.") : tr("Package view unavailable"));
		m_packageDrawer->setSections({});
		if (m_packagePreviewStack && m_packagePreviewNote) {
			m_packagePreviewNote->setText(viewError.isEmpty() ? tr("Select an image or text entry to preview it.") : viewError);
			m_packagePreviewStack->setCurrentWidget(m_packagePreviewNote);
		}
		return;
	}

	QStringList summaryLines;
	summaryLines << tr("Path: %1").arg(selectedEntry.virtualPath);
	summaryLines << tr("Kind: %1").arg(localizedPackageEntryKindName(selectedEntry.kind));
	summaryLines << tr("Type: %1").arg(selectedEntry.typeHint);
	summaryLines << tr("Size: %1").arg(byteSizeText(selectedEntry.sizeBytes));
	summaryLines << tr("Compressed size: %1").arg(byteSizeText(selectedEntry.compressedSizeBytes));
	summaryLines << tr("Storage: %1").arg(selectedEntry.storageMethod.isEmpty() ? tr("unknown") : selectedEntry.storageMethod);
	summaryLines << tr("Readable now: %1").arg(selectedEntry.readable ? tr("yes") : tr("no"));
	summaryLines << tr("Nested archive candidate: %1").arg(selectedEntry.nestedArchiveCandidate ? tr("yes") : tr("no"));
	if (!selectedEntry.modifiedUtc.isValid()) {
		summaryLines << tr("Modified: unknown");
	} else {
		summaryLines << tr("Modified: %1").arg(QLocale::system().toString(selectedEntry.modifiedUtc.toLocalTime(), QLocale::LongFormat));
	}
	if (!selectedEntry.note.isEmpty()) {
		summaryLines << tr("Note: %1").arg(selectedEntry.note);
	}

	PackagePreview preview;
	bool previewChanged = false;
	const bool imageEntry = selectedEntry.kind == PackageEntryKind::File
		&& assetPreviewKindForEntry(selectedEntry.virtualPath, selectedEntry.typeHint) == AssetPreviewKind::Image;
	if (imageEntry) {
		if (m_packagePreviewWorker) { m_packagePreviewWorker->cancel(); }
		m_packageMetadataPreviewKey.clear(); m_packageMetadataPreview.reset();
		const auto source = texturePreviewSource();
		const QString key = source.revision + QChar(0) + QString::number(entryIndex);
		if (m_packageTexturePreviewKey != key) {
			previewChanged = true;
			if (!m_packageTexturePreviewWorker) { m_packageTexturePreviewWorker = new TexturePreviewWorker(this); }
			m_packageTexturePreviewKey = key; m_packageTexturePreview.reset(); m_packagePreviewCancelled = false;
			m_packageTexturePreviewWorker->completed = [this, key](const TexturePreviewResult& result) {
				if (key != m_packageTexturePreviewKey || m_packagePreviewCancelled || result.entryIndex != selectedPackageEntryIndex()) { return; }
				if (result.revision != texturePreviewSource().revision) {
					m_packageTexturePreviewKey.clear(); refreshPackageEntryDetails(selectedPackageEntryPath()); return;
				}
				m_packageTexturePreview = std::make_shared<TexturePreviewResult>(result);
				refreshPackageEntryDetails(result.virtualPath);
			};
			TexturePreviewRequest request; request.source = source; request.virtualPath = virtualPath; request.entryIndex = entryIndex;
			request.decodePath = assetDetectionPath(virtualPath, selectedEntry.typeHint);
			m_packageTexturePreviewWorker->request(std::move(request));
		}
		preview.virtualPath = virtualPath; preview.totalBytes = selectedEntry.sizeBytes; preview.totalBytesKnown = true;
		preview.kind = PackagePreviewKind::Image;
		preview.title = tr("Texture Preview");
		preview.summary = tr("Loading texture preview…");
		if (m_packageTexturePreview) {
			const auto& decoded = m_packageTexturePreview->decoded;
			preview.kind = decoded.decoded ? PackagePreviewKind::Image : PackagePreviewKind::Unavailable;
			preview.error = decoded.error;
			preview.summary = decoded.decoded ? tr("%1, %2 x %3").arg(decoded.formatName).arg(decoded.width).arg(decoded.height) : decoded.error;
			preview.detailLines = idTechImageSummaryLines(decoded);
			preview.assetDetailLines = preview.detailLines;
			preview.assetRawLines = decoded.detailLines;
			preview.rawLines = decoded.detailLines;
			preview.detailLines.append(idTechPaletteSummaryLines(m_packageTexturePreview->palette));
		}
	} else {
		if (m_packageTexturePreviewWorker) { m_packageTexturePreviewWorker->cancel(); }
		m_packageTexturePreviewKey.clear(); m_packageTexturePreview.reset();
		const QString revision = packageViewKey();
		const QString key = revision + QChar(0) + QString::number(entryIndex);
		if (m_packageMetadataPreviewKey != key) {
			previewChanged = true;
			if (!m_packagePreviewWorker) { m_packagePreviewWorker = new PackagePreviewWorker(this); }
			m_packageMetadataPreviewKey = key; m_packageMetadataPreview.reset(); m_packagePreviewCancelled = false;
			m_packageTextPreview->clear();
			m_packagePreviewWorker->progress = [this, key](qint64 bytes, qint64 total) {
				if (key != m_packageMetadataPreviewKey || m_packagePreviewCancelled) { return; }
				m_packagePreviewProgress->setRange(0, total > 0 ? 1000 : m_settings.accessibilityPreferences().reducedMotion ? 1 : 0);
				m_packagePreviewProgress->setValue(total > 0 ? static_cast<int>(1000.0 * bytes / total) : 0);
				m_packagePreviewStatus->setText(bytes == total ? tr("Inspecting preview…")
					: tr("Reading preview: %1 / %2 MiB").arg(locale().toString(bytes / (1024.0 * 1024.0), 'f', 2), locale().toString(total / (1024.0 * 1024.0), 'f', 2)));
			};
			m_packagePreviewWorker->completed = [this, key](const PackagePreviewResult& result) {
				if (key != m_packageMetadataPreviewKey || m_packagePreviewCancelled || result.entryIndex != selectedPackageEntryIndex()) { return; }
				if (result.revision != packageViewKey()) {
					m_packageMetadataPreviewKey.clear(); refreshPackageEntryDetails(selectedPackageEntryPath()); return;
				}
				m_packageMetadataPreview = std::make_shared<PackagePreviewResult>(result);
				refreshPackageEntryDetails(result.preview.virtualPath);
			};
			PackagePreviewRequest request;
			request.archive = std::make_shared<PackageArchive>(packageViewArchive()); request.revision = revision;
			request.entryIndex = entryIndex; request.virtualPath = virtualPath;
			m_packagePreviewWorker->request(std::move(request));
		}
		if (m_packageMetadataPreview) { preview = m_packageMetadataPreview->preview; }
		else { preview.virtualPath = virtualPath; preview.totalBytes = selectedEntry.sizeBytes; preview.totalBytesKnown = true; preview.summary = tr("Loading package preview…"); }
	}
	const bool pending = !m_packagePreviewCancelled && (imageEntry ? !m_packageTexturePreview : !m_packageMetadataPreview);
	if (m_packagePreviewCancelled) { preview = {}; preview.virtualPath = virtualPath; preview.totalBytes = selectedEntry.sizeBytes; preview.totalBytesKnown = true; preview.cancelled = true; preview.summary = tr("Preview cancelled."); }
	const OperationState previewState = m_packagePreviewCancelled ? OperationState::Cancelled : pending ? OperationState::Loading
		: preview.kind == PackagePreviewKind::Unavailable ? OperationState::Warning : OperationState::Completed;
	m_packagePreviewStatus->setText(preview.error.isEmpty() ? preview.summary : preview.error);
	m_packagePreviewStatus->show();
	m_packagePreviewProgress->setVisible(pending);
	m_packagePreviewProgress->setRange(0, m_settings.accessibilityPreferences().reducedMotion ? 1 : 0);
	m_packagePreviewProgress->setValue(0);
	m_packagePreviewCancel->setVisible(pending || m_packagePreviewCancelled);
	m_packagePreviewCancel->setText(m_packagePreviewCancelled ? tr("Retry Preview") : tr("Cancel Preview"));
	if (m_packagePreviewStack && m_packageImagePreview && m_packageTextPreview && m_packagePreviewNote) {
		bool shown = false;
		if (pending || m_packagePreviewCancelled) {
			m_packageImagePreview->clearImage(); m_packageTextPreview->clear();
			m_packagePreviewNote->setText(preview.summary); m_packagePreviewStack->setCurrentWidget(m_packagePreviewNote); shown = true;
		} else if (preview.kind == PackagePreviewKind::Image) {
			if (m_packageTexturePreview && m_packageTexturePreview->decoded.decoded) {
				m_packageImagePreview->setDecodeResult(m_packageTexturePreview->decoded);
				m_packagePreviewStack->setCurrentWidget(m_packageImagePreview);
				shown = true;
			} else if (imageEntry && !m_packageTexturePreview) {
				m_packageImagePreview->clearImage();
				m_packagePreviewNote->setText(tr("Loading texture preview…"));
				m_packagePreviewStack->setCurrentWidget(m_packagePreviewNote);
				shown = true;
			}
		} else if (preview.kind == PackagePreviewKind::Text) {
			m_packageTextPreview->setPlainText(preview.body);
			m_packagePreviewStack->setCurrentWidget(m_packageTextPreview);
			shown = true;
		}
		if (!shown) {
			m_packageImagePreview->clearImage();
			m_packagePreviewNote->setText(!preview.error.isEmpty() ? preview.error : preview.kind == PackagePreviewKind::Directory
				? tr("Folders have no preview. Open it to list its contents.")
				: tr("No inline preview for %1. The Details tab lists what is known about it.").arg(localizedPackagePreviewKindName(preview.kind).toLower()));
			m_packagePreviewStack->setCurrentWidget(m_packagePreviewNote);
		}
	}
	PackagePreview drawerPreview = preview;
	if (preview.kind == PackagePreviewKind::Text) {
		drawerPreview.body = packageTextExcerpt(preview.body);
		for (auto* lines : {&drawerPreview.rawLines, &drawerPreview.assetRawLines}) {
			for (auto& line : *lines) { if (line == preview.body) { line = drawerPreview.body; } }
		}
	}
	const QString kindLabel = pending ? tr("Loading…") : m_packagePreviewCancelled ? tr("Cancelled") : localizedPackagePreviewKindName(preview.kind);
	QStringList previewDetailLines = preview.detailLines;
	if (previewDetailLines.isEmpty()) {
		previewDetailLines << (pending || m_packagePreviewCancelled ? preview.summary : tr("No preview details available."));
	}
	QStringList assetDetailLines = preview.assetDetailLines;
	if (assetDetailLines.isEmpty()) {
		assetDetailLines << (pending || m_packagePreviewCancelled ? preview.summary : tr("No specialized asset metadata available."));
	}
	QStringList assetRawLines = drawerPreview.assetRawLines;
	if (assetRawLines.isEmpty()) {
		assetRawLines << (pending || m_packagePreviewCancelled ? preview.summary : tr("No raw asset metadata available."));
	}

	QStringList rawLines;
	rawLines << tr("Source: %1").arg(nativePath(packageViewArchive().sourcePath()));
	rawLines << tr("Format: %1").arg(packageArchiveFormatId(packageViewArchive().format()));
	rawLines << tr("Virtual path: %1").arg(selectedEntry.virtualPath);
	rawLines << tr("Kind id: %1").arg(packageEntryKindId(selectedEntry.kind));
	rawLines << tr("Data offset: %1").arg(selectedEntry.dataOffset);
	rawLines << tr("Entry index: %1; source ordinal: %2").arg(entryIndex).arg(selectedEntry.sourceOrdinal);
	rawLines << tr("Size bytes: %1").arg(selectedEntry.sizeBytes);
	rawLines << tr("Compressed bytes: %1").arg(selectedEntry.compressedSizeBytes);
	rawLines << tr("Source archive id: %1").arg(selectedEntry.sourceArchiveId);
	rawLines << QString();
	rawLines << tr("Preview raw details:");
	rawLines << (drawerPreview.rawLines.isEmpty() ? tr("No preview raw details available.") : drawerPreview.rawLines.join('\n'));

	QStringList warningLines;
	for (const PackageLoadWarning& warning : packageViewArchive().warnings()) {
		if (warning.virtualPath.isEmpty() || warning.virtualPath == selectedEntry.virtualPath) {
			warningLines << QStringLiteral("%1: %2").arg(warning.virtualPath.isEmpty() ? tr("package") : warning.virtualPath, warning.message);
		}
	}
	if (warningLines.isEmpty()) {
		warningLines << tr("No warnings for this entry.");
	}

	const auto browserIndex = m_packageEntries->browserIndex(packageViewKey());
	const PackageArchiveSummary packageSummary = browserIndex ? browserIndex->summary : PackageArchiveSummary();
	const QVector<SummaryBucket> compositionBuckets = browserIndex ? packageCompositionBuckets(*browserIndex) : QVector<SummaryBucket>();
	QStringList compositionLines;
	if (packageSummary.totalSizeOverflow) { compositionLines << tr("Total size exceeds the supported range; proportions are unavailable."); }
	const double totalBytes = static_cast<double>(std::max<quint64>(1, packageSummary.totalSizeBytes));
	for (const SummaryBucket& bucket : compositionBuckets) {
		const double fraction = !packageSummary.totalSizeOverflow && bucket.bytes > 0 ? static_cast<double>(bucket.bytes) / totalBytes : 0.0;
		compositionLines << (packageSummary.totalSizeOverflow ? bucket.label : QStringLiteral("%1 %2").arg(compositionBar(fraction), bucket.label));
		compositionLines << tr("%1 / %2").arg(byteSizeText(bucket.bytes, bucket.sizeOverflow), tr("%n entries", nullptr, bucket.count));
	}
	if (compositionLines.isEmpty()) {
		compositionLines << tr("Package is empty.");
	}

	const OperationState entryState = !selectedEntry.note.isEmpty() ? OperationState::Warning : OperationState::Completed;
	m_packageDrawer->setTitle(tr("Package Entry Details"));
	m_packageDrawer->setSubtitle(selectedEntry.virtualPath);
	m_packageDrawer->setSections({
		{QStringLiteral("preview"), tr("Preview"), preview.summary.isEmpty() ? kindLabel : preview.summary, previewContentText(drawerPreview, !pending && !m_packagePreviewCancelled), previewState},
		{QStringLiteral("summary"), tr("Summary"), selectedEntry.typeHint, summaryLines.join('\n'), entryState},
		{QStringLiteral("preview-details"), tr("Preview Details"), kindLabel, previewDetailLines.join('\n'), previewState},
		{QStringLiteral("asset-details"), tr("Asset Details"), preview.assetKindId.isEmpty() ? kindLabel : preview.assetKindId, assetDetailLines.join('\n'), previewState},
		{QStringLiteral("asset-raw"), tr("Asset Raw Metadata"), preview.assetKindId.isEmpty() ? selectedEntry.virtualPath : preview.assetKindId, assetRawLines.join('\n'), previewState},
		{QStringLiteral("composition"), tr("Composition"), tr("%n buckets", nullptr, compositionBuckets.size()), compositionLines.join('\n'), packageSummary.warningCount > 0 || packageSummary.totalSizeOverflow ? OperationState::Warning : OperationState::Completed},
		{QStringLiteral("warnings"), tr("Warnings"), tr("%n package warnings", nullptr, packageViewArchive().warnings().size()), warningLines.join('\n'), warningLines.size() == 1 && warningLines.front() == tr("No warnings for this entry.") ? OperationState::Completed : OperationState::Warning},
		{QStringLiteral("raw"), tr("Raw Metadata"), selectedEntry.virtualPath, rawLines.join('\n'), entryState},
	});
	// A completed preview must not move a reader away from metadata or warnings.
	if (previewChanged) { m_packageDrawer->showSection(QStringLiteral("preview")); }
}

void ApplicationShell::filterPackageEntries()
{
	UiRefreshTiming timing(__func__);
	if (!m_packageEntries) { return; }
	const auto& archive = packageViewArchive();
	if (!archive.isOpen()) {
		const auto error = archive.errorString();
		m_packageEntries->showMessage(error.isEmpty() ? tr("No package loaded") : tr("Package view unavailable"), error);
		refreshPackageEntryDetails(QString()); rebuildPackageBreadcrumb(); return;
	}
	const auto filter = m_packageFilter ? m_packageFilter->text() : QString();
	const auto query = parseStudioQuery(filter);
	reportUnknownQueryKeys(m_packageFilter, query, {QStringLiteral("path"), QStringLiteral("name"), QStringLiteral("ext"), QStringLiteral("folder"),
		QStringLiteral("type"), QStringLiteral("storage"), QStringLiteral("size"), QStringLiteral("packed"), QStringLiteral("kind")});
	m_packageEntries->showEntries(archive, packageViewKey(), m_packageBrowseFolder, filter);
	rebuildPackageBreadcrumb();
}

void ApplicationShell::navigatePackageFolder(const QString& folder, const QString& selectPath, bool recordHistory)
{
	if (!m_packageArchive.isOpen()) {
		return;
	}
	m_packageBrowseFolder = folder;
	if (recordHistory) {
		if (m_packageFolderHistoryIndex >= 0 && m_packageFolderHistoryIndex < m_packageFolderHistory.size()
			&& m_packageFolderHistory.at(m_packageFolderHistoryIndex) == folder) {
			// Re-selecting the current folder is not a new history step.
		} else {
			while (m_packageFolderHistory.size() > m_packageFolderHistoryIndex + 1) {
				m_packageFolderHistory.removeLast();
			}
			m_packageFolderHistory.push_back(folder);
			m_packageFolderHistoryIndex = static_cast<int>(m_packageFolderHistory.size()) - 1;
		}
	}
	// Browsing a folder ends a search; the filter would otherwise hide it.
	if (m_packageFilter && !m_packageFilter->text().isEmpty()) {
		const QSignalBlocker blocker(m_packageFilter);
		m_packageFilter->clear();
	}
	filterPackageEntries();
	if (!selectPath.isEmpty()) { m_packageEntries->selectEntry(selectPath); }
	if (folder.isEmpty()) {
		if (m_packageTree) { const QSignalBlocker blocker(m_packageTree); m_packageTree->selectFolder(QString()); }
	} else {
		selectPackageTreeEntryPath(folder);
	}
	refreshPackageCommandEnablement();
}

void ApplicationShell::stepPackageFolderHistory(int delta)
{
	const int target = m_packageFolderHistoryIndex + delta;
	if (target < 0 || target >= m_packageFolderHistory.size()) {
		return;
	}
	m_packageFolderHistoryIndex = target;
	navigatePackageFolder(m_packageFolderHistory.at(target), QString(), false);
}

void ApplicationShell::rebuildPackageBreadcrumb()
{
	if (!m_packageBreadcrumb) {
		return;
	}
	auto* layout = qobject_cast<QHBoxLayout*>(m_packageBreadcrumb->layout());
	if (!layout) {
		return;
	}
	while (QLayoutItem* child = layout->takeAt(0)) {
		if (QWidget* widget = child->widget()) {
			// Hidden now, deleted later: a crumb waiting for deletion would
			// otherwise still be drawn under the new ones.
			widget->hide();
			widget->deleteLater();
		}
		delete child;
	}

	const bool open = packageViewArchive().isOpen();
	const bool searching = m_packageFilter && !m_packageFilter->text().trimmed().isEmpty();
	if (m_packageBack) {
		m_packageBack->setEnabled(open && m_packageFolderHistoryIndex > 0);
	}
	if (m_packageForward) {
		m_packageForward->setEnabled(open && m_packageFolderHistoryIndex >= 0 && m_packageFolderHistoryIndex + 1 < m_packageFolderHistory.size());
	}
	if (m_packageUp) {
		m_packageUp->setEnabled(open && !m_packageBrowseFolder.isEmpty());
	}
	if (!open) {
		layout->addStretch(1);
		return;
	}

	auto addCrumb = [this, layout](const QString& text, const QString& folder, bool current) {
		auto* crumb = new QToolButton;
		crumb->setObjectName(QStringLiteral("breadcrumbButton"));
		crumb->setText(text);
		crumb->setAutoRaise(true);
		crumb->setFocusPolicy(Qt::TabFocus);
		crumb->setProperty("current", current);
		crumb->setAccessibleName(tr("Folder %1").arg(text));
		crumb->setToolTip(folder.isEmpty() ? tr("Package root") : folder);
		connect(crumb, &QToolButton::clicked, this, [this, folder]() {
			navigatePackageFolder(folder);
		});
		layout->addWidget(crumb);
	};
	auto addSeparator = [layout]() {
		auto* chevron = new QLabel(QString(QChar(0x203a)));
		chevron->setObjectName(QStringLiteral("breadcrumbSeparator"));
		chevron->setAccessibleName(QString());
		layout->addWidget(chevron);
	};

	const QString rootName = QFileInfo(m_packageArchive.summary().sourcePath).fileName();
	addCrumb(rootName.isEmpty() ? tr("Package") : rootName, QString(), m_packageBrowseFolder.isEmpty() && !searching);
	QString path;
	const QStringList parts = m_packageBrowseFolder.split(QLatin1Char('/'), Qt::SkipEmptyParts);
	for (int index = 0; index < parts.size(); ++index) {
		path = path.isEmpty() ? parts.at(index) : path + QLatin1Char('/') + parts.at(index);
		addSeparator();
		addCrumb(parts.at(index), path, index == parts.size() - 1 && !searching);
	}
	if (searching) {
		addSeparator();
		auto* results = new QLabel(tr("Search results"));
		results->setObjectName(QStringLiteral("breadcrumbSeparator"));
		layout->addWidget(results);
	}
	layout->addStretch(1);
	if (m_packageSummary) { m_packageSummary->setText(m_packageEntries->busy() ? tr("Preparing…") : m_packageEntries->statusText()); }
}

void ApplicationShell::refreshCompilerPipelineSummary()
{
	if (!m_compilerPipeline) {
		return;
	}
	const QString selectedProfile = selectedCompilerProfileId();
	m_compilerPipeline->clear();
	const QString projectPath = m_settings.currentProjectPath();
	const CompilerRegistrySummary registry = discoverCompilerTools(compilerRegistryOptionsForProject(projectPath, m_settings));
	refreshCompilerToolTable(registry);
	const QVector<CompilerProfileDescriptor> profiles = compilerProfileDescriptors();
	if (profiles.isEmpty()) {
		m_compilerPipeline->addItem(disabledListItem(tr("No compiler profiles are registered.")));
		return;
	}

	for (const CompilerProfileDescriptor& profile : profiles) {
		const CompilerToolDiscovery* discovery = compilerDiscoveryForTool(registry, profile.toolId);
		OperationState state = OperationState::Failed;
		QString readiness = tr("Tool missing");
		QString executable = tr("not found");
		if (discovery) {
			state = discovery->state();
			readiness = discovery->executableAvailable ? tr("Ready") : (discovery->sourceAvailable ? tr("Source only, not built") : tr("Tool missing"));
			executable = discovery->executablePath.isEmpty() ? tr("not found") : nativePath(discovery->executablePath);
		}
		const bool ready = state == OperationState::Completed;
		const QString name = profile.displayName.isEmpty() ? profile.id : profile.displayName;
		const QString detail = tr("%1  \u00b7  %2 stage  \u00b7  %3").arg(profile.engineFamily, profile.stageId, readiness);
		auto* item = new QListWidgetItem(
			studioIcon(ready ? QStringLiteral("check") : QStringLiteral("warning"), ready ? StudioIconTone::Success : StudioIconTone::Warning),
			QStringLiteral("%1\n%2").arg(name, detail));
		item->setToolTip(tr("%1\nExecutable: %2").arg(profile.description, executable));
		item->setData(Qt::UserRole, profile.id);
		item->setData(Qt::UserRole + 1, operationStateId(state));
		item->setData(Qt::AccessibleTextRole, tr("%1, %2").arg(name, detail));
		m_compilerPipeline->addItem(item);
		if (profile.id == selectedProfile) {
			m_compilerPipeline->setCurrentItem(item);
		}
	}
	if (m_compilerRunSelected) {
		m_compilerRunSelected->setEnabled(m_compilerRunThread == nullptr);
	}
}

void ApplicationShell::refreshCompilerToolTable(const CompilerRegistrySummary& registry)
{
	if (!m_compilerTools) {
		return;
	}
	// A path can come from the user (here or `compiler set-path`) or from the
	// project manifest, which wins while the project is open.
	QHash<QString, QString> userPaths;
	for (const CompilerToolPathOverride& entry : m_settings.compilerToolPathOverrides()) {
		userPaths.insert(entry.toolId.toLower(), entry.executablePath);
	}
	QHash<QString, QString> projectPaths;
	ProjectManifest manifest;
	const QString projectPath = m_settings.currentProjectPath();
	if (!projectPath.isEmpty() && loadProjectManifest(projectPath, &manifest)) {
		for (const CompilerToolPathOverride& entry : manifest.compilerToolOverrides) {
			projectPaths.insert(entry.toolId.toLower(), entry.executablePath);
		}
	}

	const QString selected = selectedCompilerToolId();
	const QSignalBlocker blocker(m_compilerTools);
	m_compilerTools->clear();
	QTreeWidgetItem* current = nullptr;
	QTreeWidgetItem* firstMissing = nullptr;
	for (const CompilerToolDiscovery& tool : registry.tools) {
		const QString id = tool.descriptor.id;
		const QString key = id.toLower();
		const bool found = tool.executableAvailable;
		QString source = tr("Automatic");
		QString missingPath;
		if (projectPaths.contains(key)) {
			source = tool.executablePathOverridden ? tr("Project manifest") : tr("Project manifest (missing)");
			missingPath = tool.executablePathOverridden ? QString() : projectPaths.value(key);
		} else if (userPaths.contains(key)) {
			source = tool.executablePathOverridden ? tr("Chosen path") : tr("Chosen path (missing)");
			missingPath = tool.executablePathOverridden ? QString() : userPaths.value(key);
		}
		const QString name = tool.descriptor.displayName.isEmpty() ? id : tool.descriptor.displayName;
		auto* item = new QTreeWidgetItem(m_compilerTools);
		item->setText(0, name);
		item->setText(1, found ? tr("Ready") : tr("Not found"));
		item->setIcon(1, studioIcon(found ? QStringLiteral("check") : QStringLiteral("warning"), found ? StudioIconTone::Success : StudioIconTone::Warning));
		item->setText(2, found ? nativePath(tool.executablePath) : tr("Looked for %1").arg(tool.descriptor.executableNames.join(QStringLiteral(", "))));
		item->setText(3, source);
		if (!missingPath.isEmpty()) {
			item->setIcon(3, studioIcon(QStringLiteral("warning"), StudioIconTone::Warning));
		}
		item->setData(0, Qt::UserRole, id);
		item->setData(0, Qt::UserRole + 1, userPaths.contains(key));
		item->setData(0, Qt::UserRole + 2, found ? tool.executablePath : userPaths.value(key));
		QStringList tip {QStringLiteral("%1 (%2)").arg(name, id)};
		tip << tr("Engine: %1").arg(tool.descriptor.engineFamily);
		if (!missingPath.isEmpty()) {
			tip << tr("The chosen file does not exist: %1").arg(nativePath(missingPath));
		}
		item->setToolTip(0, tip.join(QLatin1Char('\n')));
		item->setToolTip(2, item->text(2));
		item->setToolTip(3, missingPath.isEmpty() ? source : tr("The chosen file does not exist: %1").arg(nativePath(missingPath)));
		item->setData(0, Qt::AccessibleTextRole, tr("%1, %2, path from %3").arg(name, item->text(1), source));
		if (id == selected) {
			current = item;
		}
		if (!found && !firstMissing) {
			firstMissing = item;
		}
	}
	// With nothing chosen yet, start on a tool that needs attention.
	if (!current) {
		current = firstMissing ? firstMissing : m_compilerTools->topLevelItem(0);
	}
	m_compilerTools->setCurrentItem(current);
	refreshCompilerToolActions();
}

void ApplicationShell::refreshCompilerToolActions()
{
	const QTreeWidgetItem* item = m_compilerTools ? m_compilerTools->currentItem() : nullptr;
	if (m_compilerLocate) {
		m_compilerLocate->setEnabled(item != nullptr);
	}
	if (m_compilerUseAutomatic) {
		m_compilerUseAutomatic->setEnabled(item && item->data(0, Qt::UserRole + 1).toBool());
	}
}

QString ApplicationShell::selectedCompilerToolId() const
{
	const QTreeWidgetItem* item = m_compilerTools ? m_compilerTools->currentItem() : nullptr;
	return item ? item->data(0, Qt::UserRole).toString() : QString();
}

void ApplicationShell::locateSelectedCompilerTool()
{
	CompilerToolDescriptor descriptor;
	if (!compilerToolDescriptorForId(selectedCompilerToolId(), &descriptor)) {
		statusBar()->showMessage(tr("Select a compiler tool first."));
		return;
	}
	const QTreeWidgetItem* item = m_compilerTools->currentItem();
	const QString known = item ? item->data(0, Qt::UserRole + 2).toString() : QString();
	const QString startDirectory = known.isEmpty() ? QString() : QFileInfo(known).absolutePath();
#ifdef Q_OS_WIN
	const QString filter = tr("Programs (*.exe);;All files (*)");
#else
	const QString filter = tr("All files (*)");
#endif
	const QString path = QFileDialog::getOpenFileName(this, tr("Locate %1").arg(descriptor.displayName), startDirectory, filter);
	if (path.isEmpty()) {
		return;
	}
	const QString executable = QFileInfo(path).absoluteFilePath();
	m_settings.upsertCompilerToolPathOverride({descriptor.id, executable});
	m_settings.sync();
	recordActivity(tr("Compiler path set"), descriptor.id, tr("compiler"), OperationState::Completed, nativePath(executable));

	QString message = tr("%1 now runs %2.").arg(descriptor.displayName, nativePath(executable));
	ProjectManifest manifest;
	const QString projectPath = m_settings.currentProjectPath();
	if (!projectPath.isEmpty() && loadProjectManifest(projectPath, &manifest)) {
		for (const CompilerToolPathOverride& entry : manifest.compilerToolOverrides) {
			if (entry.toolId.compare(descriptor.id, Qt::CaseInsensitive) == 0) {
				message = tr("Saved. While this project is open, its manifest's path for %1 is used instead.").arg(descriptor.displayName);
			}
		}
	}
	compilerToolPathsChanged(message);
}

void ApplicationShell::clearSelectedCompilerToolPath()
{
	CompilerToolDescriptor descriptor;
	if (!compilerToolDescriptorForId(selectedCompilerToolId(), &descriptor)) {
		statusBar()->showMessage(tr("Select a compiler tool first."));
		return;
	}
	m_settings.removeCompilerToolPathOverride(descriptor.id);
	m_settings.sync();
	recordActivity(tr("Compiler path cleared"), descriptor.id, tr("compiler"), OperationState::Completed, tr("Found automatically again."));
	compilerToolPathsChanged(tr("%1 is found automatically again.").arg(descriptor.displayName));
}

void ApplicationShell::compilerToolPathsChanged(const QString& message)
{
	// The status chip caches discovery for a few seconds; a changed path has
	// to show everywhere at once.
	m_compilerChipProbedAtMs = -1;
	refreshCompilerPipelineSummary();
	refreshBuildSurface();
	refreshStatusChips();
	refreshWorkspaceDashboard();
	statusBar()->showMessage(message);
}

QString ApplicationShell::selectedCompilerProfileId() const
{
	const QListWidgetItem* item = m_compilerPipeline ? m_compilerPipeline->currentItem() : nullptr;
	return item ? item->data(Qt::UserRole).toString() : QString();
}

void ApplicationShell::runSelectedCompilerProfile()
{
	if (m_compilerRunThread) {
		statusBar()->showMessage(tr("A compiler task is already running"));
		return;
	}

	const QString profileId = selectedCompilerProfileId();
	CompilerProfileDescriptor profile;
	if (!compilerProfileForId(profileId, &profile)) {
		statusBar()->showMessage(tr("Select a compiler profile first"));
		return;
	}

	const QString projectPath = m_settings.currentProjectPath();
	ProjectManifest manifest;
	if (projectPath.isEmpty() || !loadProjectManifest(projectPath, &manifest)) {
		manifest = defaultProjectManifest(projectPath.isEmpty() ? QDir::currentPath() : projectPath);
	}

	CompilerRunRequest runRequest;
	runRequest.command.profileId = profile.id;
	runRequest.command.workspaceRootPath = manifest.rootPath;
	runRequest.command.inputPath = firstProjectInputForProfile(profile, manifest);
	runRequest.command.extraSearchPaths = effectiveProjectCompilerSearchPaths(manifest);
	runRequest.command.executableOverrides = effectiveProjectCompilerToolOverrides(manifest, m_settings.compilerToolPathOverrides());
	runRequest.registerOutputs = true;
	runRequest.manifestPath = QDir(manifest.rootPath).filePath(QStringLiteral(".vibestudio/compiler-runs/%1-%2.json").arg(profile.id, QDateTime::currentDateTimeUtc().toString(QStringLiteral("yyyyMMddTHHmmssZ"))));

	if (profile.inputRequired && runRequest.command.inputPath.isEmpty()) {
		const QString taskId = m_activity.createTask(tr("Compiler Run"), profile.id, tr("compiler"), OperationState::Warning, false);
		m_activity.appendWarning(taskId, tr("No %1 input file was found in the project source folders.").arg(profile.inputDescription));
		m_activity.completeTask(taskId, tr("Compiler run needs an input file."));
		persistActivityTask(taskId);
		refreshActivityCenter(taskId);
		statusBar()->showMessage(tr("Compiler input file not found"));
		return;
	}

	m_compilerRunCancelRequested.store(false);
	m_compilerRunActivityId = m_activity.createTask(tr("Compiler Run"), profile.displayName, tr("compiler"), OperationState::Running, true);
	m_activity.setProgress(m_compilerRunActivityId, 0, 4, tr("Planning compiler command."));
	refreshActivityCenter(m_compilerRunActivityId);
	statusBar()->showMessage(tr("Compiler run started: %1").arg(profile.displayName));

	const QString taskId = m_compilerRunActivityId;
	auto* thread = QThread::create([this, runRequest, taskId, projectPath]() {
		CompilerRunCallbacks callbacks;
		callbacks.cancellationRequested = [this]() {
			return m_compilerRunCancelRequested.load();
		};
		callbacks.logEntry = [this, taskId](const CompilerTaskLogEntry& entry) {
			QMetaObject::invokeMethod(this, [this, taskId, entry]() {
				m_activity.appendLog(taskId, OperationState::Running, entry.message);
				// A streamed line updates the task's details only while the user
				// is looking at that task; it never moves the selection.
				if (selectedActivityTaskId() == taskId) {
					refreshActivityDetails(taskId);
				}
			}, Qt::QueuedConnection);
		};
		CompilerRunResult result = runCompilerCommand(runRequest, callbacks);
		QMetaObject::invokeMethod(this, [this, result, taskId, projectPath]() {
			finishCompilerRun(result, taskId, projectPath);
		}, Qt::QueuedConnection);
	});
	m_compilerRunThread = thread;
	connect(thread, &QThread::finished, thread, &QObject::deleteLater);
	thread->start();
}

void ApplicationShell::finishCompilerRun(const CompilerRunResult& result, const QString& taskId, const QString& projectPath)
{
	if (m_compilerRunThread) {
		m_compilerRunThread = nullptr;
	}
	m_compilerRunActivityId.clear();
	m_compilerRunCancelRequested.store(false);

	m_activity.setProgress(taskId, 4, 4, tr("Compiler run finished."));
	for (const QString& warning : result.manifest.warnings) {
		m_activity.appendWarning(taskId, warning);
	}
	if (!result.stdoutText.trimmed().isEmpty()) {
		m_activity.appendLog(taskId, OperationState::Running, tr("Stdout: %1").arg(result.stdoutText.trimmed().left(1000)));
	}
	if (!result.stderrText.trimmed().isEmpty()) {
		m_activity.appendLog(taskId, OperationState::Warning, tr("Stderr: %1").arg(result.stderrText.trimmed().left(1000)));
	}
	if (!result.registeredOutputPaths.isEmpty()) {
		ProjectManifest manifest;
		QString error;
		if (loadProjectManifest(projectPath, &manifest, &error)) {
			registerProjectOutputPaths(&manifest, result.registeredOutputPaths);
			saveOwnProjectManifest(manifest, &error);
		}
	}

	const QString summary = tr("%1 in %2 ms / outputs: %3 / manifest: %4")
		.arg(localizedOperationStateName(result.state))
		.arg(result.durationMs)
		.arg(result.registeredOutputPaths.isEmpty() ? tr("none") : QString::number(result.registeredOutputPaths.size()))
		.arg(nativePath(result.manifestPath));
	if (result.state == OperationState::Completed || result.state == OperationState::Warning) {
		m_activity.completeTask(taskId, summary);
	} else if (result.state == OperationState::Cancelled) {
		m_activity.transitionTask(taskId, OperationState::Running);
		m_activity.cancelTask(taskId, summary);
	} else {
		m_activity.failTask(taskId, result.error.isEmpty() ? summary : result.error);
	}

	persistActivityTask(taskId);
	refreshCompilerPipelineSummary();
	refreshWorkspaceContextPanels();
	refreshWorkspaceDashboard();
	refreshActivityCenter(taskId);
	statusBar()->showMessage(summary);
}

