bool pathLooksLikePackage(const QString& path)
{
	const QFileInfo info(path);
	if (info.isDir()) {
		return true;
	}
	return packageArchiveFormatFromFileName(info.fileName()) != PackageArchiveFormat::Unknown;
}

// A .wad is one of two formats. IWAD and PWAD files hold Doom maps; WAD2 and
// WAD3 files hold Quake and Half-Life textures and belong in the package
// browser, so the four-byte magic decides.
bool wadHoldsTextures(const QString& path)
{
	QFile file(path);
	if (!file.open(QIODevice::ReadOnly)) {
		return false;
	}
	const QByteArray magic = file.read(4);
	return magic == QByteArrayLiteral("WAD2") || magic == QByteArrayLiteral("WAD3");
}

bool pathLooksLikeMap(const QString& path)
{
	const QString suffix = QFileInfo(path).suffix().toLower();
	if (suffix == QStringLiteral("wad")) {
		// A Doom WAD with no maps holds resources (sounds, graphics), so it
		// opens as a package.
		return !wadHoldsTextures(path) && !levelMapNamesInWad(path).isEmpty();
	}
	return suffix == QStringLiteral("map");
}

// The object written at `line` of a map's source text: the brush or patch
// there, else the entity around it. Compilers report positions as lines of the
// .map file. Empty when no object covers the line.
QString levelMapSelectorForLine(const LevelMapDocument& document, int line)
{
	if (line <= 0) {
		return {};
	}
	for (const LevelMapBrush& brush : document.brushes) {
		if (line >= brush.startLine && line <= brush.endLine) {
			return QStringLiteral("%1:%2").arg(levelMapSelectionKindId(LevelMapSelectionKind::QuakeBrush)).arg(brush.id);
		}
	}
	for (const LevelMapPatch& patch : document.patches) {
		if (line >= patch.startLine && line <= patch.endLine) {
			return QStringLiteral("%1:%2").arg(levelMapSelectionKindId(LevelMapSelectionKind::QuakePatch)).arg(patch.id);
		}
	}
	for (const LevelMapEntity& entity : document.entities) {
		if (line >= entity.startLine && line <= entity.endLine) {
			return QStringLiteral("%1:%2").arg(levelMapSelectionKindId(LevelMapSelectionKind::Entity)).arg(entity.id);
		}
	}
	return {};
}

