	// Line operations on the open file; a read-only package copy says why
	// nothing happens.
	auto lineOperation = [this](const std::function<bool(StudioCodeEditor*)>& operation) {
		auto* editor = dynamic_cast<StudioCodeEditor*>(m_codeEditor);
		if (!editor || !hasCodeDocument()) {
			return;
		}
		if (editor->isReadOnly()) {
			statusBar()->showMessage(tr("This file is a read-only copy; open the original to edit it."));
			return;
		}
		operation(editor);
	};
	add(QStringLiteral("code.toggleComment"), StudioCommandGroup::Edit, tr("Toggle Line &Comment"),
		tr("Comment or uncomment the selected lines with the file type's line comment."), QStringLiteral("code"), false, false, false,
		[this, lineOperation]() {
			StudioLanguageDescriptor descriptor;
			studioLanguageDescriptorFor(studioLanguageForPath(m_codeFilePath), &descriptor);
			const QString token = descriptor.lineCommentTokens.value(0);
			if (token.isEmpty()) {
				statusBar()->showMessage(tr("This file type has no line comments."));
				return;
			}
			lineOperation([token](StudioCodeEditor* editor) { return editor->toggleLineComment(token); });
		});
