StudioSpeech& ApplicationShell::speech()
{
	if (!m_speech) {
		m_speech = std::make_unique<StudioSpeech>();
		applySpeechPreferences();
	}
	return *m_speech;
}

void ApplicationShell::applySpeechPreferences()
{
	if (!m_speech) {
		return;
	}
	const AccessibilityPreferences preferences = m_settings.accessibilityPreferences();
	SpeechSettings settings;
	settings.voiceId = preferences.speechVoice;
	settings.rate = preferences.speechRate;
	settings.pitch = preferences.speechPitch;
	settings.volume = preferences.speechVolume;
	m_speech->setSettings(settings);
}

void ApplicationShell::refreshSpeechControls()
{
	if (!m_speechVoiceCombo) {
		return;
	}
	const AccessibilityPreferences preferences = m_settings.accessibilityPreferences();
	// The engine starts only once someone looks at Speech or uses it, so a
	// session that never speaks never pays for it.
	const bool load = m_speech || m_speechVoiceCombo->isVisible() || preferences.textToSpeechEnabled;
	const QSignalBlocker voiceBlocker(m_speechVoiceCombo);
	if (load) {
		StudioSpeech& engine = speech();
		const SpeechCapabilities capabilities = engine.capabilities();
		if (m_speechVoiceCombo->count() <= 1 && engine.available()) {
			for (const SpeechVoice& voice : engine.voices()) {
				m_speechVoiceCombo->addItem(voice.language.isEmpty() ? voice.name : tr("%1 (%2)").arg(voice.name, voice.language), voice.id);
			}
		}
		m_speechVoiceCombo->setEnabled(engine.available() && capabilities.voices);
		m_speechRate->setEnabled(engine.available() && capabilities.rate);
		m_speechPitch->setEnabled(engine.available() && capabilities.pitch);
		m_speechVolume->setEnabled(engine.available() && capabilities.volume);
		m_speechTest->setEnabled(engine.available());
		QString status = engine.available()
			? tr("Speaks with %1, on this computer.").arg(engine.engineName())
			: tr("Nothing can be read aloud: %1").arg(engine.unavailableReason());
		if (engine.available() && (!capabilities.pitch || !capabilities.volume)) {
			status += QLatin1Char(' ') + tr("Pitch and volume follow the system's voice settings with this engine.");
		}
		m_speechStatus->setText(status);
	} else {
		m_speechStatus->setText(tr("The speech engine starts when speech is turned on or tested."));
	}
	const int voiceIndex = m_speechVoiceCombo->findData(preferences.speechVoice);
	m_speechVoiceCombo->setCurrentIndex(std::max(0, voiceIndex));
	for (auto it = m_speechEventBoxes.cbegin(); it != m_speechEventBoxes.cend(); ++it) {
		const QSignalBlocker blocker(it.value());
		it.value()->setChecked(preferences.speechEvents.contains(it.key()));
		it.value()->setEnabled(preferences.textToSpeechEnabled);
	}
	for (QSlider* slider : {m_speechRate, m_speechPitch, m_speechVolume}) {
		const QSignalBlocker blocker(slider);
		slider->setValue(slider == m_speechRate ? preferences.speechRate : (slider == m_speechPitch ? preferences.speechPitch : preferences.speechVolume));
		slider->setToolTip(tr("%1: %2").arg(slider->accessibleName()).arg(slider->value()));
	}
}

void ApplicationShell::speakEvent(const QString& eventId, const QString& text)
{
	if (text.trimmed().isEmpty()) {
		return;
	}
	const AccessibilityPreferences preferences = m_settings.accessibilityPreferences();
	if (!preferences.textToSpeechEnabled || !preferences.speechEvents.contains(eventId)) {
		return;
	}
	speech().say(text);
}

void ApplicationShell::noteTaskOutcome(const OperationTask& task)
{
	if (task.id.isEmpty() || !operationStateIsTerminal(task.state)) {
		return;
	}
	const QString key = QStringLiteral("%1/%2").arg(task.id, operationStateId(task.state));
	if (m_reportedTaskOutcomes.contains(key)) {
		return;
	}
	m_reportedTaskOutcomes.insert(key);
	if (!m_accessibilityAnnouncementsReady) {
		return;
	}
	// Worth telling: anything that went wrong, and work that took long enough
	// for the user to have turned to something else. Instant confirmations
	// already show in the status bar.
	const bool problem = task.state == OperationState::Failed || task.state == OperationState::Warning || task.state == OperationState::Cancelled;
	if (!problem && operationTaskElapsedMs(task) < 1500) {
		return;
	}
	const QString summary = (task.resultSummary.trimmed().isEmpty() ? task.detail : task.resultSummary).simplified();
	const QString message = summary.isEmpty()
		? tr("%1: %2").arg(task.title, localizedOperationStateName(task.state))
		: tr("%1, %2: %3").arg(task.title, localizedOperationStateName(task.state), summary);
	const AccessibilityPreferences preferences = m_settings.accessibilityPreferences();
	if (preferences.screenReaderAnnouncements) {
		announceToScreenReader(this, message, task.state == OperationState::Failed);
	}
	speakEvent(problem ? QStringLiteral("task-problems") : QStringLiteral("task-results"), message);
	if (preferences.soundCues) {
		playSoundCue(task.state == OperationState::Failed ? SoundCue::Failure : problem ? SoundCue::Warning : SoundCue::Success);
	}
	if (preferences.visualAlerts && !isActiveWindow()) {
		QApplication::alert(this);
	}
}

void ApplicationShell::playSoundCue(SoundCue cue)
{
	if (!m_soundCuePlayer) {
		m_soundCuePlayer = new StudioSoundCues(this);
	}
	m_soundCuePlayer->play(cue, m_settings.accessibilityPreferences().soundCueVolume);
}

void ApplicationShell::testSoundCues()
{
	// In turn, far enough apart to tell each from the next.
	playSoundCue(SoundCue::Success);
	QTimer::singleShot(700, this, [this]() { playSoundCue(SoundCue::Warning); });
	QTimer::singleShot(1400, this, [this]() { playSoundCue(SoundCue::Failure); });
}

void ApplicationShell::handleStatusMessage(const QString& text)
{
	if (text.isEmpty()) {
		return;
	}
	applyStatusMessageDuration(statusBar(), m_messageDuration);
	if (!m_accessibilityAnnouncementsReady) {
		return;
	}
	// A burst of messages (a drag, a scan) settles first: only the last of it
	// is read, and never the same words twice running.
	m_pendingStatusAnnouncement = text;
	if (!m_statusAnnouncementTimer) {
		m_statusAnnouncementTimer = new QTimer(this);
		m_statusAnnouncementTimer->setSingleShot(true);
		m_statusAnnouncementTimer->setInterval(450);
		connect(m_statusAnnouncementTimer, &QTimer::timeout, this, [this]() {
			const QString message = m_pendingStatusAnnouncement;
			if (message.isEmpty() || message == m_lastStatusAnnouncement || statusBar()->currentMessage() != message) {
				return;
			}
			m_lastStatusAnnouncement = message;
			if (m_settings.accessibilityPreferences().screenReaderAnnouncements) {
				announceToScreenReader(statusBar(), message);
			}
			speakEvent(QStringLiteral("status-messages"), message);
		});
	}
	m_statusAnnouncementTimer->start();
}

void ApplicationShell::readAloud()
{
	QString text;
	QWidget* focus = QApplication::focusWidget();
	if (auto* plain = qobject_cast<QPlainTextEdit*>(focus)) {
		const QTextCursor cursor = plain->textCursor();
		text = cursor.hasSelection() ? cursor.selectedText() : cursor.block().text();
	} else if (auto* rich = qobject_cast<QTextEdit*>(focus)) {
		const QTextCursor cursor = rich->textCursor();
		text = cursor.hasSelection() ? cursor.selectedText() : cursor.block().text();
	} else if (auto* line = qobject_cast<QLineEdit*>(focus)) {
		// A password or key field is never read out.
		if (line->echoMode() == QLineEdit::Normal) {
			text = line->hasSelectedText() ? line->selectedText() : line->text();
		}
	} else if (auto* view = qobject_cast<QAbstractItemView*>(focus)) {
		const QModelIndex index = view->currentIndex();
		text = index.data(Qt::AccessibleTextRole).toString();
		if (text.isEmpty()) {
			text = index.data(Qt::DisplayRole).toString();
		}
	} else if (focus) {
		text = focus->accessibleName();
		if (auto* button = qobject_cast<QAbstractButton*>(focus); button && text.isEmpty()) {
			text = button->text().remove(QLatin1Char('&'));
		}
		if (!focus->accessibleDescription().isEmpty()) {
			text = tr("%1. %2").arg(text, focus->accessibleDescription());
		}
	}
	if (text.trimmed().isEmpty()) {
		text = statusBar()->currentMessage();
	}
	// A text selection separates paragraphs with U+2029.
	text.replace(QChar::ParagraphSeparator, QLatin1Char('\n'));
	if (text.trimmed().isEmpty()) {
		statusBar()->showMessage(tr("Nothing to read aloud: select text, or move focus to what should be read."));
		return;
	}
	StudioSpeech& engine = speech();
	if (!engine.say(text.left(5000))) {
		statusBar()->showMessage(tr("Nothing can be read aloud: %1").arg(engine.unavailableReason()));
	}
}

void ApplicationShell::stopSpeaking()
{
	if (m_speech) {
		m_speech->stop();
	}
}

void ApplicationShell::testSpeech()
{
	StudioSpeech& engine = speech();
	applySpeechPreferences();
	// No status message on success: reading it out would cut the phrase off.
	if (!engine.say(speechTestPhrase())) {
		statusBar()->showMessage(tr("The test phrase could not be spoken: %1").arg(engine.unavailableReason()));
	}
	refreshSpeechControls();
}

void ApplicationShell::stepTextScale(int direction)
{
	static constexpr int kScales[] = {100, 125, 150, 175, 200};
	AccessibilityPreferences preferences = m_settings.accessibilityPreferences();
	int index = 0;
	for (int candidate = 0; candidate < static_cast<int>(std::size(kScales)); ++candidate) {
		if (kScales[candidate] <= preferences.textScalePercent) {
			index = candidate;
		}
	}
	const int next = direction == 0 ? 100 : kScales[std::clamp(index + (direction > 0 ? 1 : -1), 0, static_cast<int>(std::size(kScales)) - 1)];
	if (next == preferences.textScalePercent) {
		statusBar()->showMessage(direction > 0 ? tr("Text is at its largest scale, 200%.") : (direction < 0 ? tr("Text is at its smallest scale, 100%.") : tr("Text scale: %1%").arg(next)));
		return;
	}
	preferences.textScalePercent = next;
	m_settings.setAccessibilityPreferences(preferences);
	m_settings.sync();
	refreshPreferenceControls();
	applyPreferencesToUi();
	statusBar()->showMessage(tr("Text scale: %1%").arg(next));
}

void ApplicationShell::toggleHighContrastTheme()
{
	AccessibilityPreferences preferences = m_settings.accessibilityPreferences();
	const StudioTheme effective = effectiveStudioTheme(preferences.theme);
	const bool highContrast = effective == StudioTheme::HighContrastDark || effective == StudioTheme::HighContrastLight;
	const bool light = effective == StudioTheme::Light || effective == StudioTheme::HighContrastLight;
	preferences.theme = highContrast ? (light ? StudioTheme::Light : StudioTheme::Dark) : (light ? StudioTheme::HighContrastLight : StudioTheme::HighContrastDark);
	m_settings.setAccessibilityPreferences(preferences);
	m_settings.sync();
	refreshPreferenceControls();
	applyPreferencesToUi();
	statusBar()->showMessage(tr("Theme: %1").arg(localizedThemeName(preferences.theme)));
}

void ApplicationShell::refreshLanguageRestartNotice()
{
	if (!m_languageRestartNotice) {
		return;
	}
	const QString wanted = normalizedLocalizationTargetId(m_settings.accessibilityPreferences().localeName);
	if (wanted == activeInterfaceLanguage()) {
		m_languageRestartNotice->hide();
		return;
	}
	m_languageRestartNotice->showNotice(QStringLiteral("queued"), tr("Restart to change the language"),
		tr("The interface will be in %1 after a restart. Unsaved work is offered for saving first, and the session reopens.").arg(localeDisplayName(wanted)));
	QPushButton* restart = m_languageRestartNotice->addAction(tr("Restart Now"), QStringLiteral("refresh"), true);
	restart->setObjectName(QStringLiteral("languageRestartNow"));
	connect(restart, &QPushButton::clicked, this, &ApplicationShell::restartToApplyLanguage);
}

void ApplicationShell::restartToApplyLanguage()
{
	QStringList arguments;
	const QString settingsFile = StudioSettings::overrideFilePath();
	if (!settingsFile.isEmpty()) {
		arguments << QStringLiteral("--settings-file") << settingsFile;
	}
	// The window closes through its usual save prompts; cancelling one keeps
	// the studio open and nothing restarts.
	m_restartPending = true;
	if (!close()) {
		m_restartPending = false;
		statusBar()->showMessage(tr("Restart cancelled: the studio stays open in its current language."));
		return;
	}
	requestStudioRestart(arguments);
	QTimer::singleShot(0, qApp, []() { QCoreApplication::quit(); });
}

void ApplicationShell::activateStatusChip(QAbstractButton* chip)
{
	if (!chip) {
		return;
	}
	if (chip == m_projectChip) {
		setMode(StudioMode::Workspace);
	} else if (chip == m_packageChip) {
		setMode(StudioMode::Packages);
	} else if (chip == m_installChip) {
		setMode(StudioMode::Workspace);
		if (m_gameInstallations) {
			for (QWidget* parent = m_gameInstallations->parentWidget(); parent; parent = parent->parentWidget()) {
				if (auto* scroll = qobject_cast<QScrollArea*>(parent)) {
					scroll->ensureWidgetVisible(m_gameInstallations);
					break;
				}
			}
			m_gameInstallations->setFocus(Qt::OtherFocusReason);
		}
	} else if (chip == m_compilerChip) {
		setMode(StudioMode::Build);
		if (m_buildSections) {
			m_buildSections->setCurrentIndex(1);
		}
	} else if (chip == m_aiChip) {
		showAssistant();
	}
}

void ApplicationShell::showAssetContextMenu(QListWidget* list, StudioMode mode, const QPoint& position)
{
	QListWidgetItem* item = list ? list->itemAt(position) : nullptr;
	const QString virtualPath = item ? item->data(Qt::UserRole).toString() : QString();
	if (virtualPath.isEmpty()) {
		return;
	}
	list->setCurrentItem(item);
	QMenu menu(this);
	menu.setAccessibleName(tr("Asset actions"));
	QAction* reveal = menu.addAction(studioIcon(QStringLiteral("package")), tr("Show in Packages"));
	QAction* copyPath = menu.addAction(studioIcon(QStringLiteral("copy")), tr("Copy Path"));
	// A texture can go straight into the open map, replacing one it uses.
	QAction* useInMap = nullptr;
	QAction* applyToSelection = nullptr;
	QAction* useForPainting = nullptr;
	QAction* selectInMap = nullptr;
	QAction* showInMaterials = nullptr;
	if (mode == StudioMode::Textures) {
		showInMaterials = menu.addAction(studioIcon(QStringLiteral("shaders")), tr("Show in Materials"));
		showInMaterials->setToolTip(tr("Show the shaders and materials that read this image, drawn the way the game draws them."));
		const bool quakeFamilyMap = m_levelMapDocument.format == LevelMapFormat::QuakeMap || m_levelMapDocument.format == LevelMapFormat::Quake3Map;
		selectInMap = menu.addAction(studioIcon(QStringLiteral("filter")), tr("Select in Open Map"));
		selectInMap->setToolTip(tr("Select what uses this texture in the map open in Levels."));
		selectInMap->setEnabled(m_levelMapDocument.format != LevelMapFormat::Unknown && !m_levelMapDocument.textureReferences.isEmpty());
		applyToSelection = menu.addAction(studioIcon(QStringLiteral("image")), tr("Apply to Map Selection"));
		applyToSelection->setToolTip(tr("Put this texture on every face of the brushes and patches selected in Levels."));
		applyToSelection->setEnabled(quakeFamilyMap && !m_levelMapDocument.selection.isEmpty());
		useForPainting = menu.addAction(studioIcon(QStringLiteral("image")), tr("Use for Map Painting"));
		useForPainting->setEnabled(quakeFamilyMap || levelMapDoomEditable());
		useInMap = menu.addAction(studioIcon(QStringLiteral("map")), tr("Use in Open Map…"));
		useInMap->setToolTip(tr("Replace a texture the open map uses with this one."));
		useInMap->setEnabled(m_levelMapDocument.format != LevelMapFormat::Unknown && !m_levelMapDocument.textureReferences.isEmpty());
	}
	menu.addSeparator();
	QAction* exportAction = nullptr;
	switch (mode) {
	case StudioMode::Textures:
		exportAction = menu.addAction(studioIcon(QStringLiteral("export")), tr("Export PNG…"));
		break;
	case StudioMode::Models:
		exportAction = menu.addAction(studioIcon(QStringLiteral("export")), tr("Export Frame as OBJ…"));
		break;
	case StudioMode::Audio:
		exportAction = menu.addAction(studioIcon(QStringLiteral("export")), tr("Export WAV…"));
		break;
	default:
		break;
	}
	QAction* chosen = menu.exec(list->viewport()->mapToGlobal(position));
	if (chosen == reveal) {
		revealPackageEntry(virtualPath);
	} else if (chosen == copyPath) {
		QGuiApplication::clipboard()->setText(virtualPath);
		statusBar()->showMessage(tr("Path copied: %1").arg(virtualPath));
	} else if (chosen && chosen == showInMaterials) {
		showMaterialsForImage(virtualPath);
	} else if (chosen && chosen == selectInMap) {
		setMode(StudioMode::Levels);
		selectLevelMapObjectsByTexture(mapTextureNameForEntry(virtualPath));
	} else if (chosen && chosen == applyToSelection) {
		setMode(StudioMode::Levels);
		applyLevelMapTextureFromUi(mapTextureNameForEntry(virtualPath));
	} else if (chosen && chosen == useForPainting) {
		setMode(StudioMode::Levels);
		chooseLevelPaintMaterial(mapTextureNameForEntry(virtualPath));
		setLevelMaterialTool(1);
	} else if (chosen && chosen == useInMap) {
		setMode(StudioMode::Levels);
		showReplaceTextureDialog(mapTextureNameForEntry(virtualPath));
	} else if (chosen && chosen == exportAction) {
		if (mode == StudioMode::Textures) {
			exportSelectedTexture();
		} else if (mode == StudioMode::Models) {
			exportSelectedModel();
		} else if (mode == StudioMode::Audio) {
			exportSelectedAudio();
		}
	}
}

void ApplicationShell::activateShaderGraphItem(QTreeWidgetItem* item)
{
	if (!item) {
		return;
	}
	// A texture row shows the texture; a shader or stage row opens the script
	// in the code editor at its line.
	const QString reference = item->data(0, Qt::UserRole + 2).toString();
	if (!reference.isEmpty()) {
		showTextureReference(reference);
		return;
	}
	const QString scriptPath = m_advancedShaderDocument.sourcePath.isEmpty() && m_advancedShaderPath
		? m_advancedShaderPath->text().trimmed()
		: m_advancedShaderDocument.sourcePath;
	const int line = item->data(0, Qt::UserRole + 3).toInt();
	if (!scriptPath.isEmpty() && line > 0) {
		openCodeFileAt(scriptPath, line);
	}
}

void ApplicationShell::showShaderGraphContextMenu(const QPoint& position)
{
	QTreeWidgetItem* item = m_advancedShaderGraph ? m_advancedShaderGraph->itemAt(position) : nullptr;
	if (!item) {
		return;
	}
	m_advancedShaderGraph->setCurrentItem(item);
	const QString reference = item->data(0, Qt::UserRole + 2).toString();
	QMenu menu(this);
	menu.setAccessibleName(tr("Shader actions"));
	QAction* showTexture = nullptr;
	if (!reference.isEmpty()) {
		showTexture = menu.addAction(studioIcon(QStringLiteral("image")), tr("Show Texture"));
		showTexture->setEnabled(!resolveTextureReference(reference).isEmpty());
	}
	QAction* openScript = menu.addAction(studioIcon(QStringLiteral("code")), tr("Open in Code Editor"));
	QAction* copy = menu.addAction(studioIcon(QStringLiteral("copy")), reference.isEmpty() ? tr("Copy Shader Name") : tr("Copy Texture Path"));
	QAction* chosen = menu.exec(m_advancedShaderGraph->viewport()->mapToGlobal(position));
	if (chosen && chosen == showTexture) {
		showTextureReference(reference);
	} else if (chosen == openScript) {
		const QString scriptPath = m_advancedShaderDocument.sourcePath.isEmpty() && m_advancedShaderPath
			? m_advancedShaderPath->text().trimmed()
			: m_advancedShaderDocument.sourcePath;
		openCodeFileAt(scriptPath, std::max(1, item->data(0, Qt::UserRole + 3).toInt()));
	} else if (chosen == copy) {
		QGuiApplication::clipboard()->setText(reference.isEmpty() ? item->data(0, Qt::UserRole).toString() : reference);
	}
}

void ApplicationShell::showBuildStageDetails(const QString& stageId)
{
	if (!m_buildPipelineDrawer || stageId.isEmpty()) {
		return;
	}
	const QString sectionId = QStringLiteral("stage-%1").arg(stageId);
	for (const DetailSection& section : m_buildPipelineDrawer->sections()) {
		if (section.id == sectionId) {
			m_buildPipelineDrawer->showSection(sectionId);
			return;
		}
	}
	// Before a run there is only the plan, which covers every stage.
	m_buildPipelineDrawer->showSection(QStringLiteral("plan"));
}

void ApplicationShell::exportSelectedAudio()
{
	QListWidgetItem* item = m_audioEntries ? m_audioEntries->currentItem() : nullptr;
	const QString virtualPath = item && item->isSelected() ? item->data(Qt::UserRole).toString() : QString();
	if (virtualPath.isEmpty() || !m_audioArchive.isOpen()) {
		statusBar()->showMessage(tr("Select a sound to export."));
		return;
	}
	const QString suggested = QFileInfo(virtualPath).completeBaseName() + QStringLiteral(".wav");
	const PackageArchive archive = m_audioArchive;
	const qsizetype entryIndex = item->data(Qt::UserRole + 6).toLongLong();
	const QString target = QFileDialog::getSaveFileName(this, tr("Export Sound As WAV"), suggested, tr("WAV audio (*.wav)"));
	if (target.isEmpty()) {
		return;
	}
	struct Work { std::atomic_bool cancel{false}; AssetAudioExportReport report; };
	auto state = std::make_shared<Work>();
	auto* progress = new QProgressDialog(tr("Converting and saving %1…").arg(virtualPath), tr("Cancel"), 0, 0, this);
	auto* progressLabel = new QLabel(tr("Converting and saving %1…").arg(virtualPath), progress);
	progressLabel->setTextFormat(Qt::PlainText);
	progressLabel->setWordWrap(true);
	progress->setLabel(progressLabel);
	progress->setObjectName(QStringLiteral("audioBrowserExportProgress"));
	progress->setWindowTitle(tr("Export Sound"));
	progress->setAccessibleName(tr("Audio WAV export progress"));
	progress->setAccessibleDescription(tr("Cancellation stops preparation. Atomic writing completes once it has begun."));
	progress->setWindowModality(Qt::WindowModal);
	progress->setMinimumDuration(0);
	progress->setAutoClose(false);
	connect(progress, &QProgressDialog::canceled, this, [state] { state->cancel = true; });
	auto* worker = QThread::create([state, archive, entryIndex, target] {
		state->report = exportPackageAudioToWavAt(archive, entryIndex, target, false, true, [state] { return state->cancel.load(); });
	});
	connect(this, &QObject::destroyed, worker, [state] { state->cancel = true; });
	connect(worker, &QThread::finished, this, [this, state, progress, virtualPath, target] {
		progress->close(); progress->deleteLater();
		const auto& report = state->report;
		if (report.cancelled) {
			statusBar()->showMessage(tr("Audio export cancelled. No output was written."));
			return;
		}
		if (!report.succeeded()) {
			QMessageBox::warning(this, tr("Export Failed"), report.error.isEmpty() ? tr("%1 could not be exported.").arg(virtualPath) : report.error);
			return;
		}
		recordActivity(tr("Export Sound"), nativePath(target), tr("asset"), OperationState::Completed,
			(report.converted ? tr("Converted %1 to 16-bit PCM WAV.").arg(virtualPath) : tr("Copied %1 without re-encoding.").arg(virtualPath)) + QLatin1Char('\n') + report.detailLines.join(QLatin1Char('\n')));
		statusBar()->showMessage(tr("Sound written to %1").arg(nativePath(target)));
	});
	connect(worker, &QThread::finished, worker, &QObject::deleteLater);
	connect(qApp, &QCoreApplication::aboutToQuit, worker, [worker, state] { state->cancel = true; worker->wait(); });
	progress->show(); worker->start();
}

void ApplicationShell::runCommand(const QString& commandId)
{
	if (!m_commands) {
		return;
	}
	if (QAction* action = m_commands->action(commandId)) {
		if (action->isEnabled()) {
			action->trigger();
			return;
		}
		statusBar()->showMessage(tr("Command is not available right now: %1").arg(action->text()));
		return;
	}
	statusBar()->showMessage(tr("Command is documented but not implemented in this build: %1").arg(commandId));
}

void ApplicationShell::refreshPackageCommandEnablement()
{
	UiRefreshTiming timing(__func__);
	if (!m_commands) { return; }
	const bool idle = !m_packageReadRunning && !m_packageSaveRunning && !m_packageExtractionRunning;
	const bool packageReady = idle && m_packageArchive.isOpen();
	const bool documentReady = packageReady && m_packageStaging.isLoaded();
	const auto index = selectedPackageEntryIndex();
	const bool selected = packageReady && index >= 0;
	const bool editable = documentReady && selected;
	const bool fileSelected = editable && packageViewArchive().entries().at(index).kind == PackageEntryKind::File;
	const auto set = [this](const char* id, bool enabled, QAbstractButton* button = nullptr) {
		const auto key = QString::fromLatin1(id);
		m_commands->setEnabled(key, enabled);
		if (button) { button->setEnabled(m_commands->action(key)->isEnabled()); }
	};
	// Apply each final state once, including restoring open commands after a
	// worker finishes. Selection changes must not transiently enable busy work.
	set("package.new", idle, m_packageNew);
	for (const char* id : {"package.open", "package.openFolder", "package.openDraft", "package.recover"}) { set(id, idle); }
	set("package.close", packageReady);
	set("package.createDirectory", documentReady && m_packageStaging.sourceFormat() != PackageArchiveFormat::Wad, m_packageCreateDirectory);
	set("package.extractSelected", selected, m_packageExtractSelected);
	set("package.extractAll", packageReady, m_packageExtractAll);
	set("package.stageAdd", documentReady, m_packageStageAdd);
	set("package.stageReplace", fileSelected, m_packageStageReplace);
	set("package.stageRename", editable, m_packageStageRename);
	set("package.stageDelete", editable, m_packageStageDelete);
	set("package.saveAs", documentReady && m_packageStaging.summary().canSave, m_packageStageSaveAs);
	set("package.unstageLast", documentReady && m_packageStaging.canUndo(), m_packageUndo);
	set("package.redo", documentReady && m_packageStaging.canRedo(), m_packageRedo);
	set("package.saveDraft", documentReady, m_packageDraftSave);
	set("package.saveDraftAs", documentReady);
	set("package.compare", packageReady);
	set("package.validate", packageReady, m_packageValidate);
	set("package.reviewChanges", documentReady, m_packageReview);
	set("package.groups", documentReady && m_packageStaging.sourceFormat() == PackageArchiveFormat::Wad, m_packageWadGroups);
	if (m_packageWriteManifest) { m_packageWriteManifest->setEnabled(documentReady); }
	if (m_packageUndo) { m_packageUndo->setToolTip(tr("Undo: %1").arg(m_packageStaging.undoLabel())); }
	if (m_packageRedo) { m_packageRedo->setToolTip(tr("Redo: %1").arg(m_packageStaging.redoLabel())); }
	const bool folderEditable = documentReady && m_packageTree && m_packageTree->readyFor(packageViewKey()) && !m_packageTree->selectedFolder().isEmpty();
	if (m_packageFolderRename) { m_packageFolderRename->setEnabled(folderEditable); }
	if (m_packageFolderDelete) { m_packageFolderDelete->setEnabled(folderEditable); }
}

void ApplicationShell::refreshCommandEnablement()
{
	UiRefreshTiming timing(__func__);
	if (!m_commands) {
		return;
	}
	const bool hasProject = !m_settings.currentProjectPath().isEmpty();
	const bool hasMap = m_levelMapDocument.format != LevelMapFormat::Unknown;
	const bool hasSelection = m_levelMapDocument.selectionKind != LevelMapSelectionKind::None;

	m_commands->setProjectAvailable(hasProject);
	refreshPackageCommandEnablement();
	m_commands->setEnabled(QStringLiteral("model.export"), m_modelMesh.geometryAvailable && !m_modelExportRunning);
	if (m_modelExport) { m_modelExport->setEnabled(m_modelMesh.geometryAvailable && !m_modelExportRunning); }
	refreshAudioTransport();
	m_commands->setEnabled(QStringLiteral("map.saveAs"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.save"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.close"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.exportImage"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.editProperty"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.moveSelection"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.addEntity"), m_levelMapDocument.format == LevelMapFormat::QuakeMap
		|| m_levelMapDocument.format == LevelMapFormat::Quake3Map);
	m_commands->setEnabled(QStringLiteral("map.addBrush"), m_levelMapDocument.format == LevelMapFormat::QuakeMap
		|| m_levelMapDocument.format == LevelMapFormat::Quake3Map);
	m_commands->setEnabled(QStringLiteral("map.addPatch"), m_levelMapDocument.format == LevelMapFormat::Quake3Map);
	m_commands->setEnabled(QStringLiteral("map.stitchPatches"), m_levelMapDocument.format == LevelMapFormat::Quake3Map && m_levelMapDocument.patches.size() >= 2);
	m_commands->setEnabled(QStringLiteral("map.capPatch"), m_levelMapDocument.format == LevelMapFormat::Quake3Map && !m_levelMapDocument.patches.isEmpty());
	m_commands->setEnabled(QStringLiteral("map.editBrushComponents"), m_levelMapDocument.selectionKind == LevelMapSelectionKind::QuakeBrush);
	m_commands->setEnabled(QStringLiteral("map.alignSurfaces"), !levelMapSelectedSurfaces(m_levelMapDocument).isEmpty());
	refreshLevelSurfaceTools();
	m_commands->setEnabled(QStringLiteral("map.editPatch"), m_levelMapDocument.format == LevelMapFormat::Quake3Map
		&& m_levelMapDocument.selectionKind == LevelMapSelectionKind::QuakePatch);
	m_commands->setEnabled(QStringLiteral("map.addThing"), m_levelMapDocument.format == LevelMapFormat::DoomWad
		&& m_levelMapDocument.doomFormat != LevelMapDoomFormat::Udmf);
	m_commands->setEnabled(QStringLiteral("map.selectSimilar"), hasMap && !similarLevelMapObjectsLabel().isEmpty());
	m_commands->setEnabled(QStringLiteral("map.selectByTexture"), hasMap && !m_levelMapDocument.textureReferences.isEmpty());
	m_commands->setEnabled(QStringLiteral("map.snapToGrid"), hasMap && hasSelection);
	const bool textMapOpen = m_levelMapDocument.format == LevelMapFormat::QuakeMap || m_levelMapDocument.format == LevelMapFormat::Quake3Map;
	m_commands->setEnabled(QStringLiteral("map.exportPrefab"), textMapOpen && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.stagePrefab"), textMapOpen && hasSelection && m_packageStaging.isLoaded()
		&& m_packageStaging.sourceFormat() != PackageArchiveFormat::Wad && !m_packageSaveRunning && !m_packageReadRunning && !m_packageExtractionRunning);
	m_commands->setEnabled(QStringLiteral("map.insertPrefab"), textMapOpen);
	m_commands->setEnabled(QStringLiteral("map.textureLock"), textMapOpen);
	m_commands->setEnabled(QStringLiteral("map.textureScaleLock"), textMapOpen);
	m_commands->setEnabled(QStringLiteral("map.allowValve220"), textMapOpen);
	m_commands->action(QStringLiteral("map.textureLock"))->setChecked(m_settings.levelTextureLock());
	m_commands->action(QStringLiteral("map.textureScaleLock"))->setChecked(m_settings.levelTextureScaleLock());
	m_commands->action(QStringLiteral("map.allowValve220"))->setChecked(m_settings.levelAllowValve220());
	m_commands->setEnabled(QStringLiteral("map.copySelection"), textMapOpen && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.cutSelection"), textMapOpen && levelMapSelectionIsDeletable(m_levelMapDocument));
	m_commands->setEnabled(QStringLiteral("map.paste"), textMapOpen);
	m_commands->setEnabled(QStringLiteral("map.pasteWithOffset"), textMapOpen);
	m_commands->setEnabled(QStringLiteral("map.duplicateWithOffset"), hasMap && levelMapSelectionIsDuplicable(m_levelMapDocument));
	m_commands->setEnabled(QStringLiteral("map.hideSelection"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.rotateLeft"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.rotatePrecisely"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.udmfProperties"), hasMap && m_levelMapDocument.doomUdmf != nullptr);
	m_commands->setEnabled(QStringLiteral("map.rotateRight"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.flipHorizontal"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.flipVertical"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.selectConnectedGeometry"), hasMap && m_levelMapDocument.format == LevelMapFormat::DoomWad &&
		std::any_of(m_levelMapDocument.selection.cbegin(), m_levelMapDocument.selection.cend(), [](const auto& ref) {
			return ref.kind == LevelMapSelectionKind::DoomVertex || ref.kind == LevelMapSelectionKind::DoomLinedef || ref.kind == LevelMapSelectionKind::DoomSector;
		}));
	m_commands->setEnabled(QStringLiteral("map.resizeSelection"), hasMap && levelMapSelectionResizable());
	m_commands->setEnabled(QStringLiteral("map.showAll"), hasMap && m_levelMapViewport && m_levelMapViewport->hiddenCount() > 0);
	m_commands->setEnabled(QStringLiteral("map.saveView"), hasMap && !m_settings.isReadOnly() && m_levelBookmarks.size() < LevelBookmarkLimit);
	for (const auto& id : {QStringLiteral("map.linkPlanCenters"), QStringLiteral("map.linkPlanZoom"), QStringLiteral("map.followCamera")}) {
		m_commands->setEnabled(id, hasMap && !m_settings.isReadOnly());
	}
	m_commands->setEnabled(QStringLiteral("map.centerPlansOnCamera"), hasMap && m_levelMap3D && m_levelMap3D->isEnabled() && m_levelMap3D->hasMesh()
		&& m_levelMap3DSource == QString::number(m_levelMapLoadSerial));
	m_commands->setEnabled(QStringLiteral("map.manageViews"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.nextSavedView"), hasMap && !m_levelBookmarks.isEmpty());
	m_commands->setEnabled(QStringLiteral("map.previousSavedView"), hasMap && !m_levelBookmarks.isEmpty());
	m_commands->setEnabled(QStringLiteral("map.gridSmaller"), hasMap && m_levelMapGrid && m_levelMapGrid->currentIndex() > 0);
	m_commands->setEnabled(QStringLiteral("map.toggle3D"), hasMap);
	refreshLevelViewWorkspaceActions();
	const bool previewShowing = hasMap && levelMap3DShowing();
	m_commands->setEnabled(QStringLiteral("map.previewWireframe"), previewShowing);
	if (QAction* wireframe = m_commands->action(QStringLiteral("map.previewWireframe"))) {
		wireframe->setChecked(m_levelMap3D && m_levelMap3D->renderMode() == ModelViewportRenderMode::Wireframe);
	}
	if (m_levelMap3DButton) {
		m_levelMap3DButton->setEnabled(hasMap);
	}
	if (!hasMap && levelMap3DShowing()) {
		// With the map closed there is nothing to orbit.
		QMetaObject::invokeMethod(this, [this]() {
			// A map can load before this queued startup refresh is delivered.
			if (m_levelMapDocument.format == LevelMapFormat::Unknown && levelMap3DShowing()) {
				setLevelMap3D(false);
			}
		}, Qt::QueuedConnection);
	}
	const bool quakeFamilyMap = m_levelMapDocument.format == LevelMapFormat::QuakeMap || m_levelMapDocument.format == LevelMapFormat::Quake3Map;
	m_commands->setEnabled(QStringLiteral("map.clipTool"), quakeFamilyMap);
	if (QAction* tool = m_commands->action(QStringLiteral("map.clipTool"))) {
		// Loading a map turns the tool off behind a signal blocker, so the check
		// is read back from the viewport rather than left to the signal.
		tool->setChecked(m_levelMapViewport && m_levelMapViewport->clipMode());
	}
	m_commands->setEnabled(QStringLiteral("map.applyTexture"), quakeFamilyMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.paintMaterial"), quakeFamilyMap || levelMapDoomEditable());
	m_commands->setEnabled(QStringLiteral("map.drawBrush"), quakeFamilyMap);
	m_commands->setEnabled(QStringLiteral("map.sampleMaterial"), quakeFamilyMap || levelMapDoomEditable());
	m_commands->setEnabled(QStringLiteral("map.selectAll"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.selectMatching"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.selectNone"), hasMap && hasSelection);
	m_commands->setEnabled(QStringLiteral("map.invertSelection"), hasMap);
	m_commands->setEnabled(QStringLiteral("map.clipSelection"), quakeFamilyMap && levelMapSelectionClippable());
	m_commands->setEnabled(QStringLiteral("map.hollowSelection"), quakeFamilyMap && levelMapSelectionClippable());
	m_commands->setEnabled(QStringLiteral("map.carve"), quakeFamilyMap && levelMapSelectionClippable());
	m_commands->setEnabled(QStringLiteral("map.mergeBrushes"), quakeFamilyMap && levelMapSelectionClippable());
	refreshLevelEditingCommands();
	m_commands->setEnabled(QStringLiteral("map.drawSector"), levelMapDoomEditable());
	if (QAction* tool = m_commands->action(QStringLiteral("map.drawSector"))) {
		tool->setChecked(m_levelMapViewport && m_levelMapViewport->drawMode());
	}
	m_commands->setEnabled(QStringLiteral("map.addSector"), levelMapDoomEditable());
	m_commands->setEnabled(QStringLiteral("map.joinSectors"), levelMapSelectedSectorCount() >= 2);
	m_commands->setEnabled(QStringLiteral("map.connectEntities"), quakeFamilyMap && m_levelMapDocument.selection.size() >= 2);
	// On a Doom map the links are tags: lines to the sectors they act on.
	const bool linkedMap = quakeFamilyMap || levelMapDoomEditable();
	m_commands->setEnabled(QStringLiteral("map.selectTargets"), linkedMap && !levelMapLinkedEntities(m_levelMapDocument, true).isEmpty());
	m_commands->setEnabled(QStringLiteral("map.selectSources"), linkedMap && !levelMapLinkedEntities(m_levelMapDocument, false).isEmpty());
	m_commands->setEnabled(QStringLiteral("map.mergeSectors"), levelMapSelectedSectorCount() >= 2);
	m_commands->setEnabled(QStringLiteral("map.makeDoor"), levelMapDoomEditable() && levelMapSelectedSectorCount() >= 1);
	for (const char* id : {"map.raiseFloor", "map.lowerFloor", "map.raiseCeiling", "map.lowerCeiling", "map.brighten", "map.darken"}) {
		m_commands->setEnabled(QString::fromLatin1(id), levelMapDoomEditable() && levelMapSelectedSectorCount() >= 1);
	}
	for (const char* id : {"map.gradientFloors", "map.gradientCeilings", "map.gradientLight"}) {
		m_commands->setEnabled(QString::fromLatin1(id), levelMapDoomEditable() && levelMapSelectedSectorCount() >= 3);
	}
	m_commands->setEnabled(QStringLiteral("map.mergeVertices"), levelMapDoomEditable()
		&& std::count_if(m_levelMapDocument.selection.cbegin(), m_levelMapDocument.selection.cend(), [](const LevelMapSelectionRef& ref) {
			   return ref.kind == LevelMapSelectionKind::DoomVertex;
		   }) >= 2);
	m_commands->setEnabled(QStringLiteral("map.splitLinedefs"), levelMapSelectionHasLinedefs());
	m_commands->setEnabled(QStringLiteral("map.flipLinedefs"), levelMapSelectionHasLinedefs());
	m_commands->setEnabled(QStringLiteral("map.gridLarger"), hasMap && m_levelMapGrid && m_levelMapGrid->currentIndex() < m_levelMapGrid->count() - 1);
	m_commands->setEnabled(QStringLiteral("map.replaceTexture"), hasMap && !m_levelMapDocument.textureReferences.isEmpty()
		&& !(m_levelMapDocument.format == LevelMapFormat::DoomWad && m_levelMapDocument.doomFormat == LevelMapDoomFormat::Udmf));
	m_commands->setEnabled(QStringLiteral("map.deleteSelection"), hasMap && levelMapSelectionIsDeletable(m_levelMapDocument));
	// What can be deleted can be copied, but for a Doom map's geometry, which
	// is drawn: entities other than worldspawn, brushes, patches, and things.
	m_commands->setEnabled(QStringLiteral("map.duplicateSelection"), hasMap && levelMapSelectionIsDuplicable(m_levelMapDocument));
	m_commands->setEnabled(QStringLiteral("map.undo"), hasMap && !m_levelMapDocument.undoStack.isEmpty());
	m_commands->setEnabled(QStringLiteral("map.redo"), hasMap && !m_levelMapDocument.redoStack.isEmpty());
	// Point files come from Quake-family compilers; Doom node builders write none.
	m_commands->setEnabled(QStringLiteral("map.loadLeakTrail"), m_levelMapDocument.format == LevelMapFormat::QuakeMap
		|| m_levelMapDocument.format == LevelMapFormat::Quake3Map);
	m_commands->setEnabled(QStringLiteral("map.clearLeakTrail"), !m_leakTrailPath.isEmpty());
	m_commands->setEnabled(QStringLiteral("map.loadPortals"), m_levelMapDocument.format == LevelMapFormat::QuakeMap
		|| m_levelMapDocument.format == LevelMapFormat::Quake3Map);
	m_commands->setEnabled(QStringLiteral("map.clearPortals"), !m_levelPortalPath.isEmpty());
	m_commands->setEnabled(QStringLiteral("code.save"), hasCodeDocument() && (m_codeDirty || m_codeFilePath.isEmpty()) && m_codeEditor && !m_codeEditor->isReadOnly());
	m_commands->setEnabled(QStringLiteral("code.saveAs"), hasCodeDocument() && m_codeTabs.at(m_codeTab).source.editable());
	m_commands->setEnabled(QStringLiteral("code.goToLine"), hasCodeDocument());
	m_commands->setEnabled(QStringLiteral("code.goToSymbol"), !m_codeFilePath.isEmpty());
	m_commands->setEnabled(QStringLiteral("code.findNext"), hasCodeDocument());
	m_commands->setEnabled(QStringLiteral("code.replace"), hasCodeDocument() && m_codeEditor && !m_codeEditor->isReadOnly());
	m_commands->setEnabled(QStringLiteral("code.findPrevious"), hasCodeDocument());
	const bool editable = hasCodeDocument() && m_codeEditor && !m_codeEditor->isReadOnly();
	for (const char* id : {"code.toggleComment", "code.duplicateLines", "code.moveLinesUp", "code.moveLinesDown"}) {
		m_commands->setEnabled(QString::fromLatin1(id), editable);
	}
	m_commands->setEnabled(QStringLiteral("code.closeFile"), m_codeTab >= 0);
	m_commands->setEnabled(QStringLiteral("code.nextFile"), m_codeTabs.size() > 1);
	m_commands->setEnabled(QStringLiteral("code.previousFile"), m_codeTabs.size() > 1);
	m_commands->setEnabled(QStringLiteral("activity.cancel"), m_compilerRunThread != nullptr || m_buildPipelineThread != nullptr
		|| m_packageReadRunning || m_packageExtractionRunning || m_packageSaveRunning || (m_packageCompareDialog && m_packageCompareDialog->property("operationRunning").toBool())
		|| (m_packageValidationDialog && m_packageValidationDialog->property("operationRunning").toBool()));
	m_commands->setEnabled(QStringLiteral("ai.explainBuild"), !m_lastBuildResult.stages.isEmpty());
	m_commands->setEnabled(QStringLiteral("ai.askAboutCode"), !m_codeFilePath.isEmpty());
	if (m_buildExplain) {
		m_buildExplain->setEnabled(!m_lastBuildResult.stages.isEmpty());
	}
	m_commands->setEnabled(QStringLiteral("build.runPipeline"), m_buildPipelineThread == nullptr);
	m_commands->setEnabled(QStringLiteral("build.runAndLaunch"), m_buildPipelineThread == nullptr && (!preparedLevelBuildWorkspaceActive() || preparedLevelBuildCanLaunch()));
	const bool canPrepareBuild = m_buildPipelineThread == nullptr && (m_levelMapDocument.format == LevelMapFormat::Quake3Map || m_levelMapDocument.format == LevelMapFormat::QuakeMap)
		&& (m_packageStaging.isLoaded() || m_packageArchive.isOpen());
	m_commands->setEnabled(QStringLiteral("build.prepareWorkspace"), canPrepareBuild);
	m_commands->setEnabled(QStringLiteral("build.openWorkspaceAssets"), preparedLevelBuildWorkspaceActive() && !m_buildPipelineThread
		&& !m_packageReadRunning && !m_packageExtractionRunning && !m_packageSaveRunning);
	m_commands->setEnabled(QStringLiteral("build.addToPackage"), !preparedLevelBuildWorkspaceActive() && !m_buildPipelineThread);
	m_commands->setEnabled(QStringLiteral("build.publishPrepared"), preparedLevelBuildWorkspaceActive() && !m_buildPipelineThread);
	m_commands->setEnabled(QStringLiteral("build.deployPrepared"), preparedLevelBuildWorkspaceActive() && !m_buildPipelineThread && preparedLevelBuildCanLaunch());
	if (auto* button = findChild<QToolButton*>(QStringLiteral("buildPrepareWorkspace"))) { button->setEnabled(canPrepareBuild); }
	m_commands->setEnabled(QStringLiteral("compiler.run"), m_compilerRunThread == nullptr);
	refreshLevelCameraPlacementTools();
	refreshSurfaceStates();
	scheduleStatusChipRefresh();
}

// ---------------------------------------------------------------------------
// Window events
// ---------------------------------------------------------------------------

void ApplicationShell::closeEvent(QCloseEvent* event)
{
	if (m_modelAssemblyDialog && m_modelAssemblyDialog->operationBusy()) {
		m_modelAssemblyDialog->requestClose([guard = QPointer<ApplicationShell>(this)]() { if (guard) { guard->close(); } });
		event->ignore(); return;
	}
	if (m_modelExportRunning) {
		m_closeAfterModelExport = true;
		if (m_cancelModelExport) { m_cancelModelExport(); }
		event->ignore();
		return;
	}
	if (m_modelEditorDialog && m_modelEditorDialog->operationBusy()) {
		m_modelEditorDialog->requestClose([guard = QPointer<ApplicationShell>(this)]() {
			if (guard) { guard->close(); }
		});
		event->ignore();
		return;
	}
	if (m_packageReadRunning) {
		if (auto* dialog = qobject_cast<QDialog*>(QApplication::activeModalWidget())) { dialog->close(); }
		event->ignore();
		return;
	}
	if (m_audioEditorDialog && !m_audioEditorDialog->close()) { event->ignore(); return; }
	if (m_audioSessionDialog && !m_audioSessionDialog->close()) { event->ignore(); return; }
	if (m_packageSaveRunning) {
		if (m_packageSaveDialog) { m_packageSaveDialog->close(); }
		event->ignore();
		return;
	}
	if (m_textureEditorDialog && !m_textureEditorDialog->requestClose([this]() { QTimer::singleShot(0, this, [this]() { close(); }); })) { event->ignore(); return; }
	if (m_modelDesignDialog && !m_modelDesignDialog->close()) { event->ignore(); return; }
	if (m_modelEditorDialog && !m_modelEditorDialog->close()) { event->ignore(); return; }
	if (m_modelAssemblyDialog && !m_modelAssemblyDialog->close()) { event->ignore(); return; }
	if (m_packageExtractionRunning) {
		// Ask the extraction to stop; the window can close once it has.
		m_packageExtractionCancelRequested = true;
		statusBar()->showMessage(tr("Stopping the package extraction. Close again once it has finished."));
		event->ignore();
		return;
	}
	if (!confirmCodeTabsHandled(tr("Save before closing?"))) {
		event->ignore();
		return;
	}
	if (!confirmLevelMapEditsHandled(tr("Save before closing?"))) {
		event->ignore();
		return;
	}
	if (!confirmStagedPackageChangesHandled()) { event->ignore(); return; }
	saveShellState();
	// What is open now is the session the next start reopens: only a working
	// session records one, and not while a crashed one is still on offer or
	// another studio owns the record.
	if (m_recordingSession && !m_sessionOfferPending && !m_secondaryInstance) {
		StudioSession session = currentSession();
		// A restart to change the language hands the session to the studio it
		// starts, which looks before this process has finished exiting.
		if (m_restartPending) {
			session.ownerProcessId = 0;
		}
		m_settings.setLastSession(session);
	}
	if (m_restartPending) {
		m_settings.sync();
	}
	retireLevelRecovery();
	m_packageRecoveryClosing = true;
	retirePackageRecovery();
	m_codeRecoveryClosing = true;
	for (int index = 0; index < m_codeTabs.size(); ++index) { retireCodeRecovery(index); }
	m_settings.sync();
	QMainWindow::closeEvent(event);
}

void ApplicationShell::restoreLastSession()
{
	if (!m_settings.restoreSession()) {
		return;
	}
	reopenSession(m_settings.lastSession());
}

void ApplicationShell::reopenSession(const StudioSession& session, const std::function<bool()>& packageReviewed, const std::function<bool()>& mapReviewed)
{
	if (session.isEmpty()) {
		return;
	}
	// What reopening opens is not a place the user went to.
	const bool wasRestoring = m_restoringPlace;
	m_restoringPlace = true;
	const auto quiet = qScopeGuard([this, wasRestoring]() {
		m_restoringPlace = wasRestoring;
	});
	const StudioMode mode = currentMode();
	QStringList reopened;
	int missing = 0;
	int failed = 0;
	int kept = 0;
	const auto present = [&missing](const QString& path) {
		if (path.isEmpty()) {
			return false;
		}
		if (!QFileInfo::exists(path)) {
			++missing;
			return false;
		}
		return true;
	};
	// Each is named only once it is open; one that failed says why itself.
	// Work in progress is asked about first, as any open is: the crash offer
	// can be taken long after the studio started.
	const bool packageOpen = m_packageArchive.isOpen() && sameFilePath(packageOpenPath(), session.packagePath);
	if (present(session.packagePath) && !packageOpen && !(packageReviewed && packageReviewed()) && !confirmStagedPackageChangesHandled()) {
		++kept;
	} else if (!session.packagePath.isEmpty() && QFileInfo::exists(session.packagePath)) {
		if (!packageOpen) {
			loadPackagePath(session.packagePath);
		}
		if (m_packageArchive.isOpen() && sameFilePath(packageOpenPath(), session.packagePath)) {
			reopened << QFileInfo(session.packagePath).fileName();
		} else {
			++failed;
		}
	}
	const bool mapOpen = m_levelMapDocument.format != LevelMapFormat::Unknown && sameFilePath(m_levelMapDocument.sourcePath, session.mapPath)
		&& (session.mapName.isEmpty() || m_levelMapDocument.mapName.compare(session.mapName, Qt::CaseInsensitive) == 0);
	if (present(session.mapPath) && !mapOpen && !(mapReviewed && mapReviewed()) && !confirmLevelMapEditsHandled(tr("Save before reopening the last session's map?"))) {
		++kept;
	} else if (!session.mapPath.isEmpty() && QFileInfo::exists(session.mapPath) && mapOpen) {
		reopened << (session.mapName.isEmpty() ? QFileInfo(session.mapPath).fileName() : tr("%1 in %2").arg(session.mapName, QFileInfo(session.mapPath).fileName()));
	} else if (!session.mapPath.isEmpty() && QFileInfo::exists(session.mapPath)) {
		if (m_levelMapName) {
			// A WAD reopens on the map that was open, if it still holds it.
			const bool held = !session.mapName.isEmpty() && levelMapNamesInWad(session.mapPath).contains(session.mapName, Qt::CaseInsensitive);
			m_levelMapName->setCurrentText(held ? session.mapName : QString());
		}
		loadLevelMapPath(session.mapPath);
		if (m_levelMapDocument.format != LevelMapFormat::Unknown && sameFilePath(m_levelMapDocument.sourcePath, session.mapPath)) {
			// The map that did open: a WAD that no longer holds the recorded
			// one opens on another.
			const QString opened = m_levelMapDocument.format == LevelMapFormat::DoomWad ? m_levelMapDocument.mapName : QString();
			reopened << (opened.isEmpty() ? QFileInfo(session.mapPath).fileName() : tr("%1 in %2").arg(opened, QFileInfo(session.mapPath).fileName()));
		} else {
			++failed;
		}
	}
	int files = 0;
	for (const QString& path : session.codeFiles) {
		if (!present(path)) {
			continue;
		}
		if (openCodeFile(path)) {
			++files;
		} else {
			++failed;
		}
	}
	if (const int current = codeTabIndexOf(session.currentCodeFile); current >= 0) {
		activateCodeTab(current);
	}
	if (files > 0) {
		reopened << tr("%n code file(s)", nullptr, files);
	}
	// Opening things switches pages; the page the studio closed on stays.
	setMode(mode);
	QStringList sentences;
	if (!reopened.isEmpty()) {
		sentences << tr("Reopened the last session: %1.").arg(reopened.join(tr(", ")));
	}
	if (missing > 0) {
		sentences << tr("%n file(s) from the last session could not be found.", nullptr, missing);
	}
	if (failed > 0) {
		sentences << tr("%n file(s) from the last session could not be opened.", nullptr, failed);
	}
	if (kept > 0) {
		sentences << tr("%n file(s) from the last session were left closed, to keep the work open now.", nullptr, kept);
	}
	if (!sentences.isEmpty()) {
		statusBar()->showMessage(sentences.join(QLatin1Char(' ')));
	}
}

bool ApplicationShell::eventFilter(QObject* watched, QEvent* event)
{
	if (watched == m_levelMap3D && m_levelTextureDragMode && handleLevelTextureDragEvent(event)) {
		return true;
	}
	if (event->type() == QEvent::FocusIn || event->type() == QEvent::MouseButtonPress) {
		if (watched == m_levelMap3D && !m_applyingLevelViewLayout) { m_levelLastFocusedView = m_levelMap3D; }
		for (auto* view : m_levelPlanViews) {
			if (watched == view) { activateLevelPlanViewport(view); break; }
		}
	}
	if (watched == m_assistantPrompt && (event->type() == QEvent::KeyPress || event->type() == QEvent::ShortcutOverride)) {
		const auto* keyEvent = static_cast<QKeyEvent*>(event);
		const bool send = (keyEvent->key() == Qt::Key_Return || keyEvent->key() == Qt::Key_Enter) && keyEvent->modifiers().testFlag(Qt::ControlModifier);
		const bool stop = keyEvent->key() == Qt::Key_Escape && m_assistantClient && m_assistantClient->busy();
		if (send || stop) {
			event->accept();
			if (event->type() == QEvent::KeyPress) {
				if (send) {
					sendAssistantQuestion();
				} else {
					cancelAssistantQuestion();
				}
			}
			return true;
		}
	}
	if (watched == m_codeTabBar && event->type() == QEvent::MouseButtonRelease) {
		const auto* mouse = static_cast<QMouseEvent*>(event);
		const int index = mouse->button() == Qt::MiddleButton ? m_codeTabBar->tabAt(mouse->position().toPoint()) : -1;
		if (index >= 0) {
			closeCodeTab(index);
			return true;
		}
	}
	// Delete in the inspector removes the key on the current row; it never
	// reaches the page's Delete Selection, which would take the whole entity.
	if (watched == m_entityInspector && event->type() == QEvent::ShortcutOverride) {
		const auto* keyEvent = static_cast<QKeyEvent*>(event);
		if (keyEvent->key() == Qt::Key_Delete || keyEvent->matches(QKeySequence::Copy) || keyEvent->matches(QKeySequence::Cut)
			|| keyEvent->matches(QKeySequence::Paste)) {
			event->accept();
			return true;
		}
	}
	// Ctrl+C in the inspector copies the current key as a "key" "value" line;
	// cutting or pasting whole map objects from here would surprise.
	if (watched == m_entityInspector && event->type() == QEvent::KeyPress) {
		const auto* keyEvent = static_cast<QKeyEvent*>(event);
		if (keyEvent->matches(QKeySequence::Copy)) {
			const QTreeWidgetItem* item = m_entityInspector->currentItem();
			const QString key = item ? item->data(0, Qt::UserRole).toString() : QString();
			if (!key.isEmpty()) {
				QGuiApplication::clipboard()->setText(QStringLiteral("\"%1\" \"%2\"").arg(key, item->text(1)));
				statusBar()->showMessage(tr("Copied %1.").arg(key));
			} else if (item && !item->data(0, kFieldPathRole).toString().isEmpty()) {
				// A Doom or face field has no key to quote: its value is copied.
				const QString value = item->flags().testFlag(Qt::ItemIsUserCheckable)
					? (item->checkState(0) == Qt::Checked ? tr("on") : tr("off"))
					: item->text(1);
				QGuiApplication::clipboard()->setText(value);
				statusBar()->showMessage(tr("Copied %1: %2.").arg(item->text(0), value));
			}
			return true;
		}
		// Space toggles a flag row from either column: its check box is in
		// column 0, where a plain tree would want the current cell to be.
		if (keyEvent->key() == Qt::Key_Space && keyEvent->modifiers() == Qt::NoModifier) {
			QTreeWidgetItem* item = m_entityInspector->currentItem();
			if (item && item->flags().testFlag(Qt::ItemIsUserCheckable) && m_entityInspector->currentColumn() != 0) {
				item->setCheckState(0, item->checkState(0) == Qt::Checked ? Qt::Unchecked : Qt::Checked);
				return true;
			}
		}
		if (keyEvent->matches(QKeySequence::Cut) || keyEvent->matches(QKeySequence::Paste)) {
			statusBar()->showMessage(tr("Edit a value with Enter or a double-click; cut and paste map objects from the view or the objects list."));
			return true;
		}
	}
	if (watched == m_entityInspector && event->type() == QEvent::KeyPress
		&& static_cast<QKeyEvent*>(event)->key() == Qt::Key_Delete) {
		removeEntityInspectorKey();
		return true;
	}
	// Enter on a property row edits its value, like a double-click. While an
	// editor is open it has focus, so its own Enter never reaches this filter.
	if (watched == m_entityInspector && event->type() == QEvent::KeyPress) {
		const auto* keyEvent = static_cast<QKeyEvent*>(event);
		if (keyEvent->key() == Qt::Key_Return || keyEvent->key() == Qt::Key_Enter) {
			QTreeWidgetItem* item = m_entityInspector->currentItem();
			if (item && item->flags().testFlag(Qt::ItemIsEditable)) {
				m_entityInspector->editItem(item, 1);
				return true;
			}
			if (item && !item->data(0, Qt::UserRole + 5).toString().isEmpty()) {
				openCodeFileAt(item->data(0, Qt::UserRole + 5).toString(), item->data(0, Qt::UserRole + 6).toInt());
				return true;
			}
		}
	}
	if (watched == m_textureEntries && event->type() == QEvent::Resize) {
		fitTextureGrid();
	}
	if (((m_textureEntries && watched == m_textureEntries->viewport()) || (m_levelMapTextures && watched == m_levelMapTextures->viewport())) &&
		(event->type() == QEvent::Show || event->type() == QEvent::Hide || event->type() == QEvent::Resize || event->type() == QEvent::LayoutRequest)) {
		scheduleTextureThumbnails();
	}
	if (watched == m_packageTree && (event->type() == QEvent::ShortcutOverride || event->type() == QEvent::KeyPress)) {
		const auto* key = static_cast<QKeyEvent*>(event);
		if (key->modifiers() == Qt::NoModifier && (key->key() == Qt::Key_F2 || key->key() == Qt::Key_Delete)) {
			if (event->type() == QEvent::KeyPress) {
				const QString path = selectedPackageTreeEntryPath();
				if (!path.isEmpty()) { stagePackageFolder(key->key() == Qt::Key_F2, path, packageViewKey()); }
			}
			event->accept(); return true;
		}
	}
	// Delete in the staging list takes the selected changes out of the plan.
	if (watched == m_packageStagingSummary && event->type() == QEvent::KeyPress) {
		const auto* keyEvent = static_cast<QKeyEvent*>(event);
		if (keyEvent->key() == Qt::Key_Delete || keyEvent->key() == Qt::Key_Backspace) {
			const QStringList ids = m_packageStagingSummary->selectedOperationIds();
			if (!ids.isEmpty()) {
				unstagePackageOperations(ids);
				return true;
			}
		}
	}
	if (watched == m_packageStagingSummary && event->type() == QEvent::ShortcutOverride) {
		const auto* keyEvent = static_cast<QKeyEvent*>(event);
		if (keyEvent->key() == Qt::Key_Delete) {
			// The list's own Delete means unstage, not the page's stage-delete.
			event->accept();
			return true;
		}
	}
	return QMainWindow::eventFilter(watched, event);
}

void ApplicationShell::fitTextureGrid()
{
	if (!m_textureEntries || !m_textureTileMode || m_textureEntries->viewMode() != QListView::IconMode) {
		return;
	}
	// Tiles share the row evenly instead of leaving a ragged gap on the right.
	// The scroll bar's width is reserved whether or not it shows, so it
	// appearing can never change the column count that decides whether it
	// appears.
	const QSize tile = scaledIconSize(QSize(88, 88));
	const int minimumCell = tile.width() + 20;
	const int spacing = m_textureEntries->spacing();
	const int available = m_textureEntries->width() - 2 * m_textureEntries->frameWidth()
		- m_textureEntries->style()->pixelMetric(QStyle::PM_ScrollBarExtent, nullptr, m_textureEntries) - spacing;
	const int columns = std::max(1, available / (minimumCell + spacing));
	const QSize grid(std::max(minimumCell, available / columns - spacing),
		tile.height() + m_textureEntries->fontMetrics().height() + 22);
	if (m_textureEntries->gridSize() != grid) {
		m_textureEntries->setGridSize(grid);
	}
}

void ApplicationShell::dragEnterEvent(QDragEnterEvent* event)
{
	// Entries dragged out of the list are the package's own copies.
	if (!event->mimeData()->hasUrls() || event->source() == m_packageEntries) {
		return;
	}
	for (const QUrl& url : event->mimeData()->urls()) {
		if (url.isLocalFile()) {
			event->acceptProposedAction();
			return;
		}
	}
}

void ApplicationShell::dragMoveEvent(QDragMoveEvent* event)
{
	if (!event->mimeData()->hasUrls() || event->source() == m_packageEntries) {
		event->ignore();
		return;
	}
	// Over an open package's entries a drop stages the files; say where.
	bool onPackage = false;
	const QString folder = packageDropFolderAt(event->position().toPoint(), &onPackage);
	if (onPackage) {
		statusBar()->showMessage(folder.isEmpty() ? tr("Drop to stage the files into the package root.")
							  : tr("Drop to stage the files into %1.").arg(folder), 2000);
	}
	event->acceptProposedAction();
}

QString ApplicationShell::packageDropFolderAt(const QPoint& windowPoint, bool* onPackage) const
{
	*onPackage = false;
	if (!m_packageStaging.isLoaded() || !m_packageArchive.isOpen() || currentMode() != StudioMode::Packages) {
		return {};
	}
	QWidget* target = childAt(windowPoint);
	for (QAbstractItemView* view : {static_cast<QAbstractItemView*>(m_packageEntries), static_cast<QAbstractItemView*>(m_packageTree)}) {
		if (!view || !view->isVisible() || !target || !(view == target || view->isAncestorOf(target))) {
			continue;
		}
		if (view == m_packageTree ? !m_packageTree->readyFor(packageViewKey()) : !m_packageEntries->readyFor(packageViewKey())) { return {}; }
		*onPackage = true;
		const QModelIndex index = view->indexAt(view->viewport()->mapFrom(this, windowPoint));
		const QString path = index.isValid() ? index.data(Qt::UserRole).toString() : QString();
		if (view == m_packageTree) {
			// The tree lists folders: the one under the pointer takes the files.
			return index.isValid() ? path : m_packageBrowseFolder;
		}
		// On a folder's row, into that folder; anywhere else in the list, into
		// the folder it shows.
		if (!path.isEmpty() && index.data(Qt::UserRole + 3).toBool()) { return path; }
		return m_packageBrowseFolder;
	}
	return {};
}

void ApplicationShell::stageDroppedFiles(const QStringList& paths, const QString& folder)
{
	if (m_packageReadRunning || m_packageSaveRunning || m_packageExtractionRunning) { return; }
	// A Doom WAD has no folders and names lumps in 8 characters; other
	// packages keep each file's name, and a dropped folder its layout.
	const bool doomWad = m_packageStaging.sourceFormat() == PackageArchiveFormat::Wad && !m_packageStaging.sourceWadMagic().startsWith(QStringLiteral("WAD"));
	const QString prefix = folder.isEmpty() || doomWad ? QString() : QDir::cleanPath(folder) + QLatin1Char('/');
	QVector<QPair<QString, QString>> plan;
	QStringList unnameable;
	constexpr int kLimit = 4000;
	// A lump name is at most 8 Latin-1 characters; a file that cannot be one
	// is left out now rather than failing Save As later.
	const auto add = [&plan, &unnameable, doomWad](const QString& file, const QString& virtualPath) {
		if (doomWad && (virtualPath.size() > 8 || QString::fromLatin1(virtualPath.toLatin1()) != virtualPath)) {
			unnameable << QFileInfo(file).fileName();
			return;
		}
		plan.push_back({file, virtualPath});
	};
	for (const QString& path : paths) {
		const QFileInfo info(path);
		if (info.isDir()) {
			QDirIterator files(path, QDir::Files | QDir::NoDotAndDotDot, QDirIterator::Subdirectories);
			while (files.hasNext() && plan.size() <= kLimit) {
				const QString file = files.next();
				add(file, doomWad ? QFileInfo(file).completeBaseName().toUpper()
						  : prefix + info.fileName() + QLatin1Char('/') + QDir(path).relativeFilePath(file));
			}
		} else if (info.isFile()) {
			add(path, doomWad ? info.completeBaseName().toUpper() : prefix + info.fileName());
		}
	}
	if (plan.isEmpty() && !unnameable.isEmpty()) {
		statusBar()->showMessage(tr("Nothing to stage: WAD lump names are at most 8 characters, and %1 is longer.").arg(unnameable.first()));
		return;
	}
	if (plan.isEmpty()) {
		statusBar()->showMessage(tr("Nothing to stage: the drop held no files."));
		return;
	}
	if (plan.size() > kLimit) {
		statusBar()->showMessage(tr("That drop holds more than %1 files; stage a smaller folder at a time.").arg(kLimit));
		return;
	}
	// One question for the whole drop, and only when something would clash.
	QSet<QString> existing;
	for (const PackageStagedEntry& entry : m_packageStaging.plannedEntries()) {
		existing.insert(entry.virtualPath.toCaseFolded());
	}
	// Two dropped files that land on one name clash with each other too.
	bool clashes = false;
	QSet<QString> planned;
	for (const auto& item : std::as_const(plan)) {
		const QString key = item.second.toCaseFolded();
		clashes = clashes || existing.contains(key) || planned.contains(key);
		planned.insert(key);
	}
	PackageStageConflictResolution resolution = PackageStageConflictResolution::Block;
	if (clashes && !choosePackageStageResolution(tr("Dropped Files Already In The Package"), &resolution)) {
		return;
	}
	QVector<PackageStageFileRequest> requests;
	for (const auto& [source, virtualPath] : plan) { requests.append({source, virtualPath, resolution}); }
	const auto result = stagePackageFilesWithProgress(requests);
	if (result.cancelled) { return; }
	const int staged = result.accepted;
	const QStringList failures = result.errors;
	refreshPackageStagingSummary();
	recordActivity(tr("Package Stage Add"), tr("%n dropped file(s)", nullptr, staged), tr("package"),
		failures.isEmpty() ? OperationState::Completed : OperationState::Warning,
		failures.isEmpty() ? tr("Files staged for save-as.") : failures.join(QLatin1Char('\n')));
	const QString where = doomWad || folder.isEmpty() ? tr("the package") : folder;
	QStringList sentences;
	sentences << (failures.isEmpty()
			? tr("Staged %n file(s) into %1.", nullptr, staged).arg(where)
			: tr("Staged %n file(s) into %1; %2 could not be staged, the first: %3", nullptr, staged).arg(where).arg(failures.size()).arg(failures.first()));
	if (!unnameable.isEmpty()) {
		sentences << tr("%n file(s) were left out because a WAD lump name is at most 8 characters.", nullptr, static_cast<int>(unnameable.size()));
	}
	// Staged is not saved: a clash still blocks Save As until it is resolved.
	const int blockers = m_packageStaging.summary().blockingCount;
	sentences << (blockers > 0 ? tr("%n clash(es) block Save As until resolved in the staging list.", nullptr, blockers) : tr("Save As writes them."));
	statusBar()->showMessage(sentences.join(QLatin1Char(' ')));
}

void ApplicationShell::dropEvent(QDropEvent* event)
{
	if (!event->mimeData()->hasUrls()) {
		return;
	}
	// Entries dragged out of the list and dropped back on the studio are the
	// package's own copies: nothing to stage or open.
	if (event->source() == m_packageEntries) {
		event->ignore();
		return;
	}
	// Onto an open package's entries the files are staged into it; anywhere
	// else they open.
	bool onPackage = false;
	const QString folder = packageDropFolderAt(event->position().toPoint(), &onPackage);
	if (onPackage) {
		QStringList paths;
		for (const QUrl& url : event->mimeData()->urls()) {
			if (url.isLocalFile()) {
				paths << url.toLocalFile();
			}
		}
		if (!paths.isEmpty()) {
			event->acceptProposedAction();
			stageDroppedFiles(paths, folder);
		}
		return;
	}
	int handled = 0;
	for (const QUrl& url : event->mimeData()->urls()) {
		if (!url.isLocalFile()) {
			continue;
		}
		openDroppedPath(url.toLocalFile());
		++handled;
	}
	if (handled > 0) {
		event->acceptProposedAction();
	}
}

void ApplicationShell::openDroppedPath(const QString& path)
{
	const QFileInfo info(path);
	if (!info.exists()) {
		statusBar()->showMessage(tr("Dropped path does not exist: %1").arg(nativePath(path)));
		return;
	}
	if (info.isFile() && info.suffix().compare(QStringLiteral("vibeworkspace"), Qt::CaseInsensitive) == 0) {
		QString error;
		if (!openWorkspaceFrom(info.absoluteFilePath(), &error)) { statusBar()->showMessage(error); }
		return;
	}
	if (info.isFile() && info.suffix().compare(QStringLiteral("vprefab"), Qt::CaseInsensitive) == 0) {
		showLevelPrefab(false, false, info.absoluteFilePath());
		return;
	}
	if (info.isFile() && (info.suffix().compare(QStringLiteral("vsaudio"), Qt::CaseInsensitive) == 0 ||
		info.suffix().compare(QStringLiteral("vssession"), Qt::CaseInsensitive) == 0 ||
		info.suffix().compare(QStringLiteral("vstake"), Qt::CaseInsensitive) == 0)) {
		showAudioEditor(false, info.absoluteFilePath());
		setMode(StudioMode::Audio);
		return;
	}
	if (info.isFile() && info.suffix().compare(QStringLiteral("vtexture"), Qt::CaseInsensitive) == 0) {
		showTextureEditor(false);
		m_textureEditorDialog->openFromPath(info.absoluteFilePath());
		setMode(StudioMode::Textures);
		return;
	}
	if (pathLooksLikeMap(path)) {
		if (!confirmLevelMapEditsHandled(tr("Save before opening %1?").arg(info.fileName()))) {
			return;
		}
		loadLevelMapPath(path);
		setMode(StudioMode::Levels);
		return;
	}
	if (info.isDir() && QFileInfo::exists(projectManifestPath(path))) {
		openProjectPath(path);
		setMode(StudioMode::Workspace);
		return;
	}
	if (pathLooksLikePackage(path)) {
		if (!confirmStagedPackageChangesHandled()) {
			return;
		}
		loadPackagePath(path);
		setMode(StudioMode::Packages);
		return;
	}
	// A loose texture, model, or sound would be noise in the code editor; it
	// opens on its own surface from its folder instead.
	if (const AssetPreviewKind kind = assetPreviewKindForPath(path);
		info.isFile() && (kind == AssetPreviewKind::Image || kind == AssetPreviewKind::Model || kind == AssetPreviewKind::Audio)) {
		showLooseAsset(path, kind);
		return;
	}
	const QString suffix = info.suffix().toLower();
	if ((suffix == QStringLiteral("def") || suffix == QStringLiteral("fgd") || suffix == QStringLiteral("ent")) && m_entityDefinitionPath) {
		m_entityDefinitionPath->setText(path);
		reloadEntityDefinitions();
		setMode(StudioMode::Levels);
		return;
	}
	if (info.suffix().compare(QStringLiteral("shader"), Qt::CaseInsensitive) == 0 && m_advancedShaderPath) {
		m_advancedShaderPath->setText(path);
		inspectAdvancedShaderScript();
		setMode(StudioMode::Shaders);
		return;
	}
	if (info.suffix().compare(QStringLiteral("mtr"), Qt::CaseInsensitive) == 0 && m_materialWorkbench) {
		openMaterialScript(path);
		setMode(StudioMode::Shaders);
		return;
	}
	openCodeFile(path);
	setMode(StudioMode::Code);
}

